        <div className="mt-8 flex justify-center space-x-4 text-sm font-medium">
          <span className="bg-white/20 px-3 py-1 rounded-full backdrop-blur-sm">CBE Aligned</span>
          <span className="bg-white/20 px-3 py-1 rounded-full backdrop-blur-sm">Grade 7-9</span>
