export default Header;

import React, { useState, useEffect, useMemo } from 'react';
import { Grade, Term, LessonDefinition, LessonPlanData } from '../types';
import { SCHEMES_OF_WORK } from '../data/schemes';
import { generateLessonPlan } from '../services/geminiService';
import { Loader2, BookOpen, AlertCircle } from 'lucide-react';

interface Props {
  onPlanGenerated: (data: LessonPlanData) => void;
}

const LessonGenerator: React.FC<Props> = ({ onPlanGenerated }) => {
  const [formData, setFormData] = useState({
    teacherName: '',
    schoolName: '',
    date: new Date().toISOString().split('T')[0],
    grade: Grade.GRADE_7,
    term: Term.TERM_1,
    roll: 40,
  });

  const [selectedStrand, setSelectedStrand] = useState<string>('');
  const [selectedSubStrand, setSelectedSubStrand] = useState<string>('');
  const [selectedLesson, setSelectedLesson] = useState<LessonDefinition | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Derived data based on Grade selection
  const gradeData = useMemo(() => SCHEMES_OF_WORK[formData.grade] || [], [formData.grade]);

  const strands = useMemo(() => {
    return Array.from(new Set(gradeData.map(l => l.strand)));
  }, [gradeData]);

  const subStrands = useMemo(() => {
    return Array.from(new Set(gradeData.filter(l => l.strand === selectedStrand).map(l => l.subStrand)));
  }, [gradeData, selectedStrand]);

  const lessons = useMemo(() => {
    return gradeData.filter(l => l.strand === selectedStrand && l.subStrand === selectedSubStrand);
  }, [gradeData, selectedStrand, selectedSubStrand]);

  // Reset downstream selections when upstream changes
  useEffect(() => { setSelectedStrand(''); setSelectedSubStrand(''); setSelectedLesson(null); }, [formData.grade]);
  useEffect(() => { setSelectedSubStrand(''); setSelectedLesson(null); }, [selectedStrand]);
  useEffect(() => { setSelectedLesson(null); }, [selectedSubStrand]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedLesson) {
        setError("Please select a specific lesson.");
        return;
    }
    setError(null);
    setLoading(true);

    try {
      const plan = await generateLessonPlan(formData, selectedLesson);
      onPlanGenerated(plan);
    } catch (err: any) {
      setError(err.message || "An error occurred generating the plan.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden no-print">
      <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex items-center gap-2">
        <BookOpen className="text-teal-600 w-5 h-5" />
        <h2 className="text-lg font-semibold text-gray-800">Lesson Plan Generator</h2>
      </div>

      <form onSubmit={handleSubmit} className="p-6 md:p-8 space-y-8">

        {/* Top Table-like Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">

            {/* Teacher & School */}
            <div className="space-y-4">
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Teacher</label>
                    <input 
                        required
                        type="text" 
                        value={formData.teacherName}
                        onChange={e => setFormData({...formData, teacherName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                        placeholder="Enter Name"
                    />
                </div>
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">School</label>
                    <input 
                        required
                        type="text" 
                        value={formData.schoolName}
                        onChange={e => setFormData({...formData, schoolName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                        placeholder="Enter School"
                    />
                </div>
            </div>

            {/* Date, Subject, Time */}
            <div className="space-y-4">
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Date</label>
                    <input 
                        type="date" 
                        value={formData.date}
                        onChange={e => setFormData({...formData, date: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                    />
                </div>
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Subject</label>
                    <div className="flex-1 py-2 px-3 bg-gray-100 rounded-md text-gray-700 font-medium border border-gray-200">
                        Mathematics
                    </div>
                </div>
            </div>
        </div>

        {/* Separator */}
        <div className="h-px bg-gray-200 w-full"></div>

        {/* Class Details Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Grade</label>
                <select 
                    value={formData.grade}
                    onChange={e => setFormData({...formData, grade: e.target.value as Grade})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Term</label>
                <select 
                    value={formData.term}
                    onChange={e => setFormData({...formData, term: e.target.value as Term})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Term).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
            </div>
             <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Roll (Class Size)</label>
                <input 
                    type="number"
                    value={formData.roll}
                    onChange={e => setFormData({...formData, roll: parseInt(e.target.value)})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                />
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Time</label>
                <div className="w-full py-2 px-3 bg-gray-100 rounded-md text-gray-700 border border-gray-200">
                    40 Minutes
                </div>
            </div>
        </div>

        {/* Cascading Content Selection */}
        <div className="bg-teal-50 p-6 rounded-lg border border-teal-100 space-y-6">
            <h3 className="text-teal-800 font-medium border-b border-teal-200 pb-2">Curriculum Content Selector</h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                    <label className="block text-sm font-medium text-teal-800 mb-2">Select Strand</label>
                    <select 
                        value={selectedStrand}
                        onChange={e => setSelectedStrand(e.target.value)}
                        className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                        disabled={strands.length === 0}
                    >
                        <option value="">-- Choose Strand --</option>
                        {strands.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>

                <div>
                    <label className="block text-sm font-medium text-teal-800 mb-2">Select Sub-strand</label>
                    <select 
                        value={selectedSubStrand}
                        onChange={e => setSelectedSubStrand(e.target.value)}
                        className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                        disabled={!selectedStrand}
                    >
                         <option value="">-- Choose Sub-strand --</option>
                         {subStrands.map(ss => <option key={ss} value={ss}>{ss}</option>)}
                    </select>
                </div>
            </div>

            <div>
                <label className="block text-sm font-medium text-teal-800 mb-2">Select Lesson</label>
                <select 
                    value={selectedLesson ? JSON.stringify(selectedLesson) : ""}
                    onChange={e => {
                        if(e.target.value) setSelectedLesson(JSON.parse(e.target.value));
                    }}
                    className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                    disabled={!selectedSubStrand}
                >
                     <option value="">-- Choose Lesson --</option>
                     {lessons.map((l, idx) => (
                        <option key={idx} value={JSON.stringify(l)}>{l.topic}</option>
                     ))}
                </select>
            </div>

            {selectedLesson && (
                 <div className="mt-4 p-4 bg-white/60 rounded border border-teal-200 text-sm text-teal-900">
                    <p><strong>Preview Learning Outcome:</strong> {selectedLesson.learningOutcomes[0]}</p>
                </div>
            )}
        </div>

        {error && (
            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded flex items-center gap-3">
                <AlertCircle className="text-red-500" />
                <p className="text-red-700">{error}</p>
            </div>
        )}

        {/* Actions */}
        <div className="flex gap-4 pt-2">
            <button 
                type="button" 
                className="px-6 py-3 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500"
                onClick={() => {
                   setFormData({...formData, teacherName: '', schoolName: ''});
                   setSelectedStrand('');
                }}
            >
                Reset Form
            </button>
            <button 
                type="submit" 
                disabled={loading || !selectedLesson}
                className="flex-1 flex justify-center items-center gap-2 px-6 py-3 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-teal-600 hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin h-5 w-5" />
                        Generating Plan with AI...
                    </>
                ) : (
                    "Generate Lesson Plan"
                )}
            </button>
        </div>

      </form>
    </div>
  );
};

export default LessonGenerator;

import React, { useRef } from 'react';
import { LessonPlanData } from '../types';
import { Printer, Download, ArrowLeft, Share2 } from 'lucide-react';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    // Simple text download implementation
    const element = document.createElement("a");
    const file = new Blob([document.getElementById("lesson-plan-content")?.innerText || ""], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `LessonPlan-${plan.date}-${plan.lessonNumber}.txt`;
    document.body.appendChild(element);
    element.click();
  };

  return (
    <div className="space-y-6">
      {/* Action Bar */}
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200 flex flex-wrap gap-4 justify-between items-center no-print">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors">
            <ArrowLeft className="w-5 h-5" />
            <span>Back to Generator</span>
        </button>

        <div className="flex gap-3">
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
                Print / PDF
            </button>
            <button 
                onClick={handleDownload}
                className="flex items-center gap-2 bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-md hover:bg-gray-50 transition-colors shadow-sm"
            >
                <Download className="w-4 h-4" />
                Download Text
            </button>
        </div>
      </div>

      {/* The Printable Lesson Plan */}
      <div id="lesson-plan-content" ref={componentRef} className="bg-white p-8 md:p-12 shadow-lg border border-gray-200 mx-auto max-w-4xl print:shadow-none print:border-none print:w-full print:max-w-none">

        {/* Header Table */}
        <div className="mb-8 border border-gray-800">
            <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                <div className="col-span-1 p-2 font-bold bg-gray-100">Teacher</div>
                <div className="col-span-2 p-2">{plan.teacherName}</div>
                <div className="col-span-1 p-2 font-bold bg-gray-100">School</div>
                <div className="col-span-2 p-2">{plan.schoolName}</div>
            </div>
             <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                <div className="col-span-1 p-2 font-bold bg-gray-100">Date</div>
                <div className="col-span-2 p-2">{plan.date}</div>
                 <div className="col-span-1 p-2 font-bold bg-gray-100">Subject</div>
                <div className="col-span-2 p-2">Mathematics</div>
            </div>
             <div className="grid grid-cols-8 divide-x divide-gray-800">
                <div className="col-span-1 p-2 font-bold bg-gray-100">Grade</div>
                <div className="col-span-1 p-2 text-center">{plan.grade}</div>
                <div className="col-span-1 p-2 font-bold bg-gray-100">Term</div>
                <div className="col-span-1 p-2 text-center">{plan.term}</div>
                <div className="col-span-1 p-2 font-bold bg-gray-100">Roll</div>
                <div className="col-span-1 p-2 text-center">{plan.roll}</div>
                <div className="col-span-1 p-2 font-bold bg-gray-100">Time</div>
                <div className="col-span-1 p-2 text-center">40 min</div>
            </div>
        </div>

        {/* Content Body */}
        <div className="space-y-6 text-gray-900 leading-relaxed">

            {/* Identification */}
            <div className="bg-slate-50 p-4 rounded border border-slate-200 print:bg-transparent print:border-none print:p-0">
                <p><span className="font-bold">Strand:</span> {plan.strand}</p>
                <p><span className="font-bold">Sub-strand:</span> {plan.subStrand}</p>
                <h2 className="font-bold text-lg mt-2 text-slate-800">{plan.lessonNumber}</h2>
            </div>

            {/* Outcomes */}
            <div>
                <h3 className="font-bold text-lg mb-2 text-teal-800 print:text-black">Specific Learning Outcomes</h3>
                <p className="mb-2 italic">By the end of the lesson, the learner should be able to:</p>
                <ul className="list-disc pl-5 space-y-1">
                    {plan.learningOutcomes.map((outcome, i) => (
                        <li key={i}>{outcome}</li>
                    ))}
                </ul>
            </div>

            {/* Inquiry */}
             <div>
                <h3 className="font-bold text-lg mb-2 text-teal-800 print:text-black">Key Inquiry Questions</h3>
                <ul className="list-disc pl-5 space-y-1">
                    {plan.keyInquiryQuestions.map((q, i) => (
                        <li key={i}>{q}</li>
                    ))}
                </ul>
            </div>

            {/* Resources */}
            <div>
                 <h3 className="font-bold text-lg mb-2 text-teal-800 print:text-black">Learning Resources</h3>
                 <p>{plan.learningResources.join(", ")}</p>
            </div>

            <hr className="border-gray-300 my-4" />

            {/* Intro */}
            <div className="prose max-w-none">
                <h3 className="font-bold text-lg mb-2 text-teal-800 print:text-black">Introduction (5 minutes)</h3>
                <p className="whitespace-pre-wrap">{plan.introduction}</p>
            </div>

            {/* Development */}
            <div className="prose max-w-none">
                <h3 className="font-bold text-lg mb-4 text-teal-800 print:text-black">Lesson Development (25 minutes)</h3>

                <div className="ml-4 border-l-2 border-teal-500 pl-4 space-y-4 print:border-l-0 print:pl-0">
                    <div>
                        <h4 className="font-bold text-md text-gray-800">Step 1</h4>
                        <p className="whitespace-pre-wrap">{plan.developmentSteps.step1}</p>
                    </div>
                    <div>
                        <h4 className="font-bold text-md text-gray-800">Step 2</h4>
                        <p className="whitespace-pre-wrap">{plan.developmentSteps.step2}</p>
                    </div>
                    <div>
                        <h4 className="font-bold text-md text-gray-800">Step 3</h4>
                        <p className="whitespace-pre-wrap">{plan.developmentSteps.step3}</p>
                    </div>
                </div>
            </div>

            {/* Extended */}
            <div className="prose max-w-none">
                <h3 className="font-bold text-lg mb-2 text-teal-800 print:text-black">Extended Activities</h3>
                <p className="whitespace-pre-wrap bg-yellow-50 p-4 rounded border border-yellow-200 print:bg-transparent print:border-none print:p-0">{plan.extendedActivities}</p>
            </div>

            {/* Conclusion */}
            <div className="prose max-w-none">
                 <h3 className="font-bold text-lg mb-2 text-teal-800 print:text-black">Conclusion (5 minutes)</h3>
                 <p className="whitespace-pre-wrap">{plan.conclusion}</p>
            </div>

             {/* Reflection */}
            <div className="mt-8 pt-8 border-t border-dashed border-gray-400">
                <h3 className="font-bold text-lg mb-2 text-gray-500">Self-Reflection</h3>
                <div className="h-24 bg-gray-50 border border-gray-300 rounded print:border-gray-400"></div>
            </div>

        </div>
      </div>
    </div>
  );
};

export default LessonPlanDisplay;

import React, { useState } from 'react';
import Header from './components/Header';
import LessonGenerator from './components/LessonGenerator';
import LessonPlanDisplay from './components/LessonPlanDisplay';
import { LessonPlanData } from './types';

function App() {
  const [generatedPlan, setGeneratedPlan] = useState<LessonPlanData | null>(null);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <Header />

      <main className="flex-1 container mx-auto px-4 py-8 md:py-12 max-w-5xl">
        {!generatedPlan ? (
          <div className="space-y-6 animate-fade-in-up">
            <div className="text-center mb-8 no-print">
              <h2 className="text-2xl font-semibold text-gray-800">Create Your Lesson Plan</h2>
              <p className="text-gray-600 mt-2">Fill in the details below to generate a comprehensive, curriculum-aligned lesson plan in seconds.</p>
            </div>
            <LessonGenerator onPlanGenerated={setGeneratedPlan} />
          </div>
        ) : (
          <div className="animate-fade-in">
             <LessonPlanDisplay 
                plan={generatedPlan} 
                onBack={() => setGeneratedPlan(null)} 
             />
          </div>
        )}
      </main>

      <footer className="bg-slate-900 text-slate-400 py-8 text-center text-sm no-print mt-auto">
        <p>© {new Date().getFullYear()} JSS Maths Lesson Plan Guru. All Rights Reserved.</p>
        <p className="mt-1">Designed for the Kenyan CBE Curriculum.</p>
      </footer>
    </div>
  );
}

export default App;

