export const getPretechnicalLessonsForGrade = (grade: number): { strand: string; subStrand: string; lesson: PretechnicalLesson }[] => {
  const gradeData = pretechnicalCurriculumData.find(g => g.grade === grade);
  if (!gradeData) return [];

  const lessons: { strand: string; subStrand: string; lesson: PretechnicalLesson }[] = [];

  gradeData.strands.forEach(strand => {
