}

const LessonGenerator: React.FC<Props> = ({ onPlanGenerated }) => {
  const [formData, setFormData] = useState({
    teacherName: '',
    schoolName: '',
    date: new Date().toISOString().split('T')[0],
    grade: Grade.GRADE_7,
