            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
        </button>

        <div className="flex flex-wrap gap-3">
             <button 
                onClick={handleGenerateNotes}
                disabled={loadingNotes || notes !== null}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${notes ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-teal-50 border border-teal-200 text-teal-700 hover:bg-teal-100'}`}
            >
                {loadingNotes ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
                {notes ? 'Notes Generated' : 'Generate Simplified Notes'}
            </button>
            <button 
                onClick={handleGenerateQuestions}
                disabled={loadingQuestions || questions !== null}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${questions ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-blue-50 border border-blue-200 text-blue-700 hover:bg-blue-100'}`}
            >
                {loadingQuestions ? <Loader2 className="w-4 h-4 animate-spin" /> : <HelpCircle className="w-4 h-4" />}
                {questions ? 'Questions Generated' : 'Generate 15 Questions'}
            </button>
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
                Print / PDF
            </button>
            <button 
                onClick={handleDownload}
                className="flex items-center gap-2 bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-md hover:bg-gray-50 transition-colors shadow-sm"
            >
                <Download className="w-4 h-4" />
                Download
            </button>
        </div>
      </div>

      {/* The Printable Lesson Plan */}
      <div id="lesson-plan-content" ref={componentRef} className="bg-white p-8 md:p-12 shadow-lg border border-gray-200 mx-auto max-w-4xl print:shadow-none print:border-none print:w-full print:max-w-none print:p-0 print:m-0">

        {/* Header Table */}
        <div className="mb-8 border border-gray-800 text-sm">
            <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                <div className="col-span-1 p-2 font-bold bg-gray-100">Teacher</div>
                <div className="col-span-2 p-2">{plan.teacherName}</div>
                <div className="col-span-1 p-2 font-bold bg-gray-100">School</div>
                <div className="col-span-2 p-2">{plan.schoolName}</div>
            </div>
             <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                <div className="col-span-1 p-2 font-bold bg-gray-100">Date</div>
                <div className="col-span-2 p-2">{plan.date}</div>
                 <div className="col-span-1 p-2 font-bold bg-gray-100">Subject</div>
                <div className="col-span-2 p-2">{plan.subject}</div>
            </div>
             <div className="grid grid-cols-8 divide-x divide-gray-800">
                <div className="col-span-1 p-2 font-bold bg-gray-100">Grade</div>
                <div className="col-span-1 p-2 text-center">{plan.grade}</div>
                <div className="col-span-1 p-2 font-bold bg-gray-100">Term</div>
                <div className="col-span-1 p-2 text-center">{plan.term}</div>
                <div className="col-span-1 p-2 font-bold bg-gray-100">Roll</div>
                <div className="col-span-1 p-2 text-center">{plan.roll}</div>
