                <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Specific Learning Outcomes</h3>
                <p className="mb-2 italic">By the end of the lesson, the learner should be able to:</p>
                <ul className="list-disc pl-5 space-y-1">
                    {plan.learningOutcomes.map((outcome, i) => (
                        <li key={i}>{outcome}</li>
                    ))}
                </ul>
            </div>

            {/* Inquiry */}
             <div>
                <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Key Inquiry Questions</h3>
                <ul className="list-disc pl-5 space-y-1">
                    {plan.keyInquiryQuestions.map((q, i) => (
                        <li key={i}>{q}</li>
                    ))}
                </ul>
            </div>

            {/* Resources */}
            <div>
                 <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Learning Resources</h3>
                 <p>{plan.learningResources.join(", ")}</p>
            </div>

            <hr className="border-gray-300 my-4" />

            {/* Intro */}
            <div className="prose max-w-none">
                <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Introduction (5 minutes)</h3>
                <p className="whitespace-pre-wrap">{plan.introduction}</p>
            </div>

            {/* Development */}
            <div className="prose max-w-none">
                <h3 className="font-bold text-base mb-4 text-teal-800 print:text-black uppercase">Lesson Development (25 minutes)</h3>

                <div className="ml-4 border-l-2 border-teal-500 pl-4 space-y-4 print:border-l-0 print:pl-0">
                    <div>
                        <h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 1</h4>
                        <p className="whitespace-pre-wrap">{plan.developmentSteps.step1}</p>
                    </div>
                    <div>
                        <h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 2</h4>
                        <p className="whitespace-pre-wrap">{plan.developmentSteps.step2}</p>
                    </div>
                    <div>
                        <h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 3</h4>
                        <p className="whitespace-pre-wrap">{plan.developmentSteps.step3}</p>
                    </div>
                </div>
            </div>

            {/* Extended */}
            <div className="prose max-w-none">
                <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Extended Activities</h3>
                <p className="whitespace-pre-wrap bg-yellow-50 p-4 rounded border border-yellow-200 print:bg-transparent print:border-none print:p-0">{plan.extendedActivities}</p>
            </div>

            {/* Conclusion */}
            <div className="prose max-w-none">
                 <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Conclusion (5 minutes)</h3>
                 <p className="whitespace-pre-wrap">{plan.conclusion}</p>
            </div>

             {/* Reflection */}
            <div className="mt-8 pt-4 border-t border-dashed border-gray-400">
                <h3 className="font-bold text-base mb-2 text-gray-500 uppercase">Self-Reflection</h3>
                <div className="h-24 bg-gray-50 border border-gray-300 rounded print:border-gray-400"></div>
            </div>

            {/* Optional: Simplified Notes */}
            {notes && (
                <div className="mt-8 pt-8 border-t-2 border-gray-800 break-before-page">
                    <h2 className="text-xl font-bold mb-4 text-center">Simplified Teaching Notes</h2>
                    <div className="prose max-w-none whitespace-pre-wrap text-sm">
                        {notes}
                    </div>
                </div>
            )}

            {/* Optional: Practice Questions */}
            {questions && (
                <div className="mt-8 pt-8 border-t-2 border-gray-800 break-before-page">
                    <h2 className="text-xl font-bold mb-4 text-center">Practice Questions & Answers</h2>
                    <div className="prose max-w-none whitespace-pre-wrap text-sm">
                        {questions}
                    </div>
                </div>
            )}

        </div>
      </div>
    </div>
  );
};

