export const generateSimplifiedNotes = async (plan: LessonPlanData): Promise<string> => {
  const prompt = `
    Based on the following lesson plan, create simplified study notes specifically for the **LEARNERS** (students) to read.

    Topic: ${plan.topic}
    Grade: ${plan.grade}
    Subject: ${plan.subject}

    Lesson Plan Context:
    ${JSON.stringify(plan)}

    Requirements:
    1. **Target Audience:** Address the student directly (e.g., "In this lesson, you will learn..."). Use simple, age-appropriate language.
    2. **Content:** Provide clear explanations of the key concepts.
    3. **Step-by-Step:** Include step-by-step explanations for any processes, calculations, or activities mentioned.
    4. **Structure:** Use clear Headings and Bullet points for readability.
    5. **Length:** Strictly limit the output to approximately 300 words.
    6. **Format:** Plain text.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: prompt,
    });
    return response.text || "Failed to generate notes.";
  } catch (error) {
    console.error("Gemini API Error (Notes):", error);
    throw new Error("Failed to generate notes.");
  }
};

export const generatePracticeQuestions = async (plan: LessonPlanData): Promise<string> => {
  const prompt = `
    Based on the following lesson plan, generate 15 practice questions for the learners.

    Topic: ${plan.topic}
    Grade: ${plan.grade}
    Subject: ${plan.subject}

    Lesson Plan Context:
    ${JSON.stringify(plan)}

    Requirements:
    1. Generate exactly 15 questions relevant to the Specific Learning Outcomes.
    2. Questions should be age-appropriate for ${plan.grade}.
    3. Include a mix of multiple choice (if appropriate) or short answer questions.
    4. Include a separate "Answers" section at the very end.
    5. Provide the output in plain text with clear numbering.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: prompt,
    });
    return response.text || "Failed to generate questions.";
  } catch (error) {
    console.error("Gemini API Error (Questions):", error);
    throw new Error("Failed to generate questions.");
  }
};

import React, { useRef, useState } from 'react';
import { LessonPlanData } from '../types';
import { Printer, Download, ArrowLeft, FileText, HelpCircle, Loader2 } from 'lucide-react';
import { generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  const [notes, setNotes] = useState<string | null>(null);
  const [questions, setQuestions] = useState<string | null>(null);
  const [loadingNotes, setLoadingNotes] = useState(false);
  const [loadingQuestions, setLoadingQuestions] = useState(false);

  const handlePrint = () => {
    window.print();
  };

  const handleDownload = () => {
    const element = document.createElement("a");
    const file = new Blob([document.getElementById("lesson-plan-content")?.innerText || ""], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `LessonPlan-${plan.date}-${plan.lessonNumber}.txt`;
    document.body.appendChild(element);
    element.click();
  };

  const handleGenerateNotes = async () => {
    setLoadingNotes(true);
    try {
      const generatedNotes = await generateSimplifiedNotes(plan);
      setNotes(generatedNotes);
    } catch (error) {
      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(plan);
      setQuestions(generatedQuestions);
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Action Bar */}
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200 flex flex-wrap gap-4 justify-between items-center no-print sticky top-0 z-10">
