            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
        </button>

        <div className="flex flex-wrap gap-3">
             <button 
                onClick={handleGenerateNotes}
                disabled={loadingNotes || notes !== null}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${notes ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-teal-50 border border-teal-200 text-teal-700 hover:bg-teal-100'}`}
            >
                {loadingNotes ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
                {notes ? 'Notes Generated' : 'Generate Simplified Notes'}
            </button>
            <button 
                onClick={handleGenerateQuestions}
                disabled={loadingQuestions || questions !== null}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${questions ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-blue-50 border border-blue-200 text-blue-700 hover:bg-blue-100'}`}
            >
                {loadingQuestions ? <Loader2 className="w-4 h-4 animate-spin" /> : <HelpCircle className="w-4 h-4" />}
                {questions ? 'Questions Generated' : 'Generate 15 Questions'}
            </button>
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
