import React, { useState, useEffect, useMemo } from 'react';
import { Grade, Term, LessonDefinition, LessonPlanData, Subject, UserProfile } from '../types';
import { SCHEMES_OF_WORK } from '../data/maths';
import { PRETECH_SCHEMES } from '../data/pretech';
import { CREATIVE_ARTS_SCHEMES } from '../data/creative_arts';
import { CRE_SCHEMES } from '../data/cre';
import { INTEGRATED_SCIENCE_SCHEMES } from '../data/integrated_science';
import { SCIENCE_TECHNOLOGY_SCHEMES } from '../data/science_technology';
import { SOCIAL_STUDIES_SCHEMES } from '../data/social_studies';
import { AGRICULTURE_NUTRITION_SCHEMES } from '../data/agriculture_nutrition';
import { ENGLISH_SCHEMES } from '../data/english';
import { KISWAHILI_SCHEMES } from '../data/kiswahili';
import { generateLessonPlan } from '../services/geminiService';
import { Loader2, BookOpen, AlertCircle } from 'lucide-react';

interface Props {
  userProfile: UserProfile;
  onPlanGenerated: (data: LessonPlanData) => void;
}

const LessonGenerator: React.FC<Props> = ({ userProfile, onPlanGenerated }) => {
  const [formData, setFormData] = useState({
    teacherName: userProfile.name,
    schoolName: userProfile.school,
    date: new Date().toISOString().split('T')[0],
    grade: Grade.GRADE_7,
    term: Term.TERM_1,
    roll: 40,
    subject: Subject.MATHEMATICS
  });

  // Effect to update form if profile changes (e.g. from dashboard)
  useEffect(() => {
    setFormData(prev => ({
        ...prev,
        teacherName: userProfile.name,
        schoolName: userProfile.school
    }));
  }, [userProfile]);

  const [selectedStrand, setSelectedStrand] = useState<string>('');
  const [selectedSubStrand, setSelectedSubStrand] = useState<string>('');
  const [selectedLesson, setSelectedLesson] = useState<LessonDefinition | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Derived data based on Grade and Subject selection
  const gradeData = useMemo(() => {
    if (formData.subject === Subject.MATHEMATICS) {
      return SCHEMES_OF_WORK[formData.grade] || [];
    } else if (formData.subject === Subject.PRETECHNICAL_STUDIES) {
      return PRETECH_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.CREATIVE_ARTS) {
      return CREATIVE_ARTS_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.CHRISTIAN_RELIGIOUS_EDUCATION) {
      return CRE_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.INTEGRATED_SCIENCE) {
      return INTEGRATED_SCIENCE_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.SCIENCE_AND_TECHNOLOGY) {
      return SCIENCE_TECHNOLOGY_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.SOCIAL_STUDIES) {
      return SOCIAL_STUDIES_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.AGRICULTURE_AND_NUTRITION) {
      return AGRICULTURE_NUTRITION_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.ENGLISH) {
      return ENGLISH_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.KISWAHILI) {
      return KISWAHILI_SCHEMES[formData.grade] || [];
    }
    return [];
  }, [formData.grade, formData.subject]);

  const strands = useMemo(() => {
    return Array.from(new Set(gradeData.map(l => l.strand)));
  }, [gradeData]);

  const subStrands = useMemo(() => {
    return Array.from(new Set(gradeData.filter(l => l.strand === selectedStrand).map(l => l.subStrand)));
  }, [gradeData, selectedStrand]);

  const lessons = useMemo(() => {
    return gradeData.filter(l => l.strand === selectedStrand && l.subStrand === selectedSubStrand);
  }, [gradeData, selectedStrand, selectedSubStrand]);

  // Reset downstream selections when upstream changes
  useEffect(() => { setSelectedStrand(''); setSelectedSubStrand(''); setSelectedLesson(null); }, [formData.grade, formData.subject]);
  useEffect(() => { setSelectedSubStrand(''); setSelectedLesson(null); }, [selectedStrand]);
  useEffect(() => { setSelectedLesson(null); }, [selectedSubStrand]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedLesson) {
        setError("Please select a specific lesson.");
        return;
    }
    setError(null);
    setLoading(true);

    try {
      const plan = await generateLessonPlan(formData, selectedLesson);
      onPlanGenerated(plan);
    } catch (err: any) {
      setError(err.message || "An error occurred generating the plan.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden no-print">
      <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex items-center gap-2">
        <BookOpen className="text-teal-600 w-5 h-5" />
        <h2 className="text-lg font-semibold text-gray-800">Lesson Plan Generator</h2>
      </div>

      <form onSubmit={handleSubmit} className="p-6 md:p-8 space-y-8">

        {/* Top Table-like Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">

            {/* Teacher & School */}
            <div className="space-y-4">
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Teacher</label>
                    <input 
                        required
                        type="text" 
                        value={formData.teacherName}
                        onChange={e => setFormData({...formData, teacherName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border bg-gray-50"
                        placeholder="Enter Name"
                    />
                </div>
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">School</label>
                    <input 
                        required
                        type="text" 
                        value={formData.schoolName}
                        onChange={e => setFormData({...formData, schoolName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border bg-gray-50"
                        placeholder="Enter School"
                    />
                </div>
            </div>

            {/* Date, Subject, Time */}
            <div className="space-y-4">
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Date</label>
                    <input 
                        type="date" 
                        value={formData.date}
                        onChange={e => setFormData({...formData, date: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                    />
                </div>
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Subject</label>
                    <select 
                        value={formData.subject}
                        onChange={e => setFormData({...formData, subject: e.target.value as Subject})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                    >
                        {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </div>
        </div>

        {/* Separator */}
        <div className="h-px bg-gray-200 w-full"></div>

        {/* Class Details Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Grade</label>
                <select 
                    value={formData.grade}
                    onChange={e => setFormData({...formData, grade: e.target.value as Grade})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Term</label>
                <select 
                    value={formData.term}
                    onChange={e => setFormData({...formData, term: e.target.value as Term})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Term).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
            </div>
             <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Roll (Class Size)</label>
                <input 
                    type="number"
                    value={formData.roll}
                    onChange={e => setFormData({...formData, roll: parseInt(e.target.value)})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                />
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Time</label>
                <div className="w-full py-2 px-3 bg-gray-100 rounded-md text-gray-700 border border-gray-200">
                    40 Minutes
                </div>
            </div>
        </div>

        {/* Cascading Content Selection */}
        <div className="bg-teal-50 p-6 rounded-lg border border-teal-100 space-y-6">
            <h3 className="text-teal-800 font-medium border-b border-teal-200 pb-2">Curriculum Content Selector</h3>

            {gradeData.length === 0 ? (
                <div className="text-center text-gray-500 py-4">No lesson data available for {formData.subject} - {formData.grade}</div>
            ) : (
                <>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-teal-800 mb-2">Select Strand</label>
                            <select 
                                value={selectedStrand}
                                onChange={e => setSelectedStrand(e.target.value)}
                                className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                                disabled={strands.length === 0}
                            >
                                <option value="">-- Choose Strand --</option>
                                {strands.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-teal-800 mb-2">Select Sub-strand</label>
                            <select 
                                value={selectedSubStrand}
                                onChange={e => setSelectedSubStrand(e.target.value)}
                                className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                                disabled={!selectedStrand}
                            >
                                <option value="">-- Choose Sub-strand --</option>
                                {subStrands.map(ss => <option key={ss} value={ss}>{ss}</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-teal-800 mb-2">Select Lesson</label>
                        <select 
                            value={selectedLesson ? JSON.stringify(selectedLesson) : ""}
                            onChange={e => {
                                if(e.target.value) setSelectedLesson(JSON.parse(e.target.value));
                            }}
                            className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                            disabled={!selectedSubStrand}
                        >
                            <option value="">-- Choose Lesson --</option>
                            {lessons.map((l, idx) => (
                                <option key={idx} value={JSON.stringify(l)}>{l.topic}</option>
                            ))}
                        </select>
                    </div>

                    {selectedLesson && (
                        <div className="mt-4 p-4 bg-white/60 rounded border border-teal-200 text-sm text-teal-900">
                            <p><strong>Preview Learning Outcome:</strong> {selectedLesson.learningOutcomes[0]}</p>
                        </div>
                    )}
                </>
            )}
        </div>

        {error && (
            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded flex items-center gap-3">
                <AlertCircle className="text-red-500" />
                <p className="text-red-700">{error}</p>
            </div>
        )}

        {/* Actions */}
        <div className="flex gap-4 pt-2">
            <button 
                type="button" 
                className="px-6 py-3 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500"
                onClick={() => {
                   setFormData({...formData, teacherName: '', schoolName: ''});
                   setSelectedStrand('');
                }}
            >
                Reset Form
            </button>
            <button 
                type="submit" 
                disabled={loading || !selectedLesson}
                className="flex-1 flex justify-center items-center gap-2 px-6 py-3 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-teal-600 hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin h-5 w-5" />
                        Generating Plan with AI...
                    </>
                ) : (
                    "Generate Lesson Plan"
                )}
            </button>
        </div>

      </form>
    </div>
  );
};

export default LessonGenerator;

