import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import LessonGenerator from './components/LessonGenerator';
import LessonPlanDisplay from './components/LessonPlanDisplay';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import { LessonPlanData, UserProfile } from './types';
import { LayoutDashboard, FileText, LogOut } from 'lucide-react';

function App() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [generatedPlan, setGeneratedPlan] = useState<LessonPlanData | null>(null);
  const [currentView, setCurrentView] = useState<'generator' | 'dashboard'>('generator');

  // Check for existing session
  useEffect(() => {
    const savedUser = localStorage.getItem('jss_user_profile');
    if (savedUser) {
        setUser(JSON.parse(savedUser));
    }
  }, []);

  const handleLogin = (profile: UserProfile) => {
    setUser(profile);
    localStorage.setItem('jss_user_profile', JSON.stringify(profile));
  };

  const handleUpdateProfile = (profile: UserProfile) => {
    setUser(profile);
    localStorage.setItem('jss_user_profile', JSON.stringify(profile));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('jss_user_profile');
    setGeneratedPlan(null);
    setCurrentView('generator');
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <Header />

      <main className="flex-1 container mx-auto px-4 py-8 md:py-12 max-w-5xl">
        {!user ? (
            <Login onLogin={handleLogin} />
        ) : (
            <>
                {/* Navigation Bar for Authenticated Users */}
                <div className="flex justify-between items-center mb-8 border-b border-gray-200 pb-4 no-print">
                    <div className="flex gap-4">
                        <button
                            onClick={() => {
                                setCurrentView('generator');
                                setGeneratedPlan(null);
                            }}
                            className={`flex items-center gap-2 px-4 py-2 rounded-md font-medium transition-colors ${currentView === 'generator' && !generatedPlan ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                        >
                            <FileText className="w-4 h-4" />
                            Lesson Planner
                        </button>
                        <button
                            onClick={() => setCurrentView('dashboard')}
                            className={`flex items-center gap-2 px-4 py-2 rounded-md font-medium transition-colors ${currentView === 'dashboard' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                        >
                            <LayoutDashboard className="w-4 h-4" />
                            Dashboard
                        </button>
                    </div>

                    <div className="flex items-center gap-4">
                        <span className="text-sm text-gray-500 hidden md:inline">Welcome, {user.name}</span>
                        <button
                            onClick={handleLogout}
                            className="flex items-center gap-2 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50 rounded-md transition-colors"
                        >
                            <LogOut className="w-4 h-4" />
                            Logout
                        </button>
                    </div>
                </div>

                {/* Content Area */}
                {currentView === 'dashboard' ? (
                    <div className="animate-fade-in">
                        <Dashboard profile={user} onUpdate={handleUpdateProfile} />
                    </div>
                ) : generatedPlan ? (
                    <div className="animate-fade-in">
                        <LessonPlanDisplay 
                            plan={generatedPlan} 
                            onBack={() => setGeneratedPlan(null)} 
                        />
                    </div>
                ) : (
                    <div className="animate-fade-in-up">
                        <div className="text-center mb-8 no-print">
                            <h2 className="text-2xl font-semibold text-gray-800">Create Your Lesson Plan</h2>
                            <p className="text-gray-600 mt-2">Fill in the details below to generate a comprehensive, curriculum-aligned lesson plan in seconds.</p>
                        </div>
                        <LessonGenerator userProfile={user} onPlanGenerated={setGeneratedPlan} />
                    </div>
                )}
            </>
        )}
      </main>

      <footer className="bg-slate-900 text-slate-400 py-8 text-center text-sm no-print mt-auto">
        <p>© {new Date().getFullYear()} JSS Maths Lesson Plan Guru. All Rights Reserved.</p>
        <p className="mt-1">Designed for the Kenyan CBE Curriculum.</p>
      </footer>
    </div>
  );
}

export default App;

