import React, { useState } from 'react';
import { UserProfile } from '../types';
import { Lock, User, School, Phone, Mail, ArrowRight, LogIn } from 'lucide-react';

interface Props {
  onLogin: (profile: UserProfile) => void;
  initialMode?: 'signin' | 'signup';
}

const Login: React.FC<Props> = ({ onLogin, initialMode = 'signup' }) => {
  const [isSignUp, setIsSignUp] = useState(initialMode === 'signup');
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState<UserProfile>({
    email: '',
    name: '',
    school: '',
    phone: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (isSignUp) {
        // Sign Up Logic
        if (formData.email && formData.name && formData.school && formData.phone) {
            onLogin(formData);
        } else {
            setError("Please fill in all fields.");
        }
    } else {
        // Sign In Logic (Simulation)
        if (!formData.email) {
            setError("Please enter your email.");
            return;
        }

        // Attempt to retrieve profile from localStorage
        // Note: In a real app, this would be an API call. 
        // Here we can only check if the *current* browser has a session stored, 
        // but for the sake of the UX requested, we will allow "Sign In" to basically 
        // retrieve the last session or just create a minimal session if not found but prevent blocking.
        const savedUser = localStorage.getItem('jss_user_profile');
        if (savedUser) {
            const parsed = JSON.parse(savedUser);
            if (parsed.email === formData.email) {
                onLogin(parsed);
                return;
            }
        }

        // If no matching local user, we effectively treat it as a fresh login or prompt to sign up.
        // For this frontend-only demo, we'll suggest signing up if "not found" logic was real,
        // but here we might just pass the partial info or ask them to complete it.
        // Let's just pass the email and ask to complete profile if needed, or error.
        if (savedUser) {
             setError("Email does not match the saved session on this device. Please Sign Up to create a new profile.");
        } else {
             setError("No account found on this device. Please Sign Up.");
        }
    }
  };

  return (
    <div className="min-h-[80vh] flex flex-col justify-center items-center p-4 bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden">
        <div className="bg-slate-900 px-6 py-8 text-center text-white">
          <div className="mx-auto bg-slate-800 w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-inner border border-slate-700">
            {isSignUp ? <User className="w-8 h-8 text-teal-400" /> : <LogIn className="w-8 h-8 text-teal-400" />}
          </div>
          <h2 className="text-2xl font-bold">{isSignUp ? "Create Account" : "Welcome Back"}</h2>
          <p className="text-slate-400 mt-2 text-sm">
            {isSignUp ? "Join MwalimuPlanner today" : "Sign in to continue planning"}
          </p>
        </div>

        <div className="p-8">
            {error && (
                <div className="mb-6 bg-red-50 text-red-600 p-3 rounded-md text-sm border border-red-200">
                    {error}
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-5">
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Mail className="h-5 w-5 text-gray-400" />
                </div>
                <input
                    type="email"
                    required
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                    className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                    placeholder="teacher@school.edu"
                />
                </div>
            </div>

            {isSignUp && (
                <>
                    <div className="animate-fade-in-up">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Official Name</label>
                        <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <User className="h-5 w-5 text-gray-400" />
                        </div>
                        <input
                            type="text"
                            required
                            value={formData.name}
                            onChange={e => setFormData({...formData, name: e.target.value})}
                            className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                            placeholder="Mr. / Ms. Full Name"
                        />
