            )}

            <button
                type="submit"
                className="w-full flex justify-center items-center gap-2 bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-6"
            >
                {isSignUp ? "Create Account" : "Sign In"} 
