import { LessonPlanData } from '../types';
import { Printer, Download, ArrowLeft, FileText, HelpCircle, Loader2, Save, Layout } from 'lucide-react';
import { generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan } from '../services/storageService';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  // Local state for the plan being displayed (so we can update it with notes/questions)
  const [currentPlan, setCurrentPlan] = useState<LessonPlanData>(plan);
  const [activeTab, setActiveTab] = useState<'plan' | 'notes' | 'questions'>('plan');

  const [loadingNotes, setLoadingNotes] = useState(false);
  const [loadingQuestions, setLoadingQuestions] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');

  // Update local state if the prop changes
  useEffect(() => {
    setCurrentPlan(plan);
  }, [plan]);

  const handlePrint = () => {
    window.print();
  };

  const handleSave = () => {
    setSaveStatus('saving');
    savePlan(currentPlan);
    setTimeout(() => setSaveStatus('saved'), 800);
    setTimeout(() => setSaveStatus('idle'), 3000);
  };

  const handleDownload = () => {
    // Generate HTML content for Word document with specified styles
    const content = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
        <head>
          <meta charset="utf-8">
          <title>Lesson Plan - ${currentPlan.date}</title>
          <style>
            /* Global Word Styles */
            body { 
                font-family: 'Arial', sans-serif; 
                font-size: 8pt; 
                line-height: 1.2; 
                color: #000;
            }
            h1 { font-size: 14pt; border-bottom: 1px solid #000; margin-bottom: 10px; }
            h2 { font-size: 12pt; margin-top: 15px; border-bottom: 1px solid #ccc; padding-bottom: 3px; }
            h3 { font-size: 9pt; margin-top: 10px; font-weight: bold; text-transform: uppercase; }
            p, ul, li { margin-bottom: 5px; }

            /* Two Column Layout for Word */
            .columns-2 {
                column-count: 2;
                column-gap: 20px;
            }

            /* Compact Table */
            table { width: 100%; border-collapse: collapse; margin-bottom: 10px; font-size: 8pt; }
            td { border: 1px solid #000; padding: 4px; vertical-align: top; }
            .label { font-weight: bold; background-color: #f0f0f0; width: 25%; }

            .page-break { page-break-before: always; }
            .section { margin-bottom: 10px; }
          </style>
        </head>
        <body>
          <!-- PAGE 1: LESSON PLAN -->
          <h1>Lesson Plan: ${currentPlan.lessonNumber}</h1>

          <table style="width: 70%; margin-bottom: 15px;">
            <tr><td class="label">Teacher</td><td>${currentPlan.teacherName}</td><td class="label">School</td><td>${currentPlan.schoolName}</td></tr>
            <tr><td class="label">Date</td><td>${currentPlan.date}</td><td class="label">Subject</td><td>${currentPlan.subject}</td></tr>
            <tr><td class="label">Grade</td><td>${currentPlan.grade}</td><td class="label">Term</td><td>${currentPlan.term}</td></tr>
            <tr><td class="label">Roll</td><td>${currentPlan.roll}</td><td class="label">Time</td><td>40 Min</td></tr>
            <tr><td class="label">Strand</td><td colspan="3">${currentPlan.strand}</td></tr>
            <tr><td class="label">Sub-strand</td><td colspan="3">${currentPlan.subStrand}</td></tr>
          </table>

          <div class="columns-2">
            <div class="section">
                <h3>Specific Learning Outcomes</h3>
                <ul>${currentPlan.learningOutcomes.map(o => `<li>${o}</li>`).join('')}</ul>
            </div>

            <div class="section">
                <h3>Key Inquiry Questions</h3>
                <ul>${currentPlan.keyInquiryQuestions.map(q => `<li>${q}</li>`).join('')}</ul>
            </div>

            <div class="section">
                <h3>Learning Resources</h3>
                <p>${currentPlan.learningResources.join(", ")}</p>
            </div>

            <div class="section">
                <h3>Introduction (5 min)</h3>
                <p>${currentPlan.introduction.replace(/\n/g, '<br/>')}</p>
            </div>

            <div class="section">
                <h3>Lesson Development (25 min)</h3>
                <p><strong>Step 1:</strong> ${currentPlan.developmentSteps.step1.replace(/\n/g, '<br/>')}</p>
                <p><strong>Step 2:</strong> ${currentPlan.developmentSteps.step2.replace(/\n/g, '<br/>')}</p>
                <p><strong>Step 3:</strong> ${currentPlan.developmentSteps.step3.replace(/\n/g, '<br/>')}</p>
            </div>

            <div class="section">
                <h3>Extended Activities</h3>
                <p>${currentPlan.extendedActivities.replace(/\n/g, '<br/>')}</p>
            </div>

            <div class="section">
                <h3>Conclusion (5 min)</h3>
                <p>${currentPlan.conclusion.replace(/\n/g, '<br/>')}</p>
            </div>

            <div class="section">
                <h3>Reflection</h3>
                <div style="height: 50px; border: 1px dashed #999;"></div>
            </div>
          </div>

          <!-- PAGE 2: NOTES (If Generated) -->
          ${currentPlan.learnerNotes ? `
            <div class="page-break">
              <h1>Simplified Learner Notes</h1>
              <div class="columns-2">
                ${currentPlan.learnerNotes.replace(/\n/g, '<br/>')}
              </div>
            </div>
          ` : ''}

          <!-- PAGE 3: QUESTIONS (If Generated) -->
          ${currentPlan.practiceQuestions ? `
            <div class="page-break">
              <h1>Practice Questions & Answers</h1>
              <div class="columns-2">
                ${currentPlan.practiceQuestions.replace(/\n/g, '<br/>')}
              </div>
            </div>
          ` : ''}
        </body>
      </html>
    `;

    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `LessonPlan-${currentPlan.date}-${currentPlan.lessonNumber.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleGenerateNotes = async () => {
    setLoadingNotes(true);
    try {
      const generatedNotes = await generateSimplifiedNotes(currentPlan);
      const updatedPlan = { ...currentPlan, learnerNotes: generatedNotes };
      setCurrentPlan(updatedPlan);
      // Automatically save if this plan was already saved
      if (localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(currentPlan);
      const updatedPlan = { ...currentPlan, practiceQuestions: generatedQuestions };
      setCurrentPlan(updatedPlan);
      // Automatically save if this plan was already saved
      if (localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Top Action Bar */}
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200 flex flex-wrap gap-4 justify-between items-center no-print sticky top-0 z-20">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors">
            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
        </button>

        <div className="flex flex-wrap gap-3">
             <button 
                onClick={handleSave}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${saveStatus === 'saved' ? 'bg-green-100 text-green-800' : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-50'}`}
            >
                <Save className="w-4 h-4" />
                {saveStatus === 'saving' ? 'Saving...' : saveStatus === 'saved' ? 'Saved' : 'Save Plan'}
            </button>
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
                Print / PDF
            </button>
            <button 
                onClick={handleDownload}
                className="flex items-center gap-2 bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-md hover:bg-gray-50 transition-colors shadow-sm"
            >
                <Download className="w-4 h-4" />
                Download Word
            </button>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="flex border-b border-gray-200 no-print mb-6 overflow-x-auto">
        <button
            onClick={() => setActiveTab('plan')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'plan' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <Layout className="w-4 h-4" /> Lesson Plan
        </button>
        <button
            onClick={() => setActiveTab('notes')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'notes' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <FileText className="w-4 h-4" /> Learner Notes
        </button>
        <button
            onClick={() => setActiveTab('questions')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'questions' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <HelpCircle className="w-4 h-4" /> Practice Questions
        </button>
      </div>

      {/* Content Area */}
      <div id="lesson-plan-content" ref={componentRef} className="bg-white p-8 md:p-12 shadow-lg border border-gray-200 mx-auto max-w-4xl print:shadow-none print:border-none print:w-full print:max-w-none print:p-0 print:m-0">

        {/* Lesson Plan View */}
        {(activeTab === 'plan' || typeof window !== 'undefined' && window.matchMedia('print').matches) && (
            <div className={`${activeTab !== 'plan' ? 'hidden print:block' : ''}`}>
                {/* Header Table */}
                <div className="mb-8 border border-gray-800 text-sm">
                    <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Teacher</div>
                        <div className="col-span-2 p-2">{currentPlan.teacherName}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">School</div>
                        <div className="col-span-2 p-2">{currentPlan.schoolName}</div>
                    </div>
                    <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Date</div>
                        <div className="col-span-2 p-2">{currentPlan.date}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Subject</div>
                        <div className="col-span-2 p-2">{currentPlan.subject}</div>
                    </div>
                    <div className="grid grid-cols-8 divide-x divide-gray-800">
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Grade</div>
                        <div className="col-span-1 p-2 text-center">{currentPlan.grade}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Term</div>
                        <div className="col-span-1 p-2 text-center">{currentPlan.term}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Roll</div>
                        <div className="col-span-1 p-2 text-center">{currentPlan.roll}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Time</div>
                        <div className="col-span-1 p-2 text-center">40 min</div>
                    </div>
                </div>

                <div className="space-y-6 text-gray-900 leading-relaxed text-sm">
                    <div className="bg-slate-50 p-4 rounded border border-slate-200 print:bg-transparent print:border-none print:p-0">
                        <p><span className="font-bold">Strand:</span> {currentPlan.strand}</p>
                        <p><span className="font-bold">Sub-strand:</span> {currentPlan.subStrand}</p>
                        <h2 className="font-bold text-lg mt-2 text-slate-800">{currentPlan.lessonNumber}</h2>
                    </div>

                    <div>
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Specific Learning Outcomes</h3>
                        <ul className="list-disc pl-5 space-y-1">
                            {currentPlan.learningOutcomes.map((outcome, i) => <li key={i}>{outcome}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Key Inquiry Questions</h3>
                        <ul className="list-disc pl-5 space-y-1">
                            {currentPlan.keyInquiryQuestions.map((q, i) => <li key={i}>{q}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Learning Resources</h3>
                        <p>{currentPlan.learningResources.join(", ")}</p>
                    </div>

                    <hr className="border-gray-300 my-4" />

                    <div className="prose max-w-none">
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Introduction (5 minutes)</h3>
                        <p className="whitespace-pre-wrap">{currentPlan.introduction}</p>
                    </div>

                    <div className="prose max-w-none">
                        <h3 className="font-bold text-base mb-4 text-teal-800 print:text-black uppercase">Lesson Development (25 minutes)</h3>
                        <div className="ml-4 border-l-2 border-teal-500 pl-4 space-y-4 print:border-l-0 print:pl-0">
                            <div><h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 1</h4><p className="whitespace-pre-wrap">{currentPlan.developmentSteps.step1}</p></div>
                            <div><h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 2</h4><p className="whitespace-pre-wrap">{currentPlan.developmentSteps.step2}</p></div>
                            <div><h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 3</h4><p className="whitespace-pre-wrap">{currentPlan.developmentSteps.step3}</p></div>
                        </div>
                    </div>

                    <div className="prose max-w-none">
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Extended Activities</h3>
                        <p className="whitespace-pre-wrap bg-yellow-50 p-4 rounded border border-yellow-200 print:bg-transparent print:border-none print:p-0">{currentPlan.extendedActivities}</p>
                    </div>

                    <div className="prose max-w-none">
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Conclusion (5 minutes)</h3>
                        <p className="whitespace-pre-wrap">{currentPlan.conclusion}</p>
                    </div>

                    <div className="mt-8 pt-4 border-t border-dashed border-gray-400">
                        <h3 className="font-bold text-base mb-2 text-gray-500 uppercase">Self-Reflection</h3>
                        <div className="h-24 bg-gray-50 border border-gray-300 rounded print:border-gray-400"></div>
                    </div>
                </div>
            </div>
        )}

        {/* Notes View */}
        {(activeTab === 'notes' || typeof window !== 'undefined' && window.matchMedia('print').matches && currentPlan.learnerNotes) && (
            <div className={`${activeTab !== 'notes' ? 'hidden print:block print:break-before-page' : 'animate-fade-in'}`}>
                <h2 className="text-xl font-bold mb-6 text-teal-900 border-b pb-2">Simplified Learner Notes</h2>

                {currentPlan.learnerNotes ? (
                    <div className="prose max-w-none whitespace-pre-wrap text-sm bg-gray-50 p-6 rounded-lg border border-gray-200 print:bg-transparent print:border-none print:p-0">
                        {currentPlan.learnerNotes}
                    </div>
                ) : (
                    <div className="text-center py-12 bg-gray-50 rounded border border-dashed border-gray-300 no-print">
                        <p className="text-gray-500 mb-4">No notes generated yet for this lesson.</p>
                        <button 
                            onClick={handleGenerateNotes}
                            disabled={loadingNotes}
                            className="inline-flex items-center gap-2 bg-teal-600 text-white px-6 py-2 rounded-md hover:bg-teal-700 transition-colors"
                        >
                            {loadingNotes ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />}
                            Generate Notes Now
                        </button>
                    </div>
                )}
            </div>
        )}

        {/* Questions View */}
        {(activeTab === 'questions' || typeof window !== 'undefined' && window.matchMedia('print').matches && currentPlan.practiceQuestions) && (
            <div className={`${activeTab !== 'questions' ? 'hidden print:block print:break-before-page' : 'animate-fade-in'}`}>
                <h2 className="text-xl font-bold mb-6 text-teal-900 border-b pb-2">Practice Questions & Answers</h2>

                {currentPlan.practiceQuestions ? (
                    <div className="prose max-w-none whitespace-pre-wrap text-sm bg-gray-50 p-6 rounded-lg border border-gray-200 print:bg-transparent print:border-none print:p-0">
                        {currentPlan.practiceQuestions}
                    </div>
                ) : (
                    <div className="text-center py-12 bg-gray-50 rounded border border-dashed border-gray-300 no-print">
                        <p className="text-gray-500 mb-4">No questions generated yet for this lesson.</p>
                        <button 
                            onClick={handleGenerateQuestions}
                            disabled={loadingQuestions}
                            className="inline-flex items-center gap-2 bg-teal-600 text-white px-6 py-2 rounded-md hover:bg-teal-700 transition-colors"
                        >
                            {loadingQuestions ? <Loader2 className="w-4 h-4 animate-spin" /> : <HelpCircle className="w-4 h-4" />}
                            Generate 15 Questions
                        </button>
                    </div>
                )}
            </div>
        )}

      </div>
    </div>
  );
};

export default LessonPlanDisplay;

import React, { useState, useEffect } from 'react';
import { LessonPlanData } from '../types';
import { getSavedPlans, deletePlan } from '../services/storageService';
import { FileText, Calendar, Trash2, ChevronRight, Search } from 'lucide-react';

interface Props {
  onSelectPlan: (plan: LessonPlanData) => void;
}

const SavedPlans: React.FC<Props> = ({ onSelectPlan }) => {
  const [plans, setPlans] = useState<LessonPlanData[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    setPlans(getSavedPlans());
  }, []);

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('Are you sure you want to delete this lesson plan?')) {
      deletePlan(id);
      setPlans(getSavedPlans());
    }
  };

  const filteredPlans = plans.filter(p => 
    p.topic.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.subject.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.grade.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Saved Lesson Plans</h2>
        <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
            <input 
                type="text" 
                placeholder="Search plans..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
            />
        </div>
      </div>

      {filteredPlans.length === 0 ? (
        <div className="text-center py-16 bg-white rounded-xl shadow-sm border border-gray-200">
          <div className="bg-gray-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
            <FileText className="w-8 h-8 text-gray-400" />
          </div>
          <h3 className="text-lg font-medium text-gray-900">No saved plans found</h3>
          <p className="text-gray-500 mt-1">Generate a lesson plan and click "Save" to see it here.</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
          <ul className="divide-y divide-gray-200">
            {filteredPlans.map((plan) => (
              <li 
                key={plan.id} 
                onClick={() => onSelectPlan(plan)}
                className="group hover:bg-gray-50 transition-colors cursor-pointer"
              >
                <div className="p-5 flex items-center justify-between">
                  <div className="flex-1 min-w-0">
                    <h3 className="text-base font-semibold text-teal-800 truncate mb-1 group-hover:text-teal-600">
                      {plan.lessonNumber || plan.topic}
                    </h3>
                    <div className="flex flex-wrap gap-x-4 gap-y-1 text-sm text-gray-500">
                      <span className="flex items-center gap-1">
                        <span className="font-medium text-gray-700">{plan.subject}</span>
                      </span>
                      <span className="flex items-center gap-1">
                        <span className="bg-gray-200 text-xs px-2 py-0.5 rounded-full">{plan.grade}</span>
                      </span>
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3 h-3" />
                        {new Date(plan.date).toLocaleDateString()}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-4 ml-4">
                    <button
                        onClick={(e) => handleDelete(e, plan.id || '')}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                        title="Delete Plan"
                    >
                        <Trash2 className="w-4 h-4" />
                    </button>
                    <ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" />
                  </div>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

export default SavedPlans;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import LessonGenerator from './components/LessonGenerator';
import LessonPlanDisplay from './components/LessonPlanDisplay';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import LandingPage from './components/LandingPage';
import SavedPlans from './components/SavedPlans';
import { LessonPlanData, UserProfile } from './types';
import { LayoutDashboard, FileText, LogOut, Save } from 'lucide-react';

function App() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [generatedPlan, setGeneratedPlan] = useState<LessonPlanData | null>(null);
  const [currentView, setCurrentView] = useState<'landing' | 'auth' | 'generator' | 'dashboard' | 'saved'>('landing');
  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');

  // Check for existing session on load
  useEffect(() => {
    const savedUser = localStorage.getItem('jss_user_profile');
    if (savedUser) {
        setUser(JSON.parse(savedUser));
        setCurrentView('generator'); // Skip landing if logged in
    }
  }, []);

  const handleLogin = (profile: UserProfile) => {
    setUser(profile);
    localStorage.setItem('jss_user_profile', JSON.stringify(profile));
    setCurrentView('generator');
  };

  const handleUpdateProfile = (profile: UserProfile) => {
    setUser(profile);
    localStorage.setItem('jss_user_profile', JSON.stringify(profile));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('jss_user_profile');
    setGeneratedPlan(null);
    setCurrentView('landing');
  };

  const navigateToAuth = (mode: 'signin' | 'signup') => {
      setAuthMode(mode);
      setCurrentView('auth');
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
