  Quote,
  Share2,
  Zap,
  Calendar,
  Clock,
  Target,
  Award,
  FileText
} from 'lucide-react';
import { UserProfile, LessonPlanData, NewsItem } from '../types';
import { fetchEducationNews } from '../services/geminiService';
import LessonGenerator from './LessonGenerator';

// Mapping custom colors from inspiration to arbitrary tailwind values
const COLORS = {
  crimson: 'bg-[#DC143C]',
  textCrimson: 'text-[#DC143C]',
  borderCrimson: 'border-[#DC143C]',
  hoverCrimson: 'hover:bg-[#DC143C]',
  dark: 'bg-[#0f172a]', // Slate 900
  hoverDark: 'hover:bg-[#0f172a]',
  gold: 'text-[#FFD700]',
  ringGold: 'focus:ring-[#FFD700]',
  emerald: 'bg-[#10B981]',
  textEmerald: 'text-[#10B981]'
};

interface LandingProps {
  onStart: () => void;
  user: UserProfile | null;
  onLogout: () => void;
  onViewHistory?: () => void;
  onViewDashboard?: () => void;
  onPlanGenerated: (plan: LessonPlanData) => void;
}

const LandingPage: React.FC<LandingProps> = ({ onStart, user, onLogout, onViewDashboard, onPlanGenerated }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [news, setNews] = useState<NewsItem[]>([]);
  const [isNewsLoading, setIsNewsLoading] = useState(true);
  const [email, setEmail] = useState('');
  const [isSubscribing, setIsSubscribing] = useState(false);
  const [subscribeSuccess, setSubscribeSuccess] = useState(false);
  const [activeSection, setActiveSection] = useState('hero');
  const [showPlannerPreview, setShowPlannerPreview] = useState(false);

  const sectionRefs = {
    hero: useRef<HTMLElement>(null),
    features: useRef<HTMLElement>(null),
    grades: useRef<HTMLElement>(null),
    preview: useRef<HTMLElement>(null),
    testimonials: useRef<HTMLElement>(null),
    contact: useRef<HTMLElement>(null),
    news: useRef<HTMLElement>(null),
    newsletter: useRef<HTMLElement>(null)
  };

  // Intersection Observer for table of contents
  useEffect(() => {
    const observers: IntersectionObserver[] = [];

    Object.entries(sectionRefs).forEach(([key, ref]) => {
      if (ref.current) {
        const observer = new IntersectionObserver(
          (entries) => {
            entries.forEach((entry) => {
              if (entry.isIntersecting) {
                setActiveSection(key);
              }
            });
          },
          { threshold: 0.5 }
        );
        observer.observe(ref.current);
        observers.push(observer);
      }
    });

    return () => observers.forEach(observer => observer.disconnect());
  }, []);

  const loadNews = async () => {
    setIsNewsLoading(true);
    try {
      const data = await fetchEducationNews();
      setNews(data);
    } catch (e) {
      console.error("Failed to load news");
    } finally {
      setIsNewsLoading(false);
    }
  };

  useEffect(() => {
    loadNews();
  }, []);

  const handleSubscribe = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubscribing(true);
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1500));
    setIsSubscribing(false);
    setSubscribeSuccess(true);
    setEmail('');
    setTimeout(() => setSubscribeSuccess(false), 3000);
  };

  const scrollToSection = (sectionId: string) => {
    const ref = sectionRefs[sectionId as keyof typeof sectionRefs];
    if (ref && ref.current) {
        ref.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
    setIsMenuOpen(false);
  };

