// Reverting to Teal/Green Theme
const COLORS = {
  primary: 'bg-teal-600',
  textPrimary: 'text-teal-600',
  borderPrimary: 'border-teal-600',
  hoverPrimary: 'hover:bg-teal-700',
  light: 'bg-teal-50',
