import React, { useRef, useState, useEffect } from 'react';
import { LessonPlanData } from '../types';
import { Printer, Download, ArrowLeft, FileText, HelpCircle, Loader2, Save, Layout, Lock } from 'lucide-react';
import { generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan, getCurrentUser } from '../services/storageService';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  // Local state for the plan being displayed (so we can update it with notes/questions)
  const [currentPlan, setCurrentPlan] = useState<LessonPlanData>(plan);
  const [activeTab, setActiveTab] = useState<'plan' | 'notes' | 'questions'>('plan');

  const [loadingNotes, setLoadingNotes] = useState(false);
  const [loadingQuestions, setLoadingQuestions] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [isGuest, setIsGuest] = useState(false);

  // Update local state if the prop changes and check auth
  useEffect(() => {
    setCurrentPlan(plan);
    const user = getCurrentUser();
    setIsGuest(!user);
  }, [plan]);

  const handlePrint = () => {
    window.print();
  };

  const handleSave = () => {
    if (isGuest) {
        alert("Please sign in or create an account to save lesson plans.");
        return;
    }
    setSaveStatus('saving');
    savePlan(currentPlan);
    setTimeout(() => setSaveStatus('saved'), 800);
    setTimeout(() => setSaveStatus('idle'), 3000);
  };

  const handleDownload = (section: 'plan' | 'notes' | 'questions') => {
    // Restrict download for guest users
    if (isGuest) {
        alert("Please sign in or create an account to download content.");
        return;
    }

    let title = '';
    let bodyContent = '';
    let fileNameSuffix = '';

    const commonHeader = `
        <h1>${currentPlan.topic}</h1>
        <p><strong>Teacher:</strong> ${currentPlan.teacherName} | <strong>School:</strong> ${currentPlan.schoolName}</p>
        <p><strong>Grade:</strong> ${currentPlan.grade} | <strong>Subject:</strong> ${currentPlan.subject} | <strong>Date:</strong> ${currentPlan.date} | <strong>Term:</strong> ${currentPlan.term}</p>
        <hr/>
    `;

    if (section === 'plan') {
        title = `Lesson Plan: ${currentPlan.lessonNumber}`;
        fileNameSuffix = 'Plan';
        bodyContent = `
          <div style="text-align: center; margin-bottom: 20px;">
            <h1 style="text-transform: uppercase; font-size: 18pt; margin-bottom: 10px;">Lesson Plan</h1>
            <p style="font-size: 12pt; margin: 5px 0;"><strong>Teacher:</strong> ${currentPlan.teacherName} &nbsp;|&nbsp; <strong>School:</strong> ${currentPlan.schoolName}</p>
            <p style="font-size: 12pt; margin: 5px 0;"><strong>Grade:</strong> ${currentPlan.grade} &nbsp;|&nbsp; <strong>Subject:</strong> ${currentPlan.subject}</p>
            <p style="font-size: 12pt; margin: 5px 0;"><strong>Date:</strong> ${currentPlan.date} &nbsp;|&nbsp; <strong>Term:</strong> ${currentPlan.term}</p>
          </div>
          <hr style="border: 1px solid #000; margin-bottom: 20px;" />

          <h2>${currentPlan.lessonNumber}</h2>

          <table style="width: 100%; border-collapse: collapse; margin-bottom: 15px; font-size: 11pt;">
            <tr>
                <td class="label">Strand</td>
                <td colspan="3">${currentPlan.strand}</td>
            </tr>
            <tr>
                <td class="label">Sub-strand</td>
                <td colspan="3">${currentPlan.subStrand}</td>
            </tr>
            <tr>
                <td class="label">Roll</td>
                <td>${currentPlan.roll}</td>
                <td class="label">Time</td>
                <td>40 Min</td>
            </tr>
          </table>

          <div class="section">
              <h3>Specific Learning Outcomes</h3>
              <ul>${currentPlan.learningOutcomes.map(o => `<li>${o}</li>`).join('')}</ul>
          </div>

          <div class="section">
              <h3>Key Inquiry Questions</h3>
              <ul>${currentPlan.keyInquiryQuestions.map(q => `<li>${q}</li>`).join('')}</ul>
          </div>

          <div class="section">
              <h3>Learning Resources</h3>
              <p>${currentPlan.learningResources.join(", ")}</p>
          </div>

          <div class="section">
              <h3>Introduction (5 min)</h3>
              <p>${currentPlan.introduction.replace(/\n/g, '<br/>')}</p>
          </div>

          <div class="section">
              <h3>Lesson Development (25 min)</h3>
              <p><strong>Step 1:</strong> ${currentPlan.developmentSteps.step1.replace(/\n/g, '<br/>')}</p>
              <p><strong>Step 2:</strong> ${currentPlan.developmentSteps.step2.replace(/\n/g, '<br/>')}</p>
              <p><strong>Step 3:</strong> ${currentPlan.developmentSteps.step3.replace(/\n/g, '<br/>')}</p>
          </div>

          <div class="section">
              <h3>Extended Activities</h3>
              <p>${currentPlan.extendedActivities.replace(/\n/g, '<br/>')}</p>
          </div>

          <div class="section">
              <h3>Conclusion (5 min)</h3>
              <p>${currentPlan.conclusion.replace(/\n/g, '<br/>')}</p>
          </div>

          <div class="section">
              <h3>Reflection</h3>
              <div style="height: 60px; border: 1px solid #000; margin-top: 5px;"></div>
          </div>
        `;
    } else if (section === 'notes') {
        title = "Simplified Learner Notes";
        fileNameSuffix = 'Notes';
        bodyContent = `
            ${commonHeader}
            <h2>Simplified Learner Notes</h2>
            <div class="content">
                ${currentPlan.learnerNotes?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    } else if (section === 'questions') {
        title = "Practice Questions";
        fileNameSuffix = 'Questions';
        bodyContent = `
            ${commonHeader}
            <h2>Practice Questions & Answers</h2>
            <div class="content">
                ${currentPlan.practiceQuestions?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    }

    const content = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
        <head>
          <meta charset="utf-8">
          <title>${title}</title>
          <style>
            body { font-family: 'Arial', sans-serif; font-size: 11pt; line-height: 1.4; color: #000; }
            h1 { font-size: 16pt; margin-bottom: 10px; font-weight: bold; }
            h2 { font-size: 14pt; margin-top: 15px; border-bottom: 1px solid #000; padding-bottom: 3px; color: #008080; }
            h3 { font-size: 12pt; margin-top: 10px; font-weight: bold; text-transform: uppercase; color: #444; }
            p, ul, li { margin-bottom: 5px; }
            table { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
            td { border: 1px solid #000; padding: 5px; vertical-align: top; }
            .label { font-weight: bold; background-color: #f0f0f0; width: 25%; }
            .section { margin-bottom: 15px; }
          </style>
        </head>
        <body>
          ${bodyContent}
        </body>
      </html>
    `;

    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileNameSuffix}-${currentPlan.date}-${currentPlan.subject}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleGenerateNotes = async () => {
    setLoadingNotes(true);
    try {
      const generatedNotes = await generateSimplifiedNotes(currentPlan);
      const updatedPlan = { ...currentPlan, learnerNotes: generatedNotes };
      setCurrentPlan(updatedPlan);
      // Automatically save if this plan was already saved
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(currentPlan);
      const updatedPlan = { ...currentPlan, practiceQuestions: generatedQuestions };
      setCurrentPlan(updatedPlan);
      // Automatically save if this plan was already saved
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Top Action Bar */}
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200 flex flex-wrap gap-4 justify-between items-center no-print sticky top-0 z-20">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors">
            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
        </button>

        <div className="flex flex-wrap gap-3">
             <button 
                onClick={handleSave}
                disabled={isGuest}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${saveStatus === 'saved' ? 'bg-green-100 text-green-800' : isGuest ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-50'}`}
                title={isGuest ? "Sign in to save plans" : "Save Plan"}
            >
                {isGuest ? <Lock className="w-4 h-4" /> : <Save className="w-4 h-4" />}
                {isGuest ? 'Sign in to Save' : saveStatus === 'saving' ? 'Saving...' : saveStatus === 'saved' ? 'Saved' : 'Save Plan'}
            </button>
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
                Print / PDF
            </button>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="flex border-b border-gray-200 no-print mb-6 overflow-x-auto">
        <button
            onClick={() => setActiveTab('plan')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'plan' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <Layout className="w-4 h-4" /> Lesson Plan
        </button>
        <button
            onClick={() => setActiveTab('notes')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'notes' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <FileText className="w-4 h-4" /> Learner Notes
        </button>
        <button
            onClick={() => setActiveTab('questions')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'questions' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <HelpCircle className="w-4 h-4" /> Practice Questions
        </button>
      </div>

      {/* Content Area */}
      <div id="lesson-plan-content" ref={componentRef} className="bg-white p-8 md:p-12 shadow-lg border border-gray-200 mx-auto max-w-4xl print:shadow-none print:border-none print:w-full print:max-w-none print:p-0 print:m-0">

        {/* Lesson Plan View */}
        {(activeTab === 'plan' || typeof window !== 'undefined' && window.matchMedia('print').matches) && (
            <div className={`${activeTab !== 'plan' ? 'hidden print:block' : ''}`}>
                {/* Header Table */}
                <div className="mb-8 border border-gray-800 text-sm">
                    <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Teacher</div>
                        <div className="col-span-2 p-2">{currentPlan.teacherName}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">School</div>
                        <div className="col-span-2 p-2">{currentPlan.schoolName}</div>
                    </div>
                    <div className="grid grid-cols-6 border-b border-gray-800 divide-x divide-gray-800">
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Date</div>
                        <div className="col-span-2 p-2">{currentPlan.date}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Subject</div>
                        <div className="col-span-2 p-2">{currentPlan.subject}</div>
                    </div>
                    <div className="grid grid-cols-8 divide-x divide-gray-800">
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Grade</div>
                        <div className="col-span-1 p-2 text-center">{currentPlan.grade}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Term</div>
                        <div className="col-span-1 p-2 text-center">{currentPlan.term}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Roll</div>
                        <div className="col-span-1 p-2 text-center">{currentPlan.roll}</div>
                        <div className="col-span-1 p-2 font-bold bg-gray-100">Time</div>
                        <div className="col-span-1 p-2 text-center">40 min</div>
                    </div>
                </div>

                <div className="space-y-6 text-gray-900 leading-relaxed text-sm">
                    <div className="bg-slate-50 p-4 rounded border border-slate-200 print:bg-transparent print:border-none print:p-0">
                        <p><span className="font-bold">Strand:</span> {currentPlan.strand}</p>
                        <p><span className="font-bold">Sub-strand:</span> {currentPlan.subStrand}</p>
                        <h2 className="font-bold text-lg mt-2 text-slate-800">{currentPlan.lessonNumber}</h2>
                    </div>

                    <div>
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Specific Learning Outcomes</h3>
                        <ul className="list-disc pl-5 space-y-1">
                            {currentPlan.learningOutcomes.map((outcome, i) => <li key={i}>{outcome}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Key Inquiry Questions</h3>
                        <ul className="list-disc pl-5 space-y-1">
                            {currentPlan.keyInquiryQuestions.map((q, i) => <li key={i}>{q}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Learning Resources</h3>
                        <p>{currentPlan.learningResources.join(", ")}</p>
                    </div>

                    <hr className="border-gray-300 my-4" />

                    <div className="prose max-w-none">
                        <h3 className="font-bold text-base mb-2 text-teal-800 print:text-black uppercase">Introduction (5 minutes)</h3>
                        <p className="whitespace-pre-wrap">{currentPlan.introduction}</p>
                    </div>

                    <div className="prose max-w-none">
                        <h3 className="font-bold text-base mb-4 text-teal-800 print:text-black uppercase">Lesson Development (25 minutes)</h3>
                        <div className="ml-4 border-l-2 border-teal-500 pl-4 space-y-4 print:border-l-0 print:pl-0">
                            <div><h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 1</h4><p className="whitespace-pre-wrap">{currentPlan.developmentSteps.step1}</p></div>
                            <div><h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 2</h4><p className="whitespace-pre-wrap">{currentPlan.developmentSteps.step2}</p></div>
                            <div><h4 className="font-bold text-sm text-gray-800 underline mb-1">Step 3</h4><p className="whitespace-pre-wrap">{currentPlan.developmentSteps.step3}</p></div>
