                        </div>
                    </div>
                ) : (
                    <div className="text-center py-12 bg-gray-50 rounded border border-dashed border-gray-300 no-print">
                        <p className="text-gray-500 mb-4">No questions generated yet for this lesson.</p>
                        <button 
                            onClick={handleGenerateQuestions}
                            disabled={loadingQuestions}
