      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(currentPlan);
      const updatedPlan = { ...currentPlan, practiceQuestions: generatedQuestions };
      setCurrentPlan(updatedPlan);
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  const handleConvertToGoogleForm = async () => {
    if (isGuest) {
      alert("Please sign in or create an account to use this feature.");
      return;
    }

    if (!currentPlan.practiceQuestions) {
      alert("Please generate practice questions first.");
      return;
    }

    setLoadingFormScript(true);
    try {
      const script = await generateGoogleFormScript(currentPlan.topic, currentPlan.practiceQuestions);
      setScriptContent(script);
      setShowScriptModal(true);
    } catch (error) {
      alert("Failed to generate form script. Please try again.");
    } finally {
      setLoadingFormScript(false);
    }
  };

