import React, { useState } from 'react';
import { Classroom, Assignment, StudentResult, QuizQuestion } from '../types';
import { getStudentClassroom, getAssignmentsByClassCode, saveStudentResult } from '../services/storageService';
import { BookOpen, Check, ChevronRight, GraduationCap, LogIn, User, Clock, AlertCircle } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'dashboard' | 'quiz' | 'result'>('login');
  const [classCode, setClassCode] = useState('');
  const [studentName, setStudentName] = useState('');
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);

  // Quiz State
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizResult, setQuizResult] = useState<{score: number, total: number} | null>(null);
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!classCode || !studentName) {
        setError("Please enter both Class Code and Name.");
        return;
    }

    const cls = getStudentClassroom(classCode.toUpperCase());
    if (cls) {
        setClassroom(cls);
        const tasks = getAssignmentsByClassCode(cls.code);
        setAssignments(tasks);
        setView('dashboard');
        setError('');
    } else {
        setError("Invalid Class Code. Please ask your teacher.");
    }
  };

  const startAssignment = (assignment: Assignment) => {
      setActiveAssignment(assignment);
      setCurrentQuestionIndex(0);
      setSelectedAnswers({});
      setQuizResult(null);
      setView('quiz');
  };

  const handleAnswerSelect = (option: string) => {
      setSelectedAnswers(prev => ({
          ...prev,
          [currentQuestionIndex]: option
      }));
  };

  const nextQuestion = () => {
      if (activeAssignment && currentQuestionIndex < activeAssignment.questions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const submitQuiz = () => {
      if (!activeAssignment) return;

      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          if (selectedAnswers[idx] === q.correctAnswer) {
              score++;
          }
      });

      const result: StudentResult = {
          assignmentId: activeAssignment.id,
          studentName: studentName,
          score: score,
          total: activeAssignment.questions.length,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);
      setQuizResult({ score, total: activeAssignment.questions.length });
      setView('result');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">

      {/* LOGIN VIEW */}
      {view === 'login' && (
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
            <div className="text-center mb-8">
                <div className="w-16 h-16 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center mx-auto mb-4">
                    <GraduationCap className="w-8 h-8" />
                </div>
                <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                <p className="text-gray-500">Enter your class code to view assignments</p>
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 flex items-center gap-2">
                    <AlertCircle className="w-4 h-4" /> {error}
                </div>
            )}

            <form onSubmit={handleLogin} className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Class Code</label>
                    <input 
                        type="text" 
                        value={classCode}
                        onChange={(e) => setClassCode(e.target.value.toUpperCase())}
                        className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-transparent font-mono uppercase tracking-widest text-center text-lg"
                        placeholder="XXXXXXX"
                        maxLength={7}
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Your Full Name</label>
                    <input 
                        type="text" 
                        value={studentName}
                        onChange={(e) => setStudentName(e.target.value)}
                        className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                        placeholder="John Doe"
                    />
                </div>
                <button type="submit" className="w-full bg-teal-600 text-white py-3 rounded-lg font-bold hover:bg-teal-700 transition-colors shadow-md flex justify-center items-center gap-2">
                    Enter Class <LogIn className="w-4 h-4" />
                </button>
            </form>
        </div>
      )}

      {/* DASHBOARD VIEW */}
      {view === 'dashboard' && classroom && (
          <div className="max-w-2xl w-full">
              <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden mb-6">
                  <div className="bg-slate-800 p-6 text-white flex justify-between items-center">
                      <div>
                          <h2 className="text-xl font-bold">{classroom.grade} - {classroom.stream}</h2>
                          <p className="text-slate-400 text-sm">{classroom.subject}</p>
                      </div>
                      <div className="text-right">
                          <p className="text-sm font-medium">{studentName}</p>
                          <button onClick={() => setView('login')} className="text-xs text-teal-400 hover:text-white underline">Logout</button>
                      </div>
                  </div>
              </div>

              <h3 className="text-lg font-bold text-gray-800 mb-4 px-2">Assignments</h3>

              <div className="space-y-3">
                  {assignments.length === 0 ? (
                      <div className="text-center py-12 text-gray-500 bg-white rounded-xl border border-dashed border-gray-300">
                          No assignments available at the moment.
                      </div>
                  ) : (
                      assignments.map(a => (
                          <div key={a.id} onClick={() => startAssignment(a)} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200 hover:border-teal-500 cursor-pointer transition-all flex justify-between items-center group">
                              <div className="flex items-center gap-4">
                                  <div className="bg-teal-50 p-3 rounded-lg text-teal-600 group-hover:bg-teal-600 group-hover:text-white transition-colors">
                                      <BookOpen className="w-6 h-6" />
                                  </div>
                                  <div>
                                      <h4 className="font-bold text-gray-800">{a.topic}</h4>
                                      <p className="text-sm text-gray-500">{a.questions.length} Questions</p>
                                  </div>
                              </div>
                              <ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" />
                          </div>
                      ))
                  )}
              </div>
          </div>
      )}

      {/* QUIZ VIEW */}
      {view === 'quiz' && activeAssignment && (
          <div className="max-w-xl w-full bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
              <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex justify-between items-center">
                  <span className="text-sm font-bold text-gray-500 uppercase tracking-wider">Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}</span>
                  <span className="text-xs bg-teal-100 text-teal-800 px-2 py-1 rounded-full font-bold">{activeAssignment.topic}</span>
              </div>

              <div className="p-8">
                  <h3 className="text-xl font-medium text-gray-800 mb-6 leading-relaxed">
                      {activeAssignment.questions[currentQuestionIndex].question}
                  </h3>

                  <div className="space-y-3">
                      {activeAssignment.questions[currentQuestionIndex].options.map((option, idx) => (
                          <button
                              key={idx}
                              onClick={() => handleAnswerSelect(option)}
                              className={`w-full text-left p-4 rounded-lg border-2 transition-all ${
                                  selectedAnswers[currentQuestionIndex] === option 
                                  ? 'border-teal-500 bg-teal-50 text-teal-900 font-medium' 
                                  : 'border-gray-200 hover:border-gray-300 text-gray-700'
                              }`}
                          >
                              {option}
                          </button>
                      ))}
                  </div>
              </div>

              <div className="p-6 bg-gray-50 border-t border-gray-200 flex justify-between">
                  <button 
                    onClick={() => setView('dashboard')}
                    className="text-gray-500 hover:text-gray-700 text-sm font-medium"
                  >
                      Cancel
                  </button>

                  {currentQuestionIndex < activeAssignment.questions.length - 1 ? (
                      <button 
                          onClick={nextQuestion}
                          disabled={!selectedAnswers[currentQuestionIndex]}
                          className="bg-slate-800 text-white px-6 py-2 rounded-lg font-medium hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      >
                          Next
                      </button>
                  ) : (
                      <button 
                          onClick={submitQuiz}
                          disabled={!selectedAnswers[currentQuestionIndex]}
                          className="bg-teal-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      >
                          Submit Quiz
                      </button>
                  )}
              </div>
          </div>
      )}

      {/* RESULT VIEW */}
      {view === 'result' && quizResult && (
          <div className="max-w-md w-full bg-white rounded-xl shadow-xl border border-gray-200 text-center p-10 animate-fade-in-up">
              <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                  <Check className="w-10 h-10 text-green-600" />
              </div>
              <h2 className="text-2xl font-bold text-gray-800 mb-2">Quiz Completed!</h2>
              <p className="text-gray-500 mb-8">You have successfully submitted your assignment.</p>

              <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 mb-8">
                  <p className="text-sm text-gray-500 uppercase tracking-widest font-bold mb-1">Your Score</p>
                  <p className="text-4xl font-black text-slate-800">
                      {quizResult.score} <span className="text-xl text-gray-400 font-normal">/ {quizResult.total}</span>
                  </p>
              </div>

              <button 
                  onClick={() => setView('dashboard')}
                  className="w-full bg-slate-800 text-white py-3 rounded-lg font-bold hover:bg-slate-700 transition-colors"
              >
                  Return to Dashboard
              </button>
          </div>
      )}

    </div>
  );
};

export default StudentPortal;

import React, { useState } from 'react';
import { UserProfile } from '../types';
import { Lock, User, School, Phone, Mail, ArrowRight, LogIn, AlertCircle, GraduationCap } from 'lucide-react';
import { loginUser, registerUser } from '../services/storageService';

interface Props {
  onLogin: (profile: UserProfile) => void;
  onStudentLoginClick: () => void;
  initialMode?: 'signin' | 'signup';
}

const Login: React.FC<Props> = ({ onLogin, onStudentLoginClick, initialMode = 'signup' }) => {
  const [isSignUp, setIsSignUp] = useState(initialMode === 'signup');
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState<UserProfile>({
    email: '',
    name: '',
    school: '',
    phone: '',
    password: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    try {
        if (isSignUp) {
            // Sign Up Logic
            if (formData.email && formData.name && formData.school && formData.phone && formData.password) {
                const user = registerUser(formData);
                onLogin(user);
            } else {
                setError("Please fill in all fields.");
            }
        } else {
            // Sign In Logic
            if (formData.email && formData.password) {
                const user = loginUser(formData.email, formData.password || '');
                onLogin(user);
            } else {
                setError("Please enter both email and password.");
            }
        }
    } catch (err: any) {
        setError(err.message || "Authentication failed.");
    }
  };

  return (
    <div className="min-h-[80vh] flex flex-col justify-center items-center p-4 bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden">
        <div className="bg-slate-900 px-6 py-8 text-center text-white">
          <div className="mx-auto bg-slate-800 w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-inner border border-slate-700">
            {isSignUp ? <User className="w-8 h-8 text-teal-400" /> : <LogIn className="w-8 h-8 text-teal-400" />}
          </div>
          <h2 className="text-2xl font-bold">{isSignUp ? "Create Account" : "Welcome Back"}</h2>
          <p className="text-slate-400 mt-2 text-sm">
            {isSignUp ? "Join MwalimuPlanner today" : "Sign in to continue planning"}
          </p>
        </div>

        <div className="p-8">
            {error && (
                <div className="mb-6 bg-red-50 text-red-600 p-3 rounded-md text-sm border border-red-200 flex items-start gap-2">
                    <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
                    <span>{error}</span>
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-5">
            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Mail className="h-5 w-5 text-gray-400" />
                </div>
                <input
                    type="email"
                    required
                    value={formData.email}
                    onChange={e => setFormData({...formData, email: e.target.value})}
                    className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                    placeholder="teacher@school.edu"
                />
                </div>
            </div>

            {isSignUp && (
                <>
                    <div className="animate-fade-in-up">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Official Name</label>
                        <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <User className="h-5 w-5 text-gray-400" />
                        </div>
                        <input
                            type="text"
                            required
                            value={formData.name}
                            onChange={e => setFormData({...formData, name: e.target.value})}
                            className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                            placeholder="Mr. / Ms. Full Name"
                        />
                        </div>
                    </div>

                    <div className="animate-fade-in-up">
                        <label className="block text-sm font-medium text-gray-700 mb-1">School Name</label>
                        <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <School className="h-5 w-5 text-gray-400" />
                        </div>
                        <input
                            type="text"
                            required
                            value={formData.school}
                            onChange={e => setFormData({...formData, school: e.target.value})}
                            className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                            placeholder="Official School Name"
                        />
                        </div>
                    </div>

                    <div className="animate-fade-in-up">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Contact Number</label>
                        <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <Phone className="h-5 w-5 text-gray-400" />
                        </div>
                        <input
                            type="tel"
                            required
                            value={formData.phone}
                            onChange={e => setFormData({...formData, phone: e.target.value})}
                            className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                            placeholder="07XX XXX XXX"
                        />
                        </div>
                    </div>
                </>
            )}

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Lock className="h-5 w-5 text-gray-400" />
                </div>
                <input
                    type="password"
                    required
                    value={formData.password}
                    onChange={e => setFormData({...formData, password: e.target.value})}
                    className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                    placeholder="••••••••"
                    minLength={6}
                />
                </div>
            </div>

            <button
                type="submit"
                className="w-full flex justify-center items-center gap-2 bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-6"
            >
                {isSignUp ? "Create Account" : "Sign In"} 
                <ArrowRight className="w-4 h-4" />
            </button>
            </form>

            <div className="mt-6 text-center space-y-4">
                <p className="text-sm text-gray-600">
                    {isSignUp ? "Already have an account?" : "Don't have an account yet?"}
                    <button 
                        onClick={() => {
                            setIsSignUp(!isSignUp);
                            setError(null);
                            setFormData({
                                email: '',
                                name: '',
                                school: '',
                                phone: '',
                                password: ''
                            });
                        }}
                        className="ml-2 text-teal-600 hover:text-teal-800 font-semibold focus:outline-none"
                    >
                        {isSignUp ? "Sign In" : "Sign Up"}
                    </button>
                </p>

                <div className="pt-4 border-t border-gray-100">
                    <button 
                        onClick={onStudentLoginClick}
                        className="inline-flex items-center gap-2 text-sm text-slate-500 hover:text-slate-800 font-medium px-4 py-2 rounded-full bg-slate-50 hover:bg-slate-100 transition-colors"
                    >
                        <GraduationCap className="w-4 h-4" />
                        I am a Student
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import LessonGenerator from './components/LessonGenerator';
import LessonPlanDisplay from './components/LessonPlanDisplay';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import LandingPage from './components/LandingPage';
import SavedPlans from './components/SavedPlans';
import NewsSection from './components/NewsSection';
import AdminDashboard from './components/AdminDashboard';
import StudentPortal from './components/StudentPortal';
import { LessonPlanData, UserProfile } from './types';
import { LayoutDashboard, FileText, LogOut, Save, Newspaper, Shield } from 'lucide-react';
import { getCurrentUser, logoutUser, updateUserProfile } from './services/storageService';

function App() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [generatedPlan, setGeneratedPlan] = useState<LessonPlanData | null>(null);
  const [currentView, setCurrentView] = useState<'landing' | 'auth' | 'generator' | 'dashboard' | 'saved' | 'news' | 'admin' | 'student'>('landing');
  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');

  // Check for existing session on load
  useEffect(() => {
    const savedUser = getCurrentUser();
    if (savedUser) {
        setUser(savedUser);
        if (savedUser.isAdmin) {
            setCurrentView('admin');
        } else {
            setCurrentView('generator'); // Skip landing if logged in as regular user
        }
    }
  }, []);

  const handleLogin = (profile: UserProfile) => {
    setUser(profile);
    if (profile.isAdmin) {
        setCurrentView('admin');
    } else {
        setCurrentView('generator');
    }
  };

  const handleUpdateProfile = (profile: UserProfile) => {
    updateUserProfile(profile);
    setUser(profile); // Update local state
  };

  const handleLogout = () => {
    logoutUser();
    setUser(null);
    setGeneratedPlan(null);
    setCurrentView('landing');
  };

  const navigateToAuth = (mode: 'signin' | 'signup') => {
      setAuthMode(mode);
      setCurrentView('auth');
  };

  // Handler for clicking the logo/header title
  const handleHomeClick = () => {
    if (currentView === 'student') {
        // Do nothing or maybe warn if in student mode
        return;
    }

    if (user) {
        if (user.isAdmin) {
            setCurrentView('admin');
        } else {
            setCurrentView('generator');
            setGeneratedPlan(null); // Reset generated plan view
        }
    } else {
        setCurrentView('landing');
        setGeneratedPlan(null); // Reset guest generated plan view
    }
  };

  // Special rendering for Student Portal (no header/footer usually desired, but keeping header for consistency)
  if (currentView === 'student') {
      return (
          <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
              <Header onHomeClick={() => setCurrentView('landing')} />
              <StudentPortal />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <Header onHomeClick={handleHomeClick} />

      <main className="flex-1">
        {/* Navigation State Logic */}

        {/* LANDING PAGE (Unauthenticated) */}
        {currentView === 'landing' && !user && (
            <LandingPage 
                onStart={() => navigateToAuth('signup')} 
                user={user}
                onLogout={handleLogout}
                onPlanGenerated={(plan) => {
                    setGeneratedPlan(plan);
                    // Stay in a state where we show the plan, but user is null
                }} 
            />
        )}

        {/* AUTH PAGE */}
        {currentView === 'auth' && !user && (
            <Login 
                onLogin={handleLogin} 
                initialMode={authMode} 
                onStudentLoginClick={() => setCurrentView('student')}
            />
        )}

        {/* LOGGED IN NAVIGATION */}
        {user && (
            <div className={`container mx-auto px-4 py-8 md:py-12 ${currentView === 'admin' ? 'max-w-full px-0 py-0' : 'max-w-5xl'}`}>
                {/* Navigation Bar for Authenticated Users */}
                <div className={`flex flex-wrap gap-4 justify-between items-center mb-8 border-b border-gray-200 pb-4 no-print ${currentView === 'admin' ? 'px-4 pt-4' : ''}`}>
                    <div className="flex gap-2 md:gap-4 overflow-x-auto pb-2 md:pb-0">
                        {user.isAdmin ? (
                            <button
                                onClick={() => setCurrentView('admin')}
                                className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'admin' ? 'bg-slate-800 text-white' : 'text-gray-600 hover:bg-gray-100'}`}
                            >
                                <Shield className="w-4 h-4" />
                                Admin Panel
                            </button>
                        ) : (
                            <>
                                <button
                                    onClick={() => {
                                        setCurrentView('generator');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'generator' && !generatedPlan ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <FileText className="w-4 h-4" />
                                    Planner
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('saved');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'saved' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <Save className="w-4 h-4" />
                                    Saved Plans
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('news');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'news' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <Newspaper className="w-4 h-4" />
                                    News
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('dashboard');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'dashboard' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <LayoutDashboard className="w-4 h-4" />
                                    Dashboard
                                </button>
                            </>
                        )}
                    </div>

                    <div className="flex items-center gap-4">
                        <span className="text-sm text-gray-500 hidden md:inline">
                            {user.isAdmin ? 'Administrator' : `Welcome, ${user.name}`}
                        </span>
                        <button
                            onClick={handleLogout}
                            className="flex items-center gap-2 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50 rounded-md transition-colors"
                        >
                            <LogOut className="w-4 h-4" />
                            Logout
                        </button>
                    </div>
                </div>

                {/* Authenticated Views */}
                {currentView === 'admin' ? (
                    <div className="animate-fade-in">
                        <AdminDashboard />
                    </div>
                ) : currentView === 'dashboard' ? (
                    <div className="animate-fade-in">
                        <Dashboard profile={user} onUpdate={handleUpdateProfile} />
                    </div>
                ) : currentView === 'saved' ? (
                    <div className="animate-fade-in">
                        <SavedPlans onSelectPlan={(plan) => {
                            setGeneratedPlan(plan);
                            setCurrentView('generator');
                        }} />
                    </div>
                ) : currentView === 'news' ? (
                    <div className="animate-fade-in">
                        <NewsSection />
                    </div>
                ) : generatedPlan ? (
                    <div className="animate-fade-in">
                        <LessonPlanDisplay 
                            plan={generatedPlan} 
                            onBack={() => setGeneratedPlan(null)} 
                        />
                    </div>
                ) : (
                    <div className="animate-fade-in-up">
                        <div className="text-center mb-8 no-print">
                            <h2 className="text-2xl font-semibold text-gray-800">Create Your Lesson Plan</h2>
                            <p className="text-gray-600 mt-2">Fill in the details below to generate a comprehensive, curriculum-aligned lesson plan in seconds.</p>
                        </div>
                        <LessonGenerator userProfile={user} onPlanGenerated={setGeneratedPlan} />
                    </div>
                )}
            </div>
        )}

        {/* GUEST GENERATED PLAN DISPLAY (Special Case) */}
        {!user && generatedPlan && (
             <div className="container mx-auto px-4 py-8 md:py-12 max-w-5xl animate-fade-in">
                <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-6 flex justify-between items-center">
                    <p className="text-sm text-yellow-700">
                        You are viewing this plan as a guest. <strong>Sign in</strong> to save it to your account.
                    </p>
                    <button 
                        onClick={() => navigateToAuth('signin')}
                        className="text-sm font-medium text-yellow-800 underline hover:text-yellow-900"
                    >
                        Sign In Now
                    </button>
                </div>
                <LessonPlanDisplay 
                    plan={generatedPlan} 
                    onBack={() => {
                        setGeneratedPlan(null);
                        setCurrentView('landing');
                    }} 
                />
            </div>
        )}

      </main>

      {/* Footer only if not in landing page (Landing has its own flow or style usually, but here we can keep it consistent or simple) */}
      <footer className="bg-slate-900 text-slate-400 py-8 text-center text-sm no-print mt-auto">
        <p>© {new Date().getFullYear()} MwalimuPlanner. All Rights Reserved.</p>
        <p className="mt-1">Empowering Kenyan Educators.</p>
      </footer>
    </div>
  );
}

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { LessonPlanData, Classroom, Assignment } from '../types';
import { Printer, Download, ArrowLeft, FileText, HelpCircle, Loader2, Save, Layout, Lock, Link, X, Copy, Check, Send } from 'lucide-react';
import { generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan, getCurrentUser, getClassrooms, saveAssignment } from '../services/storageService';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  const [currentPlan, setCurrentPlan] = useState<LessonPlanData>(plan);
  const [activeTab, setActiveTab] = useState<'plan' | 'notes' | 'questions'>('plan');

  const [loadingNotes, setLoadingNotes] = useState(false);
  const [loadingQuestions, setLoadingQuestions] = useState(false);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [isGuest, setIsGuest] = useState(false);

  // Assign to Class State
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [userClassrooms, setUserClassrooms] = useState<Classroom[]>([]);
  const [selectedClassCode, setSelectedClassCode] = useState<string>('');
  const [assigningStatus, setAssigningStatus] = useState<'idle' | 'assigning' | 'assigned'>('idle');

  useEffect(() => {
    setCurrentPlan(plan);
    const user = getCurrentUser();
    setIsGuest(!user);
    if (user) {
        setUserClassrooms(getClassrooms());
    }
  }, [plan]);

  const handlePrint = () => {
    window.print();
  };

  const handleSave = () => {
    if (isGuest) {
        alert("Please sign in or create an account to save lesson plans.");
        return;
    }
    setSaveStatus('saving');
    savePlan(currentPlan);
    setTimeout(() => setSaveStatus('saved'), 800);
    setTimeout(() => setSaveStatus('idle'), 3000);
  };

  const handleDownload = (section: 'plan' | 'notes' | 'questions') => {
    if (isGuest) {
        alert("Please sign in or create an account to download content.");
        return;
    }

    const isKiswahili = currentPlan.subject === 'Kiswahili';

    let title = '';
    let bodyContent = '';
    let fileNameSuffix = '';

    // STRICT FORMATTING FOR WORD EXPORT
    const metadataTable = `
      <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px; font-size: 10pt; font-family: Arial, sans-serif; border: 1px solid #000;">
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Teacher</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.teacherName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">School</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.schoolName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Date</td>
          <td style="border: 1px solid #000; padding: 4px; width: 10%;">${currentPlan.date}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Subject</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.subject}</td>
        </tr>
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Grade</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.grade}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Term</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.term}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Roll</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.roll}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Time</td>
          <td style="border: 1px solid #000; padding: 4px;">40 min</td>
        </tr>
      </table>
    `;

    if (section === 'plan') {
        title = `Lesson Plan - ${currentPlan.date}`;
        fileNameSuffix = 'Plan';
        bodyContent = `
          ${metadataTable}

          <div style="font-family: Arial, sans-serif; font-size: 10pt;">
            <p style="margin: 3px 0;"><strong>Strand:</strong> ${currentPlan.strand}</p>
            <p style="margin: 3px 0;"><strong>Sub-strand:</strong> ${currentPlan.subStrand}</p>
            <p style="margin: 10px 0; font-weight: bold; text-transform: uppercase;">${currentPlan.topic.toUpperCase()}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">SPECIFIC LEARNING OUTCOMES</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.learningOutcomes.map(o => `<li>${o}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">KEY INQUIRY QUESTIONS</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.keyInquiryQuestions.map(q => `<li>${q}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LEARNING RESOURCES</p>
            <p style="margin-top: 0;">${currentPlan.learningResources.join(", ")}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">INTRODUCTION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.introduction}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LESSON DEVELOPMENT (25 MIN)</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 1:</strong> ${currentPlan.developmentSteps.step1}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 2:</strong> ${currentPlan.developmentSteps.step2}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 3:</strong> ${currentPlan.developmentSteps.step3}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">EXTENDED ACTIVITIES</p>
            <p style="margin-top: 0;">${currentPlan.extendedActivities}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">CONCLUSION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.conclusion}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">REFLECTION</p>
            <div style="height: 60px; border: 1px solid #000; width: 100%;"></div>
          </div>
        `;
    } else if (section === 'notes') {
        // Notes export keeps simple format
        title = 'Learner Notes';
        fileNameSuffix = 'Notes';
        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Simplified Learner Notes</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${currentPlan.learnerNotes?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    } else if (section === 'questions') {
        // Questions export keeps simple format
        title = 'Practice Questions';
        fileNameSuffix = 'Questions';
        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Practice Questions</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${currentPlan.practiceQuestions?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    }

    const content = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
        <head>
          <meta charset="utf-8">
          <title>${title}</title>
          <style>
            body { font-family: 'Arial', sans-serif; font-size: 10pt; }
          </style>
        </head>
        <body>
          ${bodyContent}
        </body>
      </html>
    `;

    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileNameSuffix}-${currentPlan.date}-${currentPlan.subject}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleGenerateNotes = async () => {
    setLoadingNotes(true);
    try {
      const generatedNotes = await generateSimplifiedNotes(currentPlan);
      const updatedPlan = { ...currentPlan, learnerNotes: generatedNotes };
      setCurrentPlan(updatedPlan);
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(currentPlan);
      const textRepresentation = generatedQuestions.map((q, i) => 
        `${i+1}. ${q.question}\nA) ${q.options[0]}\nB) ${q.options[1]}\nC) ${q.options[2]}\nD) ${q.options[3]}\nAnswer: ${q.correctAnswer}`
      ).join('\n\n');

      const updatedPlan = { 
          ...currentPlan, 
          practiceQuestions: textRepresentation, 
          structuredQuestions: generatedQuestions 
      };

      setCurrentPlan(updatedPlan);
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  const handleAssignToClass = () => {
    if (isGuest) {
      alert("Please sign in to assign work to classes.");
      return;
    }
    if (!currentPlan.structuredQuestions || currentPlan.structuredQuestions.length === 0) {
      alert("Please generate practice questions first.");
      return;
    }
    if (userClassrooms.length === 0) {
        alert("You have no active classrooms. Go to your Dashboard to create one.");
        return;
    }
    setShowAssignModal(true);
  };

  const confirmAssignment = () => {
      if (!selectedClassCode) return;
      setAssigningStatus('assigning');

      const assignment: Assignment = {
          id: crypto.randomUUID(),
          classCode: selectedClassCode,
          topic: currentPlan.topic,
          questions: currentPlan.structuredQuestions || [],
          createdAt: new Date().toISOString()
      };

      saveAssignment(assignment);

      setTimeout(() => {
          setAssigningStatus('assigned');
          setTimeout(() => {
              setShowAssignModal(false);
              setAssigningStatus('idle');
              setSelectedClassCode('');
          }, 1500);
      }, 1000);
  };

  return (
    <div className="space-y-6">
      {/* Top Action Bar */}
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200 flex flex-wrap gap-4 justify-between items-center no-print sticky top-0 z-20">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors">
            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
        </button>

        <div className="flex flex-wrap gap-3">
             <button 
                onClick={handleSave}
                disabled={isGuest}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${saveStatus === 'saved' ? 'bg-green-100 text-green-800' : isGuest ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-50'}`}
            >
                {isGuest ? <Lock className="w-4 h-4" /> : <Save className="w-4 h-4" />}
                {isGuest ? 'Sign in to Save' : saveStatus === 'saving' ? 'Saving...' : saveStatus === 'saved' ? 'Saved' : 'Save Plan'}
            </button>
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
                Print / PDF
            </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-gray-200 no-print mb-6 overflow-x-auto">
        <button
            onClick={() => setActiveTab('plan')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'plan' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <Layout className="w-4 h-4" /> Lesson Plan
        </button>
        <button
            onClick={() => setActiveTab('notes')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'notes' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <FileText className="w-4 h-4" /> Learner Notes
        </button>
        <button
            onClick={() => setActiveTab('questions')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'questions' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <HelpCircle className="w-4 h-4" /> Practice Questions
        </button>
      </div>

      {/* Content Area */}
      <div id="lesson-plan-content" ref={componentRef} className="bg-white p-8 md:p-12 shadow-lg border border-gray-200 mx-auto max-w-4xl print:shadow-none print:border-none print:w-full print:max-w-none print:p-0 print:m-0 font-sans">

        {/* Lesson Plan Text Content - Strict Layout */}
        {(activeTab === 'plan' || typeof window !== 'undefined' && window.matchMedia('print').matches) && (
            <div className={`${activeTab !== 'plan' ? 'hidden print:block' : ''}`}>
                {/* Strict Table Layout for Header */}
                <div className="border border-black mb-6 text-sm">
                    <div className="grid grid-cols-8 border-b border-black divide-x divide-black">
                        <div className="col-span-1 p-2 font-bold bg-white">Teacher</div>
                        <div className="col-span-2 p-2">{currentPlan.teacherName}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">School</div>
                        <div className="col-span-2 p-2">{currentPlan.schoolName}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Date</div>
                        <div className="col-span-1 p-2">{currentPlan.date}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Subject</div>
                        <div className="col-span-2 p-2">{currentPlan.subject}</div>
                    </div>
                    <div className="grid grid-cols-8 divide-x divide-black">
                        <div className="col-span-1 p-2 font-bold bg-white">Grade</div>
                        <div className="col-span-1 p-2">{currentPlan.grade}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Term</div>
                        <div className="col-span-1 p-2">{currentPlan.term}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Roll</div>
                        <div className="col-span-1 p-2">{currentPlan.roll}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Time</div>
                        <div className="col-span-1 p-2">40 min</div>
                    </div>
                </div>

                <div className="space-y-4 text-black text-sm">
                    <div>
                        <p><strong>Strand:</strong> {currentPlan.strand}</p>
                        <p><strong>Sub-strand:</strong> {currentPlan.subStrand}</p>
                        <p className="font-bold uppercase mt-2">{currentPlan.topic.toUpperCase()}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">SPECIFIC LEARNING OUTCOMES</h3>
                        <ul className="list-disc pl-5">
                            {currentPlan.learningOutcomes.map((outcome, i) => <li key={i}>{outcome}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">KEY INQUIRY QUESTIONS</h3>
                        <ul className="list-disc pl-5">
                            {currentPlan.keyInquiryQuestions.map((q, i) => <li key={i}>{q}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">LEARNING RESOURCES</h3>
                        <p>{currentPlan.learningResources.join(", ")}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">INTRODUCTION (5 MIN)</h3>
                        <p>{currentPlan.introduction}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">LESSON DEVELOPMENT (25 MIN)</h3>
                        <div className="space-y-2">
                            <p><strong>Step 1:</strong> {currentPlan.developmentSteps.step1}</p>
                            <p><strong>Step 2:</strong> {currentPlan.developmentSteps.step2}</p>
                            <p><strong>Step 3:</strong> {currentPlan.developmentSteps.step3}</p>
                        </div>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">EXTENDED ACTIVITIES</h3>
                        <p>{currentPlan.extendedActivities}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">CONCLUSION (5 MIN)</h3>
                        <p>{currentPlan.conclusion}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">REFLECTION</h3>
                        <div className="h-16 border border-black w-full"></div>
                    </div>

                    {/* Bottom Download Button for Plan */}
                    <div className="mt-8 flex justify-center no-print">
                        <button 
                            onClick={() => handleDownload('plan')}
                            disabled={isGuest}
                            className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium ${isGuest ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-teal-600 text-white hover:bg-teal-700'}`}
                            title={isGuest ? "Sign in to download" : "Download Word Document"}
                        >
                            {isGuest ? <Lock className="w-5 h-5" /> : <Download className="w-5 h-5" />}
                            {isGuest ? "Sign In to Download" : "Download Lesson Plan (Word)"}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* Notes View */}
        {(activeTab === 'notes' || typeof window !== 'undefined' && window.matchMedia('print').matches && currentPlan.learnerNotes) && (
            <div className={`${activeTab !== 'notes' ? 'hidden print:block print:break-before-page' : ''}`}>
                <h2 className="text-xl font-bold mb-4 text-teal-900 border-b pb-2">Simplified Learner Notes</h2>

                {currentPlan.learnerNotes ? (
                    <div className="space-y-8">
                        <div className="prose max-w-none whitespace-pre-wrap text-sm bg-gray-50 p-6 rounded-lg border border-gray-200 print:bg-transparent print:border-none print:p-0">
                            {currentPlan.learnerNotes}
                        </div>
                        {/* Bottom Download Button for Notes */}
                        <div className="flex justify-center no-print">
                            <button 
                                onClick={() => handleDownload('notes')}
                                disabled={isGuest}
                                className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium ${isGuest ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-teal-600 text-white hover:bg-teal-700'}`}
                            >
                                {isGuest ? <Lock className="w-5 h-5" /> : <Download className="w-5 h-5" />}
                                {isGuest ? "Sign In to Download" : "Download Notes (Word)"}
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="text-center py-12 bg-gray-50 rounded border border-dashed border-gray-300 no-print">
                        <p className="text-gray-500 mb-4">No notes generated yet.</p>
                        <button onClick={handleGenerateNotes} disabled={loadingNotes} className="inline-flex items-center gap-2 bg-teal-600 text-white px-6 py-2 rounded-md hover:bg-teal-700">
                            {loadingNotes ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />} Generate Notes
                        </button>
                    </div>
                )}
            </div>
        )}

        {/* Questions View */}
        {(activeTab === 'questions' || typeof window !== 'undefined' && window.matchMedia('print').matches && currentPlan.practiceQuestions) && (
            <div className={`${activeTab !== 'questions' ? 'hidden print:block print:break-before-page' : ''}`}>
                <h2 className="text-xl font-bold mb-4 text-teal-900 border-b pb-2">Practice Questions</h2>

                {currentPlan.practiceQuestions ? (
                    <div className="space-y-8">
                        <div className="prose max-w-none whitespace-pre-wrap text-sm bg-gray-50 p-6 rounded-lg border border-gray-200 print:bg-transparent print:border-none print:p-0">
                            {currentPlan.practiceQuestions}
                        </div>

                        <div className="flex flex-wrap justify-center gap-4 no-print">
                            <button onClick={handleDownload('questions')} disabled={isGuest} className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium ${isGuest ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-teal-600 text-white hover:bg-teal-700'}`}>
                                {isGuest ? <Lock className="w-5 h-5" /> : <Download className="w-5 h-5" />}
                                {isGuest ? "Sign In to Download" : "Download Questions (Word)"}
                            </button>
                            <button onClick={handleAssignToClass} disabled={isGuest} className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium border ${isGuest ? 'bg-gray-100 text-gray-400 border-gray-200 cursor-not-allowed' : 'bg-white text-teal-700 border-teal-600 hover:bg-teal-50'}`}>
                                {isGuest ? <Lock className="w-5 h-5" /> : <Send className="w-5 h-5" />}
                                {isGuest ? "Sign In to Assign" : "Assign to Class"}
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="text-center py-12 bg-gray-50 rounded border border-dashed border-gray-300 no-print">
                        <p className="text-gray-500 mb-4">No questions generated yet.</p>
                        <button onClick={handleGenerateQuestions} disabled={loadingQuestions} className="inline-flex items-center gap-2 bg-teal-600 text-white px-6 py-2 rounded-md hover:bg-teal-700">
                            {loadingQuestions ? <Loader2 className="w-4 h-4 animate-spin" /> : <HelpCircle className="w-4 h-4" />} Generate Questions
                        </button>
                    </div>
                )}
            </div>
        )}
      </div>

      {/* Assign to Class Modal */}
      {showAssignModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden">
            <div className="flex justify-between items-center p-6 border-b border-gray-200 bg-gray-50">
              <h3 className="text-lg font-bold text-gray-800">Assign to Classroom</h3>
              <button onClick={() => setShowAssignModal(false)} className="text-gray-400 hover:text-gray-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6">
                <p className="text-gray-600 mb-4">Select a class to assign these {currentPlan.structuredQuestions?.length} questions to:</p>
                <div className="space-y-3">
                    {userClassrooms.map(c => (
                        <label key={c.id} className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-all ${selectedClassCode === c.code ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                            <div>
                                <div className="font-bold text-gray-800">{c.grade} - {c.stream}</div>
                                <div className="text-xs text-gray-500">{c.subject} • {c.code}</div>
                            </div>
                            <input 
                                type="radio" 
                                name="classroom" 
                                className="text-teal-600 focus:ring-teal-500"
                                checked={selectedClassCode === c.code}
                                onChange={() => setSelectedClassCode(c.code)}
                            />
                        </label>
                    ))}
                </div>
            </div>

            <div className="p-6 border-t border-gray-200 bg-gray-50 text-right">
              <button 
                onClick={confirmAssignment}
                disabled={!selectedClassCode || assigningStatus !== 'idle'}
                className={`w-full py-2.5 rounded-lg font-bold text-white transition-colors flex justify-center items-center gap-2 ${assigningStatus === 'assigned' ? 'bg-green-600' : 'bg-teal-600 hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed'}`}
              >
                {assigningStatus === 'assigning' ? <Loader2 className="w-5 h-5 animate-spin" /> : assigningStatus === 'assigned' ? <Check className="w-5 h-5" /> : null}
                {assigningStatus === 'assigning' ? 'Assigning...' : assigningStatus === 'assigned' ? 'Assigned Successfully!' : 'Confirm Assignment'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

