import React, { useState } from 'react';
import { Classroom, Assignment, StudentResult, Student } from '../types';
import { authenticateStudent, getAssignmentsByClassId, saveStudentResult } from '../services/storageService';
import { BookOpen, Check, ChevronRight, GraduationCap, LogIn, AlertCircle, Key, ArrowLeft, LayoutDashboard } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'dashboard' | 'assignments' | 'quiz' | 'result'>('login');
  const [accessCode, setAccessCode] = useState('');

  // Session State
  const [currentStudent, setCurrentStudent] = useState<Student | null>(null);
  const [currentClassroom, setCurrentClassroom] = useState<Classroom | null>(null);
  const [classAssignments, setClassAssignments] = useState<Assignment[]>([]);

  // View State
  const [selectedSubject, setSelectedSubject] = useState<string | null>(null);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);

  // Quiz State
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizResult, setQuizResult] = useState<{score: number, total: number} | null>(null);
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!accessCode) {
        setError("Please enter your Access Code.");
        return;
    }

    const authResult = authenticateStudent(accessCode.toUpperCase());
    if (authResult) {
        setCurrentStudent(authResult.student);
        setCurrentClassroom(authResult.classroom);

        // Load assignments for this class
        const tasks = getAssignmentsByClassId(authResult.classroom.id);
        setClassAssignments(tasks);

        setView('dashboard');
        setAccessCode('');
    } else {
        setError("Invalid Access Code. Please check and try again.");
    }
  };

  const handleSubjectSelect = (subject: string) => {
      setSelectedSubject(subject);
      setView('assignments');
  };

  const filteredAssignments = selectedSubject 
    ? classAssignments.filter(a => a.subject === selectedSubject)
    : [];

  const startAssignment = (assignment: Assignment) => {
      setActiveAssignment(assignment);
      setCurrentQuestionIndex(0);
      setSelectedAnswers({});
      setQuizResult(null);
      setView('quiz');
  };

  const handleAnswerSelect = (option: string) => {
      setSelectedAnswers(prev => ({
          ...prev,
          [currentQuestionIndex]: option
      }));
  };

  const nextQuestion = () => {
      if (activeAssignment && currentQuestionIndex < activeAssignment.questions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const submitQuiz = () => {
      if (!activeAssignment || !currentStudent) return;

      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          if (selectedAnswers[idx] === q.correctAnswer) {
              score++;
          }
      });

      const result: StudentResult = {
          assignmentId: activeAssignment.id,
          studentName: currentStudent.name || `Index ${currentStudent.index}`,
          score: score,
          total: activeAssignment.questions.length,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);
      setQuizResult({ score, total: activeAssignment.questions.length });
      setView('result');
  };

  const handleLogout = () => {
      setCurrentStudent(null);
      setCurrentClassroom(null);
      setView('login');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">

      {/* LOGIN VIEW */}
      {view === 'login' && (
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
            <div className="text-center mb-8">
                <div className="w-16 h-16 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center mx-auto mb-4">
                    <GraduationCap className="w-8 h-8" />
                </div>
                <h2 className="text-2xl font-bold text-gray-800">Student Login</h2>
                <p className="text-gray-500">Enter the access code provided by your teacher</p>
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 flex items-center gap-2">
                    <AlertCircle className="w-4 h-4" /> {error}
                </div>
            )}

            <form onSubmit={handleLogin} className="space-y-6">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                    <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <Key className="h-5 w-5 text-gray-400" />
                        </div>
                        <input 
                            type="text" 
                            value={accessCode}
                            onChange={(e) => setAccessCode(e.target.value.toUpperCase())}
                            className="w-full pl-10 px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-transparent font-mono uppercase tracking-widest text-center text-lg"
                            placeholder="XXXXXX"
                            maxLength={6}
                        />
                    </div>
                </div>
                <button type="submit" className="w-full bg-teal-600 text-white py-3 rounded-lg font-bold hover:bg-teal-700 transition-colors shadow-md flex justify-center items-center gap-2">
                    Enter Dashboard <LogIn className="w-4 h-4" />
                </button>
            </form>
        </div>
      )}

      {/* LOGGED IN HEADER */}
      {currentStudent && currentClassroom && view !== 'login' && (
          <div className="w-full max-w-2xl fixed top-0 left-0 right-0 mx-auto p-4 z-10">
              <div className="bg-slate-800 rounded-xl shadow-lg p-4 text-white flex justify-between items-center">
                  <div>
                      <h2 className="font-bold text-lg">{currentClassroom.grade} - {currentClassroom.stream}</h2>
                      <p className="text-slate-400 text-xs">Student Index: #{currentStudent.index}</p>
                  </div>
                  <button onClick={handleLogout} className="text-xs bg-slate-700 hover:bg-slate-600 px-3 py-1.5 rounded-full transition-colors">
                      Sign Out
                  </button>
              </div>
          </div>
      )}

      {/* DASHBOARD VIEW */}
      {view === 'dashboard' && currentClassroom && (
          <div className="max-w-2xl w-full mt-24">
              <div className="mb-6">
                  <h3 className="text-xl font-bold text-gray-800">My Subjects</h3>
                  <p className="text-gray-500 text-sm">Select a subject to view assignments</p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {currentClassroom.subjects.length === 0 ? (
                      <div className="col-span-2 text-center py-12 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500">
                          No subjects added to this class yet.
                      </div>
                  ) : (
                      currentClassroom.subjects.map(subject => {
                          const count = classAssignments.filter(a => a.subject === subject).length;
                          return (
                              <button 
                                  key={subject} 
                                  onClick={() => handleSubjectSelect(subject)}
                                  className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 hover:border-teal-500 hover:shadow-md transition-all text-left group"
                              >
                                  <h4 className="font-bold text-gray-800 group-hover:text-teal-600 mb-1">{subject}</h4>
                                  <div className="flex justify-between items-center">
                                      <span className="text-xs font-medium text-gray-500 bg-gray-100 px-2 py-1 rounded-full">
                                          {count} Assignments
                                      </span>
                                      <ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" />
                                  </div>
                              </button>
                          );
                      })
                  )}
              </div>
          </div>
      )}

      {/* ASSIGNMENTS VIEW */}
      {view === 'assignments' && (
          <div className="max-w-2xl w-full mt-24">
              <button 
                  onClick={() => setView('dashboard')}
                  className="flex items-center gap-2 text-gray-500 hover:text-gray-800 mb-6 font-medium"
              >
                  <ArrowLeft className="w-4 h-4" /> Back to Subjects
              </button>

              <div className="flex items-center gap-3 mb-6">
                  <div className="w-10 h-10 bg-teal-100 text-teal-600 rounded-lg flex items-center justify-center">
                      <BookOpen className="w-6 h-6" />
                  </div>
                  <h3 className="text-xl font-bold text-gray-800">{selectedSubject} Assignments</h3>
              </div>

              <div className="space-y-3">
                  {filteredAssignments.length === 0 ? (
                      <div className="text-center py-12 text-gray-500 bg-white rounded-xl border border-dashed border-gray-300">
                          No active assignments for {selectedSubject}.
                      </div>
                  ) : (
                      filteredAssignments.map(a => (
                          <div key={a.id} onClick={() => startAssignment(a)} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200 hover:border-teal-500 cursor-pointer transition-all flex justify-between items-center group">
                              <div>
                                  <h4 className="font-bold text-gray-800 group-hover:text-teal-600">{a.topic}</h4>
                                  <p className="text-sm text-gray-500 mt-1">{a.questions.length} Questions</p>
                              </div>
                              <div className="bg-teal-50 text-teal-700 px-4 py-2 rounded-lg text-sm font-bold group-hover:bg-teal-600 group-hover:text-white transition-colors">
                                  Start
                              </div>
                          </div>
                      ))
                  )}
              </div>
          </div>
      )}

      {/* QUIZ VIEW */}
      {view === 'quiz' && activeAssignment && (
          <div className="max-w-xl w-full bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden mt-20">
              <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex justify-between items-center">
                  <span className="text-sm font-bold text-gray-500 uppercase tracking-wider">Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}</span>
                  <span className="text-xs bg-teal-100 text-teal-800 px-2 py-1 rounded-full font-bold">{activeAssignment.topic}</span>
              </div>

              <div className="p-8">
                  <h3 className="text-xl font-medium text-gray-800 mb-6 leading-relaxed">
                      {activeAssignment.questions[currentQuestionIndex].question}
                  </h3>

                  <div className="space-y-3">
                      {activeAssignment.questions[currentQuestionIndex].options.map((option, idx) => (
                          <button
                              key={idx}
                              onClick={() => handleAnswerSelect(option)}
                              className={`w-full text-left p-4 rounded-lg border-2 transition-all ${
                                  selectedAnswers[currentQuestionIndex] === option 
                                  ? 'border-teal-500 bg-teal-50 text-teal-900 font-medium' 
                                  : 'border-gray-200 hover:border-gray-300 text-gray-700'
                              }`}
                          >
                              {option}
                          </button>
                      ))}
                  </div>
              </div>

              <div className="p-6 bg-gray-50 border-t border-gray-200 flex justify-between">
                  <button 
                    onClick={() => setView('assignments')}
                    className="text-gray-500 hover:text-gray-700 text-sm font-medium"
                  >
                      Cancel
                  </button>

                  {currentQuestionIndex < activeAssignment.questions.length - 1 ? (
                      <button 
                          onClick={nextQuestion}
                          disabled={!selectedAnswers[currentQuestionIndex]}
                          className="bg-slate-800 text-white px-6 py-2 rounded-lg font-medium hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      >
                          Next
                      </button>
                  ) : (
                      <button 
                          onClick={submitQuiz}
                          disabled={!selectedAnswers[currentQuestionIndex]}
                          className="bg-teal-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      >
                          Submit Quiz
                      </button>
                  )}
              </div>
          </div>
      )}

      {/* RESULT VIEW */}
      {view === 'result' && quizResult && (
          <div className="max-w-md w-full bg-white rounded-xl shadow-xl border border-gray-200 text-center p-10 animate-fade-in-up mt-20">
              <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                  <Check className="w-10 h-10 text-green-600" />
              </div>
              <h2 className="text-2xl font-bold text-gray-800 mb-2">Quiz Completed!</h2>
              <p className="text-gray-500 mb-8">You have successfully submitted your assignment.</p>

              <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 mb-8">
                  <p className="text-sm text-gray-500 uppercase tracking-widest font-bold mb-1">Your Score</p>
                  <p className="text-4xl font-black text-slate-800">
                      {quizResult.score} <span className="text-xl text-gray-400 font-normal">/ {quizResult.total}</span>
                  </p>
              </div>

              <button 
                  onClick={() => setView('assignments')}
                  className="w-full bg-slate-800 text-white py-3 rounded-lg font-bold hover:bg-slate-700 transition-colors"
              >
                  Back to Assignments
              </button>
          </div>
      )}

    </div>
  );
};

export default StudentPortal;

import React, { useRef, useState, useEffect } from 'react';
import { LessonPlanData, Classroom, Assignment } from '../types';
import { Printer, Download, ArrowLeft, FileText, HelpCircle, Loader2, Save, Layout, Lock, Link, X, Copy, Check, Send } from 'lucide-react';
import { generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan, getCurrentUser, getClassrooms, saveAssignment } from '../services/storageService';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  const [currentPlan, setCurrentPlan] = useState<LessonPlanData>(plan);
  const [activeTab, setActiveTab] = useState<'plan' | 'notes' | 'questions'>('plan');

  const [loadingNotes, setLoadingNotes] = useState(false);
  const [loadingQuestions, setLoadingQuestions] = useState(false);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [isGuest, setIsGuest] = useState(false);

  // Assign to Class State
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [userClassrooms, setUserClassrooms] = useState<Classroom[]>([]);
  const [selectedClassId, setSelectedClassId] = useState<string>('');
  const [assigningStatus, setAssigningStatus] = useState<'idle' | 'assigning' | 'assigned'>('idle');

  useEffect(() => {
    setCurrentPlan(plan);
    const user = getCurrentUser();
    setIsGuest(!user);
    if (user) {
        setUserClassrooms(getClassrooms());
    }
  }, [plan]);

  const handlePrint = () => {
    window.print();
  };

  const handleSave = () => {
    if (isGuest) {
        alert("Please sign in or create an account to save lesson plans.");
        return;
    }
    setSaveStatus('saving');
    savePlan(currentPlan);
    setTimeout(() => setSaveStatus('saved'), 800);
    setTimeout(() => setSaveStatus('idle'), 3000);
  };

  const handleDownload = (section: 'plan' | 'notes' | 'questions') => {
    if (isGuest) {
        alert("Please sign in or create an account to download content.");
        return;
    }

    const isKiswahili = currentPlan.subject === 'Kiswahili';

    let title = '';
    let bodyContent = '';
    let fileNameSuffix = '';

    // STRICT FORMATTING FOR WORD EXPORT
    const metadataTable = `
      <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px; font-size: 10pt; font-family: Arial, sans-serif; border: 1px solid #000;">
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Teacher</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.teacherName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">School</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.schoolName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Date</td>
          <td style="border: 1px solid #000; padding: 4px; width: 10%;">${currentPlan.date}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Subject</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.subject}</td>
        </tr>
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Grade</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.grade}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Term</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.term}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Roll</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.roll}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Time</td>
          <td style="border: 1px solid #000; padding: 4px;">40 min</td>
        </tr>
      </table>
    `;

    if (section === 'plan') {
        title = `Lesson Plan - ${currentPlan.date}`;
        fileNameSuffix = 'Plan';
        bodyContent = `
          ${metadataTable}

          <div style="font-family: Arial, sans-serif; font-size: 10pt;">
            <p style="margin: 3px 0;"><strong>Strand:</strong> ${currentPlan.strand}</p>
            <p style="margin: 3px 0;"><strong>Sub-strand:</strong> ${currentPlan.subStrand}</p>
            <p style="margin: 10px 0; font-weight: bold; text-transform: uppercase;">${currentPlan.topic.toUpperCase()}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">SPECIFIC LEARNING OUTCOMES</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.learningOutcomes.map(o => `<li>${o}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">KEY INQUIRY QUESTIONS</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.keyInquiryQuestions.map(q => `<li>${q}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LEARNING RESOURCES</p>
            <p style="margin-top: 0;">${currentPlan.learningResources.join(", ")}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">INTRODUCTION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.introduction}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LESSON DEVELOPMENT (25 MIN)</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 1:</strong> ${currentPlan.developmentSteps.step1}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 2:</strong> ${currentPlan.developmentSteps.step2}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 3:</strong> ${currentPlan.developmentSteps.step3}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">EXTENDED ACTIVITIES</p>
            <p style="margin-top: 0;">${currentPlan.extendedActivities}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">CONCLUSION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.conclusion}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">REFLECTION</p>
            <div style="height: 60px; border: 1px solid #000; width: 100%;"></div>
          </div>
        `;
    } else if (section === 'notes') {
        // Notes export keeps simple format
        title = 'Learner Notes';
        fileNameSuffix = 'Notes';
        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Simplified Learner Notes</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${currentPlan.learnerNotes?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    } else if (section === 'questions') {
        // Questions export keeps simple format
        title = 'Practice Questions';
        fileNameSuffix = 'Questions';
        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Practice Questions</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${currentPlan.practiceQuestions?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    }

    const content = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
        <head>
          <meta charset="utf-8">
          <title>${title}</title>
          <style>
            body { font-family: 'Arial', sans-serif; font-size: 10pt; }
          </style>
        </head>
        <body>
          ${bodyContent}
        </body>
      </html>
    `;

    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileNameSuffix}-${currentPlan.date}-${currentPlan.subject}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleGenerateNotes = async () => {
    setLoadingNotes(true);
    try {
      const generatedNotes = await generateSimplifiedNotes(currentPlan);
      const updatedPlan = { ...currentPlan, learnerNotes: generatedNotes };
      setCurrentPlan(updatedPlan);
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(currentPlan);
      const textRepresentation = generatedQuestions.map((q, i) => 
        `${i+1}. ${q.question}\nA) ${q.options[0]}\nB) ${q.options[1]}\nC) ${q.options[2]}\nD) ${q.options[3]}\nAnswer: ${q.correctAnswer}`
      ).join('\n\n');

      const updatedPlan = { 
          ...currentPlan, 
          practiceQuestions: textRepresentation, 
          structuredQuestions: generatedQuestions 
      };

      setCurrentPlan(updatedPlan);
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  const handleAssignToClass = () => {
    if (isGuest) {
      alert("Please sign in to assign work to classes.");
      return;
    }
    if (!currentPlan.structuredQuestions || currentPlan.structuredQuestions.length === 0) {
      alert("Please generate practice questions first.");
      return;
    }
    if (userClassrooms.length === 0) {
        alert("You have no active classrooms. Go to your Dashboard to create one.");
        return;
    }
    setShowAssignModal(true);
  };

  const confirmAssignment = () => {
      if (!selectedClassId) return;
      setAssigningStatus('assigning');

      const assignment: Assignment = {
          id: crypto.randomUUID(),
          classroomId: selectedClassId,
          subject: currentPlan.subject,
          topic: currentPlan.topic,
          questions: currentPlan.structuredQuestions || [],
          createdAt: new Date().toISOString()
      };

      saveAssignment(assignment);

      setTimeout(() => {
          setAssigningStatus('assigned');
          setTimeout(() => {
              setShowAssignModal(false);
              setAssigningStatus('idle');
              setSelectedClassId('');
          }, 1500);
      }, 1000);
  };

  return (
    <div className="space-y-6">
      {/* Top Action Bar */}
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200 flex flex-wrap gap-4 justify-between items-center no-print sticky top-0 z-20">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors">
            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
        </button>

        <div className="flex flex-wrap gap-3">
             <button 
                onClick={handleSave}
                disabled={isGuest}
                className={`flex items-center gap-2 px-4 py-2 rounded-md transition-colors shadow-sm ${saveStatus === 'saved' ? 'bg-green-100 text-green-800' : isGuest ? 'bg-gray-100 text-gray-400 cursor-not-allowed' : 'bg-white border border-gray-300 text-gray-700 hover:bg-gray-50'}`}
            >
                {isGuest ? <Lock className="w-4 h-4" /> : <Save className="w-4 h-4" />}
                {isGuest ? 'Sign in to Save' : saveStatus === 'saving' ? 'Saving...' : saveStatus === 'saved' ? 'Saved' : 'Save Plan'}
            </button>
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
                Print / PDF
            </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-gray-200 no-print mb-6 overflow-x-auto">
        <button
            onClick={() => setActiveTab('plan')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'plan' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <Layout className="w-4 h-4" /> Lesson Plan
        </button>
        <button
            onClick={() => setActiveTab('notes')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'notes' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <FileText className="w-4 h-4" /> Learner Notes
        </button>
        <button
            onClick={() => setActiveTab('questions')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'questions' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <HelpCircle className="w-4 h-4" /> Practice Questions
        </button>
      </div>

      {/* Content Area */}
      <div id="lesson-plan-content" ref={componentRef} className="bg-white p-8 md:p-12 shadow-lg border border-gray-200 mx-auto max-w-4xl print:shadow-none print:border-none print:w-full print:max-w-none print:p-0 print:m-0 font-sans">

        {/* Lesson Plan Text Content - Strict Layout */}
        {(activeTab === 'plan' || typeof window !== 'undefined' && window.matchMedia('print').matches) && (
            <div className={`${activeTab !== 'plan' ? 'hidden print:block' : ''}`}>
                {/* Strict Table Layout for Header */}
                <div className="border border-black mb-6 text-sm">
                    <div className="grid grid-cols-8 border-b border-black divide-x divide-black">
