export const saveAssignment = (assignment: Assignment): void => {
  const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  const assignments: Assignment[] = data ? JSON.parse(data) : [];
  assignments.push(assignment);
  localStorage.setItem(ASSIGNMENTS_STORAGE_KEY, JSON.stringify(assignments));
};

export const getAssignmentsByClassId = (classId: string): Assignment[] => {
  const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  const assignments: Assignment[] = data ? JSON.parse(data) : [];
  return assignments.filter(a => a.classroomId === classId);
};

// --- Student Login & Results ---

export const authenticateStudent = (code: string): { student: Student, classroom: Classroom } | null => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  // Find the classroom that contains a student with this code
  for (const cls of allClassrooms) {
    const student = cls.students.find(s => s.code === code);
    if (student) {
      return { student, classroom: cls };
    }
  }
  return null;
};

export const updateStudentName = (classId: string, studentCode: string, name: string): Student | null => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex === -1) return null;

    const studentIndex = allClassrooms[clsIndex].students.findIndex(s => s.code === studentCode);
    if (studentIndex === -1) return null;

    // Update name
    allClassrooms[clsIndex].students[studentIndex].name = name;
    localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));

    return allClassrooms[clsIndex].students[studentIndex];
};

export const saveStudentResult = (result: StudentResult): void => {
  const data = localStorage.getItem(RESULTS_STORAGE_KEY);
  const results: StudentResult[] = data ? JSON.parse(data) : [];

  // Check if result already exists for this assignment and student to update it or prevent duplicates?
  // For now, we allow multiple attempts, or overwrite. Let's append for history.
  results.push(result);
  localStorage.setItem(RESULTS_STORAGE_KEY, JSON.stringify(results));
};

export const getStudentResults = (studentCode: string): StudentResult[] => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    return results.filter(r => r.studentCode === studentCode).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
};

// --- User Authentication & Management ---

const getUsers = (): UserProfile[] => {
  const data = localStorage.getItem(USERS_DB_KEY);
  return data ? JSON.parse(data) : [];
};

export const getAllUsers = (): UserProfile[] => {
  return getUsers();
};

export const registerUser = (user: UserProfile): UserProfile => {
  const users = getUsers();

  // Check if email already exists
  if (users.some(u => u.email.toLowerCase() === user.email.toLowerCase())) {
    throw new Error('An account with this email already exists.');
  }

  // Regular users are not admins
  user.isAdmin = false;

  users.push(user);
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

  // Auto login after registration
  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const loginUser = (email: string, password: string): UserProfile => {
  // Hardcoded Admin Check
  if (email === 'admin@mwalimuplanner.com' && password === 'admin123') {
    const adminUser: UserProfile = {
      name: 'System Administrator',
      email: 'admin@mwalimuplanner.com',
      school: 'HQ',
      phone: '0000000000',
      isAdmin: true
    };
    localStorage.setItem(SESSION_KEY, JSON.stringify(adminUser));
    return adminUser;
  }

  const users = getUsers();
  const user = users.find(u => 
    u.email.toLowerCase() === email.toLowerCase() && 
    u.password === password
  );

  if (!user) {
    throw new Error('Invalid email or password.');
  }

  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const logoutUser = (): void => {
  localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = (): UserProfile | null => {
  const data = localStorage.getItem(SESSION_KEY);
  return data ? JSON.parse(data) : null;
};

export const updateUserProfile = (updatedProfile: UserProfile): void => {
  const users = getUsers();
  const index = users.findIndex(u => u.email === updatedProfile.email);

  if (index !== -1) {
    // Preserve password if not provided in update
    const existingUser = users[index];
    users[index] = { ...existingUser, ...updatedProfile };

    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
    localStorage.setItem(SESSION_KEY, JSON.stringify(users[index]));
  }
};

import React, { useState } from 'react';
import { Classroom, Assignment, StudentResult, Student } from '../types';
import { authenticateStudent, getAssignmentsByClassId, saveStudentResult, updateStudentName, getStudentResults } from '../services/storageService';
import { BookOpen, Check, ChevronRight, GraduationCap, LogIn, AlertCircle, Key, ArrowLeft, LayoutDashboard, Clock, CheckCircle2, XCircle, RotateCcw } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'enterName' | 'dashboard' | 'quiz' | 'result' | 'revision'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [studentNameInput, setStudentNameInput] = useState('');

  // Session State
  const [currentStudent, setCurrentStudent] = useState<Student | null>(null);
  const [currentClassroom, setCurrentClassroom] = useState<Classroom | null>(null);
  const [classAssignments, setClassAssignments] = useState<Assignment[]>([]);
  const [completedResults, setCompletedResults] = useState<StudentResult[]>([]);

  // Dashboard Tabs
  const [dashboardTab, setDashboardTab] = useState<'upcoming' | 'completed'>('upcoming');

  // Active Quiz/Revision State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizResult, setQuizResult] = useState<StudentResult | null>(null);

  const [error, setError] = useState('');

  // --- Auth Flow ---

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!accessCode) {
        setError("Please enter your Access Code.");
        return;
    }

    const authResult = authenticateStudent(accessCode.toUpperCase());
    if (authResult) {
        setCurrentStudent(authResult.student);
        setCurrentClassroom(authResult.classroom);

        if (!authResult.student.name) {
            setView('enterName');
        } else {
            loadStudentData(authResult.student, authResult.classroom);
            setView('dashboard');
        }
        setAccessCode('');
    } else {
        setError("Invalid Access Code. Please check and try again.");
    }
  };

  const handleNameSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!studentNameInput.trim() || !currentClassroom || !currentStudent) return;

      const updatedStudent = updateStudentName(currentClassroom.id, currentStudent.code, studentNameInput.trim());
      if (updatedStudent) {
          setCurrentStudent(updatedStudent);
          loadStudentData(updatedStudent, currentClassroom);
          setView('dashboard');
      }
  };

  const loadStudentData = (student: Student, classroom: Classroom) => {
      const allTasks = getAssignmentsByClassId(classroom.id);
      const results = getStudentResults(student.code);

      setClassAssignments(allTasks);
      setCompletedResults(results);
  };

  const handleLogout = () => {
      setCurrentStudent(null);
      setCurrentClassroom(null);
      setView('login');
      setStudentNameInput('');
      setSelectedAnswers({});
  };

  // --- Logic Helpers ---

  const getAssignmentById = (id: string) => classAssignments.find(a => a.id === id);

  // Filter assignments based on whether a result exists for them
  const upcomingAssignments = classAssignments.filter(a => 
      !completedResults.some(r => r.assignmentId === a.id)
  );

  // --- Quiz Logic ---

  const startAssignment = (assignment: Assignment) => {
      setActiveAssignment(assignment);
      setCurrentQuestionIndex(0);
      setSelectedAnswers({});
      setQuizResult(null);
      setView('quiz');
  };

  const handleAnswerSelect = (option: string) => {
      setSelectedAnswers(prev => ({
          ...prev,
          [currentQuestionIndex]: option
      }));
  };

  const nextQuestion = () => {
      if (activeAssignment && currentQuestionIndex < activeAssignment.questions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const submitQuiz = () => {
      if (!activeAssignment || !currentStudent) return;

      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          if (selectedAnswers[idx] === q.correctAnswer) {
              score++;
          }
      });

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: currentStudent.code,
          studentName: currentStudent.name || `Index ${currentStudent.index}`,
          score: score,
          total: activeAssignment.questions.length,
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);
      // Refresh results
      setCompletedResults(getStudentResults(currentStudent.code));
      setQuizResult(result);
      setView('result');
  };

  // --- Revision Logic ---

  const viewRevision = (result: StudentResult) => {
      const assignment = getAssignmentById(result.assignmentId);
      if (assignment) {
          setActiveAssignment(assignment);
          setQuizResult(result);
          setView('revision');
      }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">

      {/* 1. LOGIN VIEW */}
      {view === 'login' && (
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
            <div className="text-center mb-8">
                <div className="w-16 h-16 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center mx-auto mb-4">
                    <GraduationCap className="w-8 h-8" />
                </div>
                <h2 className="text-2xl font-bold text-gray-800">Student Login</h2>
                <p className="text-gray-500">Enter the access code provided by your teacher</p>
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 flex items-center gap-2">
                    <AlertCircle className="w-4 h-4" /> {error}
                </div>
            )}

            <form onSubmit={handleLogin} className="space-y-6">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                    <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <Key className="h-5 w-5 text-gray-400" />
                        </div>
                        <input 
                            type="text" 
                            value={accessCode}
                            onChange={(e) => setAccessCode(e.target.value.toUpperCase())}
                            className="w-full pl-10 px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-transparent font-mono uppercase tracking-widest text-center text-lg"
                            placeholder="XXXXXX"
                            maxLength={6}
                        />
                    </div>
                </div>
                <button type="submit" className="w-full bg-teal-600 text-white py-3 rounded-lg font-bold hover:bg-teal-700 transition-colors shadow-md flex justify-center items-center gap-2">
                    Enter Dashboard <LogIn className="w-4 h-4" />
                </button>
            </form>
        </div>
      )}

      {/* 2. ENTER NAME VIEW (First Time Login) */}
      {view === 'enterName' && (
          <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200 animate-fade-in">
              <div className="text-center mb-6">
                  <h2 className="text-2xl font-bold text-gray-800">Welcome!</h2>
                  <p className="text-gray-500">Please enter your full name to continue.</p>
              </div>
              <form onSubmit={handleNameSubmit} className="space-y-6">
                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                      <input 
                          type="text" 
                          required
                          value={studentNameInput}
                          onChange={(e) => setStudentNameInput(e.target.value)}
                          className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                          placeholder="e.g. John Kamau"
                      />
                  </div>
                  <button type="submit" className="w-full bg-slate-800 text-white py-3 rounded-lg font-bold hover:bg-slate-700 transition-colors">
                      Continue to Dashboard
                  </button>
              </form>
          </div>
      )}

      {/* HEADER (Visible when logged in) */}
      {currentStudent && currentClassroom && view !== 'login' && view !== 'enterName' && (
          <div className="w-full max-w-3xl fixed top-0 left-0 right-0 mx-auto p-4 z-10">
              <div className="bg-slate-800 rounded-xl shadow-lg p-4 text-white flex justify-between items-center">
                  <div>
                      <h2 className="font-bold text-lg">{currentClassroom.grade} - {currentClassroom.stream}</h2>
                      <p className="text-slate-400 text-xs">
                          {currentStudent.name} <span className="text-slate-600 mx-1">|</span> #{currentStudent.index}
                      </p>
                  </div>
                  <button onClick={handleLogout} className="text-xs bg-slate-700 hover:bg-slate-600 px-3 py-1.5 rounded-full transition-colors">
                      Sign Out
                  </button>
              </div>
          </div>
      )}

      {/* 3. DASHBOARD VIEW */}
      {view === 'dashboard' && (
          <div className="max-w-3xl w-full mt-24 animate-fade-in">

              {/* Dashboard Tabs */}
              <div className="flex p-1 bg-white rounded-xl shadow-sm border border-gray-200 mb-6">
                  <button 
                      onClick={() => setDashboardTab('upcoming')}
                      className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all ${dashboardTab === 'upcoming' ? 'bg-teal-50 text-teal-700 shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
                  >
                      Upcoming Assignments ({upcomingAssignments.length})
                  </button>
                  <button 
                      onClick={() => setDashboardTab('completed')}
                      className={`flex-1 py-2.5 text-sm font-bold rounded-lg transition-all ${dashboardTab === 'completed' ? 'bg-teal-50 text-teal-700 shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
                  >
                      Completed Tasks ({completedResults.length})
                  </button>
              </div>

              {/* Upcoming List */}
              {dashboardTab === 'upcoming' && (
                  <div className="space-y-4">
                      {upcomingAssignments.length === 0 ? (
                          <div className="text-center py-12 text-gray-500 bg-white rounded-xl border border-dashed border-gray-300">
                              <CheckCircle2 className="w-12 h-12 mx-auto mb-3 text-green-200" />
                              <p>You're all caught up! No new assignments.</p>
                          </div>
                      ) : (
                          upcomingAssignments.map(a => (
                              <div key={a.id} onClick={() => startAssignment(a)} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200 hover:border-teal-500 cursor-pointer transition-all group">
                                  <div className="flex justify-between items-start">
                                      <div>
                                          <span className="inline-block px-2 py-1 bg-slate-100 text-slate-600 text-[10px] font-bold uppercase rounded mb-2">{a.subject}</span>
                                          <h4 className="font-bold text-gray-800 group-hover:text-teal-600 text-lg">{a.topic}</h4>
                                          <p className="text-sm text-gray-500 mt-1 flex items-center gap-2">
                                              <Clock className="w-3 h-3" /> {a.questions.length} Questions
                                          </p>
                                      </div>
                                      <div className="bg-teal-50 text-teal-700 px-4 py-2 rounded-lg text-sm font-bold group-hover:bg-teal-600 group-hover:text-white transition-colors">
                                          Start
                                      </div>
                                  </div>
                              </div>
                          ))
                      )}
                  </div>
              )}

              {/* Completed List */}
              {dashboardTab === 'completed' && (
                  <div className="space-y-4">
                      {completedResults.length === 0 ? (
                          <div className="text-center py-12 text-gray-500 bg-white rounded-xl border border-dashed border-gray-300">
                              <p>No completed assignments yet.</p>
                          </div>
                      ) : (
                          completedResults.map(r => {
                              const assignment = getAssignmentById(r.assignmentId);
                              const percentage = Math.round((r.score / r.total) * 100);
                              return (
                                  <div key={r.id} onClick={() => viewRevision(r)} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200 hover:border-teal-500 cursor-pointer transition-all group">
                                      <div className="flex justify-between items-center">
                                          <div>
                                              <span className="inline-block px-2 py-1 bg-slate-100 text-slate-600 text-[10px] font-bold uppercase rounded mb-2">{assignment?.subject || 'Unknown Subject'}</span>
                                              <h4 className="font-bold text-gray-800 text-lg">{assignment?.topic || 'Unknown Topic'}</h4>
                                              <p className="text-xs text-gray-400 mt-1">Completed: {new Date(r.dateTaken).toLocaleDateString()}</p>
                                          </div>
                                          <div className="text-right">
                                              <div className={`text-2xl font-black ${percentage >= 50 ? 'text-green-600' : 'text-orange-500'}`}>
                                                  {percentage}%
                                              </div>
                                              <p className="text-xs text-gray-500">{r.score}/{r.total} Correct</p>
                                              <div className="text-[10px] text-teal-600 font-bold mt-1 group-hover:underline">Review Answers</div>
                                          </div>
                                      </div>
                                  </div>
                              );
                          })
                      )}
                  </div>
              )}
          </div>
      )}

      {/* 4. QUIZ VIEW */}
      {view === 'quiz' && activeAssignment && (
          <div className="max-w-xl w-full bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden mt-20 animate-fade-in-up">
              <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex justify-between items-center">
                  <span className="text-sm font-bold text-gray-500 uppercase tracking-wider">Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}</span>
                  <span className="text-xs bg-teal-100 text-teal-800 px-2 py-1 rounded-full font-bold">{activeAssignment.subject}</span>
              </div>

              <div className="p-8">
                  <h3 className="text-xl font-medium text-gray-800 mb-6 leading-relaxed">
                      {activeAssignment.questions[currentQuestionIndex].question}
                  </h3>

                  <div className="space-y-3">
                      {activeAssignment.questions[currentQuestionIndex].options.map((option, idx) => (
                          <button
                              key={idx}
                              onClick={() => handleAnswerSelect(option)}
                              className={`w-full text-left p-4 rounded-lg border-2 transition-all ${
                                  selectedAnswers[currentQuestionIndex] === option 
                                  ? 'border-teal-500 bg-teal-50 text-teal-900 font-medium' 
                                  : 'border-gray-200 hover:border-gray-300 text-gray-700'
                              }`}
                          >
                              {option}
                          </button>
                      ))}
                  </div>
              </div>

              <div className="p-6 bg-gray-50 border-t border-gray-200 flex justify-between">
                  <button 
                    onClick={() => setView('dashboard')}
                    className="text-gray-500 hover:text-gray-700 text-sm font-medium"
                  >
                      Cancel
                  </button>

                  {currentQuestionIndex < activeAssignment.questions.length - 1 ? (
                      <button 
                          onClick={nextQuestion}
                          disabled={!selectedAnswers[currentQuestionIndex]}
                          className="bg-slate-800 text-white px-6 py-2 rounded-lg font-medium hover:bg-slate-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      >
                          Next
                      </button>
                  ) : (
                      <button 
                          onClick={submitQuiz}
                          disabled={!selectedAnswers[currentQuestionIndex]}
                          className="bg-teal-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      >
                          Submit Quiz
                      </button>
                  )}
              </div>
          </div>
      )}

      {/* 5. RESULT SUMMARY VIEW */}
      {view === 'result' && quizResult && (
          <div className="max-w-md w-full bg-white rounded-xl shadow-xl border border-gray-200 text-center p-10 animate-fade-in-up mt-20">
              <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                  <Check className="w-10 h-10 text-green-600" />
              </div>
              <h2 className="text-2xl font-bold text-gray-800 mb-2">Quiz Completed!</h2>
              <p className="text-gray-500 mb-8">Your results have been recorded successfully.</p>

              <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 mb-8">
                  <p className="text-sm text-gray-500 uppercase tracking-widest font-bold mb-1">Your Score</p>
                  <p className="text-4xl font-black text-slate-800">
                      {quizResult.score} <span className="text-xl text-gray-400 font-normal">/ {quizResult.total}</span>
                  </p>
              </div>

              <div className="flex gap-3">
                  <button 
                      onClick={() => setView('dashboard')}
                      className="flex-1 bg-white border border-gray-300 text-gray-700 py-3 rounded-lg font-bold hover:bg-gray-50 transition-colors"
                  >
                      Dashboard
                  </button>
                  <button 
                      onClick={() => setView('revision')}
                      className="flex-1 bg-slate-800 text-white py-3 rounded-lg font-bold hover:bg-slate-700 transition-colors"
                  >
                      Review Answers
                  </button>
              </div>
          </div>
      )}

      {/* 6. REVISION VIEW */}
      {view === 'revision' && activeAssignment && quizResult && (
          <div className="max-w-3xl w-full mt-24 animate-fade-in pb-12">
              <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 mb-6 flex justify-between items-center sticky top-24 z-20">
                  <div>
                      <h2 className="text-xl font-bold text-gray-800">Revision Mode</h2>
                      <p className="text-sm text-gray-500">{activeAssignment.topic}</p>
                  </div>
                  <button 
                      onClick={() => setView('dashboard')}
                      className="text-sm bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2 rounded-lg font-medium transition-colors flex items-center gap-2"
                  >
                      <LayoutDashboard className="w-4 h-4" /> Exit
                  </button>
              </div>

              <div className="space-y-6">
                  {activeAssignment.questions.map((q, idx) => {
                      const selected = quizResult.answers[idx];
                      const isCorrect = selected === q.correctAnswer;

                      return (
                          <div key={q.id} className={`bg-white p-6 rounded-xl border-2 ${isCorrect ? 'border-green-100' : 'border-red-100'} shadow-sm`}>
                              <div className="flex gap-4">
                                  <div className="shrink-0 mt-1">
                                      {isCorrect ? (
                                          <div className="w-8 h-8 bg-green-100 text-green-600 rounded-full flex items-center justify-center">
                                              <Check className="w-5 h-5" />
                                          </div>
                                      ) : (
                                          <div className="w-8 h-8 bg-red-100 text-red-600 rounded-full flex items-center justify-center">
                                              <XCircle className="w-5 h-5" />
                                          </div>
                                      )}
                                  </div>
                                  <div className="flex-1">
                                      <h3 className="text-lg font-medium text-gray-900 mb-4">
                                          <span className="text-gray-400 mr-2">{idx + 1}.</span>
                                          {q.question}
                                      </h3>

                                      <div className="space-y-2 mb-4">
                                          <div className={`p-3 rounded-lg text-sm border flex justify-between items-center ${isCorrect ? 'bg-green-50 border-green-200 text-green-900' : 'bg-red-50 border-red-200 text-red-900'}`}>
                                              <span><span className="font-bold mr-2">You Answered:</span> {selected || "No Answer"}</span>
                                          </div>

                                          {!isCorrect && (
                                              <div className="p-3 rounded-lg text-sm bg-green-50 border border-green-200 text-green-900">
                                                  <span className="font-bold mr-2">Correct Answer:</span> {q.correctAnswer}
                                              </div>
                                          )}
                                      </div>

                                      {q.explanation && (
                                          <div className="bg-slate-50 p-4 rounded-lg text-sm text-slate-600 mt-4">
                                              <span className="font-bold block mb-1 text-slate-800">Explanation:</span>
                                              {q.explanation}
                                          </div>
                                      )}
                                  </div>
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      )}

    </div>
  );
};

export default StudentPortal;

