  const handleSignUp = (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.email || !formData.name || !formData.school || !formData.phone || !formData.password) {
          setError("Please fill in all fields.");
          return;
      }

      try {
          // Direct registration for sign up (no verification required per request)
          const user = registerUser(formData);
          onLogin(user);
      } catch (err: any) {
          setError(err.message);
      }
  };

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
        if (formData.email && formData.password) {
            const user = loginUser(formData.email, formData.password);
            onLogin(user);
        } else {
            setError("Please enter both email and password.");
        }
    } catch (err: any) {
        setError(err.message || "Authentication failed.");
    }
  };

  const handleForgotPassword = (e: React.FormEvent) => {
      e.preventDefault();
      if (!formData.email) {
          setError("Please enter your email address.");
          return;
      }

      // Simulate sending verification code for password reset
      const code = Math.floor(100000 + Math.random() * 900000).toString();
      setGeneratedCode(code);
      setEmailToRecover(formData.email);

      // In a real app, this would be an API call.
      alert(`Simulation: Your password reset verification code is ${code}`); 

      setSuccess(`Verification code sent to ${formData.email}`);
      setError(null);
      setView('verify');
  };

  const handleVerifyCode = (e: React.FormEvent) => {
      e.preventDefault();
      if (verificationCode === generatedCode) {
          setSuccess("Code verified. Please set your new password.");
          setError(null);
          setView('reset');
      } else {
          setError("Invalid verification code. Please try again.");
      }
  };

  const handleResetPassword = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newPassword || newPassword.length < 6) {
          setError("Password must be at least 6 characters.");
          return;
      }

      const success = resetUserPassword(emailToRecover, newPassword);
      if (success) {
          setSuccess("Password reset successfully. Please login.");
          setError(null);
          setFormData({ ...formData, password: '' }); // Clear password field
          setView('signin');
      } else {
          setError("Account not found. Please sign up.");
          setView('signup');
      }
  };

  return (
    <div className="min-h-[80vh] flex flex-col justify-center items-center p-4 bg-gray-50">
