                      <button onClick={() => setManagedClassroom(null)} className="hover:bg-slate-700 p-2 rounded transition-colors"><X className="w-5 h-5" /></button>
                  </div>

                  {/* Tabs */}
                  <div className="flex border-b border-gray-200 bg-gray-50">
                      <button 
                          onClick={() => setManageTab('students')}
                          className={`flex-1 py-3 text-sm font-bold border-b-2 transition-colors ${manageTab === 'students' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Student Codes
                      </button>
                      <button 
                          onClick={() => { setManageTab('performance'); setManageView('subjects'); }}
                          className={`flex-1 py-3 text-sm font-bold border-b-2 transition-colors ${manageTab === 'performance' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Subject Performance
                      </button>
                  </div>

                  {/* Content Area */}
                  <div className="flex-1 overflow-y-auto p-0 bg-white relative">

                      {/* TAB 1: STUDENT CODES */}
                      {manageTab === 'students' && (
                          <div className="p-0">
                              <div className="print-header hidden p-4">
                                  <h1 className="text-xl font-bold">Student Access Codes</h1>
                                  <p>Class: {managedClassroom.grade} - {managedClassroom.stream}</p>
                                  <hr className="my-2"/>
                              </div>
                              <div className="p-4 flex justify-end">
                                  <button onClick={handlePrintCodes} className="bg-slate-100 text-slate-700 px-3 py-1.5 rounded text-sm font-bold hover:bg-slate-200 flex items-center gap-2">
                                      <BookOpen className="w-4 h-4" /> Print Codes
                                  </button>
                              </div>
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs sticky top-0">
                                      <tr>
                                          <th className="px-6 py-3 border-b">Index</th>
                                          <th className="px-6 py-3 border-b">Code</th>
                                          <th className="px-6 py-3 border-b">Name</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {managedClassroom.students.map((student) => (
                                          <tr key={student.code} className="hover:bg-gray-50">
                                              <td className="px-6 py-3 font-medium text-gray-900">#{student.index}</td>
                                              <td className="px-6 py-3 font-mono text-teal-700 font-bold tracking-wider">{student.code}</td>
                                              <td className="px-6 py-3 text-gray-400 italic">{student.name || "______________________"}</td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      )}

                      {/* TAB 2: PERFORMANCE */}
                      {manageTab === 'performance' && (
                          <div className="p-6 h-full">

                              {/* VIEW: SUBJECT LIST */}
                              {manageView === 'subjects' && (
                                  <div className="animate-fade-in">
                                      <h3 className="text-lg font-bold text-gray-800 mb-4">Select a Subject</h3>
                                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                                          {managedClassroom.subjects.length === 0 ? (
                                              <div className="col-span-full text-center py-10 text-gray-400 italic bg-gray-50 rounded-lg border border-dashed">
                                                  No subjects added to this class yet.
                                              </div>
                                          ) : (
                                              managedClassroom.subjects.map(subject => (
                                                  <button 
                                                      key={subject}
                                                      onClick={() => loadAssignmentsForSubject(subject)}
                                                      className="p-4 bg-white border border-gray-200 rounded-xl hover:border-teal-500 hover:shadow-md transition-all text-left group"
                                                  >
                                                      <h4 className="font-bold text-slate-700 group-hover:text-teal-700">{subject}</h4>
                                                      <div className="flex items-center text-xs text-gray-400 mt-2">
                                                          View Assignments <ChevronRight className="w-3 h-3 ml-1" />
                                                      </div>
                                                  </button>
                                              ))
                                          )}
                                      </div>
                                  </div>
                              )}

                              {/* VIEW: ASSIGNMENT LIST */}
                              {manageView === 'assignments' && (
                                  <div className="animate-fade-in h-full flex flex-col">
                                      <button onClick={() => setManageView('subjects')} className="flex items-center text-sm text-gray-500 hover:text-gray-800 mb-4 w-fit">
                                          <ArrowLeft className="w-4 h-4 mr-1" /> Back to Subjects
                                      </button>
                                      <h3 className="text-lg font-bold text-gray-800 mb-4">{selectedSubjectForStats} Assignments</h3>

                                      <div className="overflow-y-auto flex-1">
                                          {assignmentList.length === 0 ? (
                                              <div className="text-center py-10 text-gray-400 italic bg-gray-50 rounded-lg border border-dashed">
                                                  No assignments found for this subject.
                                              </div>
                                          ) : (
                                              <div className="space-y-3">
                                                  {assignmentList.map(assign => (
                                                      <div key={assign.id} onClick={() => loadResultsForAssignment(assign)} className="p-4 bg-white border border-gray-200 rounded-xl hover:border-teal-500 cursor-pointer transition-all flex justify-between items-center group">
                                                          <div>
                                                              <h4 className="font-bold text-slate-700">{assign.topic}</h4>
                                                              <p className="text-xs text-gray-500">{new Date(assign.createdAt).toLocaleDateString()} • {assign.questions.length} Questions</p>
                                                          </div>
                                                          <ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" />
                                                      </div>
                                                  ))}
                                              </div>
                                          )}
                                      </div>
                                  </div>
                              )}

                              {/* VIEW: RESULT LIST */}
                              {manageView === 'results' && selectedAssignmentForStats && (
                                  <div className="animate-fade-in h-full flex flex-col">
                                      <button onClick={() => setManageView('assignments')} className="flex items-center text-sm text-gray-500 hover:text-gray-800 mb-4 w-fit">
                                          <ArrowLeft className="w-4 h-4 mr-1" /> Back to Assignments
                                      </button>
                                      <div className="flex justify-between items-center mb-4">
                                          <div>
                                              <h3 className="text-lg font-bold text-gray-800">{selectedAssignmentForStats.topic}</h3>
                                              <p className="text-xs text-gray-500">Student Results</p>
                                          </div>
                                      </div>

                                      <div className="overflow-hidden border border-gray-200 rounded-lg">
                                          <table className="w-full text-sm text-left">
                                              <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs">
                                                  <tr>
                                                      <th className="px-6 py-3">Student Name</th>
                                                      <th className="px-6 py-3">Score</th>
                                                      <th className="px-6 py-3 text-right">Feedback</th>
                                                  </tr>
                                              </thead>
                                              <tbody className="divide-y divide-gray-100">
                                                  {currentAssignmentResults.map((result) => (
                                                      <tr key={result.id} className="hover:bg-gray-50">
                                                          <td className="px-6 py-3 font-medium text-gray-900">
                                                              {result.studentName}
                                                              <div className="text-[10px] text-gray-400">{new Date(result.dateTaken).toLocaleDateString()}</div>
                                                          </td>
                                                          <td className="px-6 py-3">
                                                              <span className={`px-2 py-1 rounded text-xs font-bold ${result.score/result.total >= 0.5 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                                  {result.score}/{result.total}
                                                              </span>
                                                          </td>
                                                          <td className="px-6 py-3 text-right">
                                                              <button 
                                                                  onClick={() => openFeedbackModal(result)}
                                                                  className={`inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded transition-colors ${result.feedback ? 'bg-blue-50 text-blue-600 hover:bg-blue-100' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                                              >
                                                                  <MessageSquare className="w-3 h-3" />
                                                                  {result.feedback ? 'Edit Feedback' : 'Give Feedback'}
                                                              </button>
                                                          </td>
                                                      </tr>
                                                  ))}
                                                  {currentAssignmentResults.length === 0 && (
                                                      <tr><td colSpan={3} className="px-6 py-8 text-center text-gray-400">No students have completed this assignment yet.</td></tr>
                                                  )}
                                              </tbody>
                                          </table>
                                      </div>
                                  </div>
                              )}
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* Feedback Modal */}
      {feedbackModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                      <h3 className="font-bold">Feedback for {feedbackModal.name}</h3>
                      <button onClick={() => setFeedbackModal(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="p-6">
                      <label className="block text-sm font-medium text-gray-700 mb-2">Teacher's Comment</label>
                      <textarea 
                          rows={4}
                          className="w-full rounded-lg border border-gray-300 p-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                          placeholder="Write your feedback here..."
                          value={feedbackInput}
                          onChange={(e) => setFeedbackInput(e.target.value)}
                      ></textarea>
                  </div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2">
                      <button onClick={() => setFeedbackModal(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium text-sm">Cancel</button>
                      <button onClick={saveFeedback} className="px-4 py-2 bg-teal-600 text-white rounded font-bold text-sm hover:bg-teal-700">Save Feedback</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Classroom, Assignment, StudentResult, Student } from '../types';
import { authenticateStudent, getAssignmentsByClassId, saveStudentResult, updateStudentName, getStudentResults } from '../services/storageService';
import { BookOpen, Check, ChevronRight, GraduationCap, LogIn, AlertCircle, Key, ArrowLeft, LayoutDashboard, Clock, CheckCircle2, XCircle, RotateCcw, Menu, Bell, ChevronDown, FileText, List, User, LogOut, MessageSquare } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'enterName' | 'dashboard' | 'assignments' | 'results' | 'quiz' | 'revision'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [studentNameInput, setStudentNameInput] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Session State
  const [currentStudent, setCurrentStudent] = useState<Student | null>(null);
  const [currentClassroom, setCurrentClassroom] = useState<Classroom | null>(null);
  const [classAssignments, setClassAssignments] = useState<Assignment[]>([]);
  const [completedResults, setCompletedResults] = useState<StudentResult[]>([]);

  // Active Quiz/Revision State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizResult, setQuizResult] = useState<StudentResult | null>(null);

  const [error, setError] = useState('');

  // --- Auth Flow ---

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!accessCode) {
        setError("Please enter your Access Code.");
        return;
    }

    const authResult = authenticateStudent(accessCode.toUpperCase());
    if (authResult) {
        setCurrentStudent(authResult.student);
        setCurrentClassroom(authResult.classroom);

        if (!authResult.student.name) {
            setView('enterName');
        } else {
            loadStudentData(authResult.student, authResult.classroom);
            setView('dashboard');
        }
        setAccessCode('');
    } else {
        setError("Invalid Access Code. Please check and try again.");
    }
  };

  const handleNameSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!studentNameInput.trim() || !currentClassroom || !currentStudent) return;

      const updatedStudent = updateStudentName(currentClassroom.id, currentStudent.code, studentNameInput.trim());
      if (updatedStudent) {
          setCurrentStudent(updatedStudent);
          loadStudentData(updatedStudent, currentClassroom);
          setView('dashboard');
      }
  };

  const loadStudentData = (student: Student, classroom: Classroom) => {
      const allTasks = getAssignmentsByClassId(classroom.id);
      const results = getStudentResults(student.code);
      setClassAssignments(allTasks);
      setCompletedResults(results);
  };

  const handleLogout = () => {
      setCurrentStudent(null);
      setCurrentClassroom(null);
      setView('login');
      setStudentNameInput('');
      setSelectedAnswers({});
  };

  const upcomingAssignments = classAssignments.filter(a => 
      !completedResults.some(r => r.assignmentId === a.id)
  );

  const getAssignmentById = (id: string) => classAssignments.find(a => a.id === id);

  const startAssignment = (assignment: Assignment) => {
      setActiveAssignment(assignment);
      setCurrentQuestionIndex(0);
      setSelectedAnswers({});
      setQuizResult(null);
      setView('quiz');
  };

  const handleAnswerSelect = (option: string) => {
      setSelectedAnswers(prev => ({ ...prev, [currentQuestionIndex]: option }));
  };

  const nextQuestion = () => {
      if (activeAssignment && currentQuestionIndex < activeAssignment.questions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const submitQuiz = () => {
      if (!activeAssignment || !currentStudent) return;
      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          if (selectedAnswers[idx] === q.correctAnswer) score++;
      });
      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: currentStudent.code,
          studentName: currentStudent.name || `Index ${currentStudent.index}`,
          score: score,
          total: activeAssignment.questions.length,
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };
      saveStudentResult(result);
      setCompletedResults(getStudentResults(currentStudent.code));
      setQuizResult(result);
      setView('result'); // Shows summary
  };

  const viewRevision = (result: StudentResult) => {
      const assignment = getAssignmentById(result.assignmentId);
      if (assignment) {
          setActiveAssignment(assignment);
          setQuizResult(result);
          setView('revision');
      }
  };

  // Stats for Dashboard
  const avgScore = completedResults.length > 0 
    ? Math.round(completedResults.reduce((acc, curr) => acc + (curr.score/curr.total)*100, 0) / completedResults.length) 
    : 0;

  // Render Login Views
  if (view === 'login') {
      return (
        <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
            <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
                <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-slate-900 text-teal-400 rounded-full flex items-center justify-center mx-auto mb-4">
                        <GraduationCap className="w-8 h-8" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                    <p className="text-gray-500">Enter your access code</p>
                </div>
                {error && <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}
                <form onSubmit={handleLogin} className="space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none"><Key className="h-5 w-5 text-gray-400" /></div>
                            <input type="text" value={accessCode} onChange={(e) => setAccessCode(e.target.value.toUpperCase())} className="w-full pl-10 px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 text-center text-lg uppercase tracking-widest font-mono" placeholder="XXXXXX" maxLength={6} />
                        </div>
                    </div>
                    <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800 transition-colors shadow-md">Enter Dashboard</button>
                </form>
            </div>
        </div>
      );
  }

  if (view === 'enterName') {
      return (
          <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
              <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
                  <div className="text-center mb-6">
                      <h2 className="text-2xl font-bold text-gray-800">Welcome!</h2>
                      <p className="text-gray-500">Please enter your full name.</p>
                  </div>
                  <form onSubmit={handleNameSubmit} className="space-y-6">
                      <input type="text" required value={studentNameInput} onChange={(e) => setStudentNameInput(e.target.value)} className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500" placeholder="e.g. John Kamau" />
                      <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800">Continue</button>
                  </form>
              </div>
          </div>
      );
  }

  // LOGGED IN DASHBOARD LAYOUT
  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">

        {/* Sidebar */}
        <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-slate-300 transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 shadow-xl`}>
            <div className="flex items-center h-16 px-6 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800">
                <GraduationCap className="w-6 h-6 mr-2 text-teal-500" />
                Student<span className="text-teal-500">Portal</span>
            </div>
            <div className="p-4">
                <div className="bg-slate-800 rounded p-3 mb-6">
                    <p className="text-xs text-slate-400 uppercase tracking-wider">Class</p>
                    <p className="font-bold text-white">{currentClassroom?.grade} - {currentClassroom?.stream}</p>
                </div>
                <nav className="space-y-2">
                    <button onClick={() => setView('dashboard')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'dashboard' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <LayoutDashboard className="w-5 h-5 mr-3" /> Overview
                    </button>
                    <button onClick={() => setView('assignments')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'assignments' || view === 'quiz' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <FileText className="w-5 h-5 mr-3" /> Assignments
                        {upcomingAssignments.length > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{upcomingAssignments.length}</span>}
                    </button>
                    <button onClick={() => setView('results')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'results' || view === 'revision' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <List className="w-5 h-5 mr-3" /> Results
                    </button>
                </nav>
            </div>
            <div className="absolute bottom-0 w-full p-4 border-t border-slate-800">
                <button onClick={handleLogout} className="flex items-center w-full px-4 py-2 text-sm text-slate-400 hover:text-red-400 transition-colors">
                    <LogOut className="w-4 h-4 mr-3" /> Sign Out
                </button>
            </div>
        </aside>

        {/* Main Content */}
        <div className={`flex-1 flex flex-col transition-all duration-300 ${sidebarOpen ? 'lg:ml-64' : ''}`}>

            {/* Header */}
            <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 sticky top-0 z-40 shadow-sm">
                <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500"><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 ml-auto">
                    <div className="flex items-center gap-2 pl-4 border-l border-gray-200">
                        <div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center text-xs font-bold">{currentStudent?.name?.charAt(0)}</div>
                        <span className="text-sm font-medium text-gray-700 hidden md:block">{currentStudent?.name}</span>
                    </div>
                </div>
            </header>

            <main className="p-4 lg:p-8">
                {/* Yellow Alert */}
                <div className="bg-amber-100 border-l-4 border-amber-500 text-amber-800 p-4 mb-8 rounded-r shadow-sm flex items-start gap-3">
                    <span className="bg-amber-200 p-1 rounded text-amber-700 font-bold px-2">i</span>
                    <p className="text-sm">Welcome back! You have <strong>{upcomingAssignments.length} pending assignments</strong> to complete.</p>
                </div>

                {view === 'dashboard' && (
                    <div className="space-y-8 animate-fade-in">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Pending</h3><span className="text-4xl font-light text-orange-500">{upcomingAssignments.length}</span></div>
                                <div className="p-3 bg-orange-50 rounded-full"><Clock className="w-6 h-6 text-orange-500" /></div>
                            </div>
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Completed</h3><span className="text-4xl font-light text-teal-500">{completedResults.length}</span></div>
                                <div className="p-3 bg-teal-50 rounded-full"><CheckCircle2 className="w-6 h-6 text-teal-500" /></div>
                            </div>
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Avg Score</h3><span className="text-4xl font-light text-blue-500">{avgScore}%</span></div>
                                <div className="p-3 bg-blue-50 rounded-full"><RotateCcw className="w-6 h-6 text-blue-500" /></div>
                            </div>
                        </div>
                    </div>
                )}

                {(view === 'assignments' || view === 'dashboard') && upcomingAssignments.length > 0 && (
                    <div className="mt-8 animate-fade-in">
                        <h3 className="text-lg font-bold text-gray-700 mb-4">Pending Assignments</h3>
                        <div className="grid gap-4">
                            {upcomingAssignments.map(a => (
                                <div key={a.id} className="bg-white p-5 rounded-xl border border-gray-200 hover:border-teal-500 shadow-sm flex justify-between items-center transition-all group">
                                    <div>
                                        <span className="text-xs font-bold text-teal-600 bg-teal-50 px-2 py-1 rounded uppercase">{a.subject}</span>
                                        <h4 className="font-bold text-gray-800 mt-2">{a.topic}</h4>
                                        <p className="text-xs text-gray-500 mt-1">{a.questions.length} Questions</p>
                                    </div>
                                    <button onClick={() => startAssignment(a)} className="bg-slate-900 text-white px-4 py-2 rounded text-sm font-bold hover:bg-slate-800 transition-colors">Start</button>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {view === 'results' && (
                    <div className="animate-fade-in">
                        <h3 className="text-lg font-bold text-gray-700 mb-4">Revision History</h3>
                        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
