};

import { LessonPlanData, UserProfile, Classroom, Assignment, StudentResult, Student } from '../types';

const PLANS_STORAGE_KEY = 'mwalimu_saved_plans';
const USERS_DB_KEY = 'mwalimu_users_db';
const SESSION_KEY = 'mwalimu_current_session';
const CLASSROOMS_STORAGE_KEY = 'mwalimu_classrooms';
const ASSIGNMENTS_STORAGE_KEY = 'mwalimu_assignments';
const RESULTS_STORAGE_KEY = 'mwalimu_results';

// --- Plan Management ---

export const savePlan = (plan: LessonPlanData): void => {
  const currentUser = getCurrentUser();
  if (!currentUser) {
    throw new Error("You must be logged in to save a plan.");
  }

  // Fetch ALL plans first (to append to the global storage)
  const allPlans = getAllGlobalPlans();

  // Ensure ID and timestamp exist
  if (!plan.id) plan.id = crypto.randomUUID();
  if (!plan.createdAt) plan.createdAt = new Date().toISOString();
  // Assign ownership
  plan.userId = currentUser.email;

  const existingIndex = allPlans.findIndex(p => p.id === plan.id);

  if (existingIndex >= 0) {
    allPlans[existingIndex] = plan;
  } else {
    allPlans.unshift(plan);
  }

  localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(allPlans));
};

// Returns plans ONLY for the current user
export const getSavedPlans = (): LessonPlanData[] => {
  const currentUser = getCurrentUser();
  if (!currentUser) return [];

  const data = localStorage.getItem(PLANS_STORAGE_KEY);
  const allPlans: LessonPlanData[] = data ? JSON.parse(data) : [];

  // Filter plans where plan.userId matches current user's email
  return allPlans.filter(plan => plan.userId === currentUser.email);
};

// Returns ALL plans (For Admin Dashboard use only)
export const getAllGlobalPlans = (): LessonPlanData[] => {
  const data = localStorage.getItem(PLANS_STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

export const deletePlan = (id: string): void => {
  const allPlans = getAllGlobalPlans();
  const updatedPlans = allPlans.filter(p => p.id !== id);
  localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(updatedPlans));
};

// --- Classroom Management ---

const generateStudentCode = (): string => {
  // Generate a 6-character alphanumeric code (e.g., A7X92P)
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Helper to check if a code is globally unique across all classrooms
const isCodeUnique = (code: string, allClassrooms: Classroom[]): boolean => {
  for (const cls of allClassrooms) {
    if (cls.students.some(s => s.code === code)) return false;
  }
  return true;
};

export const createClassroom = (grade: string, stream: string, roll: number): Classroom => {
  const currentUser = getCurrentUser();
  if (!currentUser) throw new Error("Must be logged in.");

  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  const students: Student[] = [];
  for (let i = 1; i <= roll; i++) {
    let code = generateStudentCode();
    // Ensure uniqueness
    while (!isCodeUnique(code, allClassrooms)) {
      code = generateStudentCode();
    }
    students.push({
      index: i,
      code: code
    });
  }

  const newClassroom: Classroom = {
    id: crypto.randomUUID(),
    userId: currentUser.email,
    grade,
    stream,
    subjects: [], // Starts with no subjects
    students: students
  };

  allClassrooms.push(newClassroom);
  localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
  return newClassroom;
};

export const addSubjectToClassroom = (classId: string, subject: string): void => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  const clsIndex = allClassrooms.findIndex(c => c.id === classId);
  if (clsIndex !== -1) {
    if (!allClassrooms[clsIndex].subjects.includes(subject)) {
        allClassrooms[clsIndex].subjects.push(subject);
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
  }
};

export const removeSubjectFromClassroom = (classId: string, subject: string): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
      allClassrooms[clsIndex].subjects = allClassrooms[clsIndex].subjects.filter(s => s !== subject);
      localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
};

export const getClassrooms = (): Classroom[] => {
  const currentUser = getCurrentUser();
  if (!currentUser) return [];

  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  return allClassrooms.filter(c => c.userId === currentUser.email);
};

export const deleteClassroom = (id: string): void => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  const updatedClassrooms = allClassrooms.filter(c => c.id !== id);
  localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(updatedClassrooms));

  // Also delete assignments associated with this classroom
  const assignData = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  if (assignData) {
      const assignments: Assignment[] = JSON.parse(assignData);
      const updatedAssignments = assignments.filter(a => a.classroomId !== id);
      localStorage.setItem(ASSIGNMENTS_STORAGE_KEY, JSON.stringify(updatedAssignments));
  }
};

// --- Assignment Management ---

export const saveAssignment = (assignment: Assignment): void => {
  const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  const assignments: Assignment[] = data ? JSON.parse(data) : [];
  assignments.push(assignment);
  localStorage.setItem(ASSIGNMENTS_STORAGE_KEY, JSON.stringify(assignments));
};

export const getAssignmentsByClassId = (classId: string): Assignment[] => {
  const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  const assignments: Assignment[] = data ? JSON.parse(data) : [];
  return assignments.filter(a => a.classroomId === classId);
};

// --- Student Login & Results ---

export const authenticateStudent = (code: string): { student: Student, classroom: Classroom } | null => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  // Find the classroom that contains a student with this code
  for (const cls of allClassrooms) {
    const student = cls.students.find(s => s.code === code);
    if (student) {
      return { student, classroom: cls };
    }
  }
  return null;
};

export const updateStudentName = (classId: string, studentCode: string, name: string): Student | null => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex === -1) return null;

    const studentIndex = allClassrooms[clsIndex].students.findIndex(s => s.code === studentCode);
    if (studentIndex === -1) return null;

    // Update name
    allClassrooms[clsIndex].students[studentIndex].name = name;
    localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));

    return allClassrooms[clsIndex].students[studentIndex];
};

export const saveStudentResult = (result: StudentResult): void => {
  const data = localStorage.getItem(RESULTS_STORAGE_KEY);
  const results: StudentResult[] = data ? JSON.parse(data) : [];

  // Check if result already exists for this assignment and student
  const existingIndex = results.findIndex(r => r.assignmentId === result.assignmentId && r.studentCode === result.studentCode);

  if (existingIndex !== -1) {
      // Update existing result
      const existing = results[existingIndex];
      existing.attempts = (existing.attempts || 0) + 1;

      // Update score only if higher
      if (result.score > existing.score) {
          existing.score = result.score;
          existing.answers = result.answers; // Keep answers of best attempt
      }
      // Update date taken to latest
      existing.dateTaken = result.dateTaken;

      results[existingIndex] = existing;
  } else {
      // New result, set attempt to 1
      result.attempts = 1;
      results.push(result);
  }

  localStorage.setItem(RESULTS_STORAGE_KEY, JSON.stringify(results));
};

export const getStudentResults = (studentCode: string): StudentResult[] => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    return results.filter(r => r.studentCode === studentCode).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
};

export const getAssignmentResults = (assignmentId: string): StudentResult[] => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    return results.filter(r => r.assignmentId === assignmentId).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
};

export const updateStudentResultFeedback = (resultId: string, feedback: string): void => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    const index = results.findIndex(r => r.id === resultId);

    if (index !== -1) {
        results[index].feedback = feedback;
        localStorage.setItem(RESULTS_STORAGE_KEY, JSON.stringify(results));
    }
};

// --- User Authentication & Management ---

const getUsers = (): UserProfile[] => {
  const data = localStorage.getItem(USERS_DB_KEY);
  return data ? JSON.parse(data) : [];
};

export const getAllUsers = (): UserProfile[] => {
  return getUsers();
};

export const registerUser = (user: UserProfile): UserProfile => {
  const users = getUsers();

  // Check if email already exists
  if (users.some(u => u.email.toLowerCase() === user.email.toLowerCase())) {
    throw new Error('An account with this email already exists.');
  }

  // Regular users are not admins
  user.isAdmin = false;

  users.push(user);
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

  // Auto login after registration
  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const loginUser = (email: string, password: string): UserProfile => {
  // Hardcoded Admin Check
  if (email === 'admin@mwalimuplanner.com' && password === 'admin123') {
    const adminUser: UserProfile = {
      name: 'System Administrator',
      email: 'admin@mwalimuplanner.com',
      school: 'HQ',
      phone: '0000000000',
      isAdmin: true
    };
    localStorage.setItem(SESSION_KEY, JSON.stringify(adminUser));
    return adminUser;
  }

  const users = getUsers();
  const user = users.find(u => 
    u.email.toLowerCase() === email.toLowerCase() && 
    u.password === password
  );

  if (!user) {
    throw new Error('Invalid email or password.');
  }

  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const logoutUser = (): void => {
  localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = (): UserProfile | null => {
  const data = localStorage.getItem(SESSION_KEY);
  return data ? JSON.parse(data) : null;
};

export const updateUserProfile = (updatedProfile: UserProfile): void => {
  const users = getUsers();
  const index = users.findIndex(u => u.email === updatedProfile.email);

  if (index !== -1) {
    // Preserve password if not provided in update
    const existingUser = users[index];
    users[index] = { ...existingUser, ...updatedProfile };

    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
    localStorage.setItem(SESSION_KEY, JSON.stringify(users[index]));
  }
};

export const resetUserPassword = (email: string, newPass: string): boolean => {
    const users = getUsers();
    const index = users.findIndex(u => u.email.toLowerCase() === email.toLowerCase());

    if (index !== -1) {
        users[index].password = newPass;
        localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
        return true;
    }
    return false;
};

import React, { useState } from 'react';
import { Classroom, Assignment, StudentResult, Student, QuizQuestion } from '../types';
import { authenticateStudent, getAssignmentsByClassId, saveStudentResult, updateStudentName, getStudentResults } from '../services/storageService';
import { generateSimilarQuestions } from '../services/geminiService';
import { BookOpen, Check, ChevronRight, GraduationCap, LogIn, AlertCircle, Key, ArrowLeft, LayoutDashboard, Clock, CheckCircle2, XCircle, RotateCcw, Menu, Bell, ChevronDown, FileText, List, User, LogOut, MessageSquare, Loader2 } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'enterName' | 'dashboard' | 'assignments' | 'results' | 'quiz' | 'revision'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [studentNameInput, setStudentNameInput] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Session State
  const [currentStudent, setCurrentStudent] = useState<Student | null>(null);
  const [currentClassroom, setCurrentClassroom] = useState<Classroom | null>(null);
  const [classAssignments, setClassAssignments] = useState<Assignment[]>([]);
  const [completedResults, setCompletedResults] = useState<StudentResult[]>([]);

  // Active Quiz/Revision State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]); // To hold current set (original or regenerated)
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizResult, setQuizResult] = useState<StudentResult | null>(null);

  const [loadingQuiz, setLoadingQuiz] = useState(false);
  const [error, setError] = useState('');

  // --- Auth Flow ---

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!accessCode) {
        setError("Please enter your Access Code.");
        return;
    }

    const authResult = authenticateStudent(accessCode.toUpperCase());
    if (authResult) {
        setCurrentStudent(authResult.student);
        setCurrentClassroom(authResult.classroom);

        if (!authResult.student.name) {
            setView('enterName');
        } else {
            loadStudentData(authResult.student, authResult.classroom);
            setView('dashboard');
        }
        setAccessCode('');
    } else {
        setError("Invalid Access Code. Please check and try again.");
    }
  };

  const handleNameSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!studentNameInput.trim() || !currentClassroom || !currentStudent) return;

      const updatedStudent = updateStudentName(currentClassroom.id, currentStudent.code, studentNameInput.trim());
      if (updatedStudent) {
          setCurrentStudent(updatedStudent);
          loadStudentData(updatedStudent, currentClassroom);
          setView('dashboard');
      }
  };

  const loadStudentData = (student: Student, classroom: Classroom) => {
      const allTasks = getAssignmentsByClassId(classroom.id);
      const results = getStudentResults(student.code);
      setClassAssignments(allTasks);
      setCompletedResults(results);
  };

  const handleLogout = () => {
      setCurrentStudent(null);
      setCurrentClassroom(null);
      setView('login');
      setStudentNameInput('');
      setSelectedAnswers({});
  };

  const upcomingAssignments = classAssignments.filter(a => 
      !completedResults.some(r => r.assignmentId === a.id)
  );

  const getAssignmentById = (id: string) => classAssignments.find(a => a.id === id);

  const startAssignment = async (assignment: Assignment, isReattempt = false) => {
      setLoadingQuiz(true);
      setActiveAssignment(assignment);

      try {
          if (isReattempt && assignment.grade) {
              // Generate new similar questions
              const newQuestions = await generateSimilarQuestions(assignment.topic, assignment.subject, assignment.grade);
              setQuizQuestions(newQuestions);
          } else {
              // Use original questions
              setQuizQuestions(assignment.questions);
          }

          setCurrentQuestionIndex(0);
          setSelectedAnswers({});
          setQuizResult(null);
          setView('quiz');
      } catch (err) {
          alert("Could not load questions. Please try again.");
      } finally {
          setLoadingQuiz(false);
      }
  };

  const handleAnswerSelect = (option: string) => {
      setSelectedAnswers(prev => ({ ...prev, [currentQuestionIndex]: option }));
  };

  const nextQuestion = () => {
      if (activeAssignment && currentQuestionIndex < quizQuestions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const submitQuiz = () => {
      if (!activeAssignment || !currentStudent) return;

      let score = 0;
      quizQuestions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx]?.toLowerCase().trim() || "";
          const correct = q.correctAnswer.toLowerCase().trim();

          // Basic exact match check (improve with fuzzy logic if needed later)
          if (userAnswer === correct || (q.type === 'mcq' && userAnswer === correct)) {
              score++;
          }
      });

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: currentStudent.code,
          studentName: currentStudent.name || `Index ${currentStudent.index}`,
          score: score,
          total: quizQuestions.length,
          attempts: 1, // Will be incremented in storage if exists
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);

      // Update local state to reflect new attempt count/score
      setCompletedResults(getStudentResults(currentStudent.code));

      // Get the latest result object (with updated attempt count)
      const updatedResults = getStudentResults(currentStudent.code);
      const latestResult = updatedResults.find(r => r.assignmentId === activeAssignment.id) || result;

      setQuizResult(latestResult);
      setView('result'); // Shows summary
  };

  const viewRevision = (result: StudentResult) => {
      const assignment = getAssignmentById(result.assignmentId);
      if (assignment) {
          setActiveAssignment(assignment);
          // For revision, we can only reliably show original questions if we didn't store re-generated ones.
          // Assumption: result.answers keys align with assignment.questions indices.
          // NOTE: If questions were regenerated, we can't show exact revision unless we store questions in result.
          // For MVP, falling back to original questions or hiding detail if mismatch.
          setQuizQuestions(assignment.questions); 
          setQuizResult(result);
          setView('revision');
      }
  };

  // Stats for Dashboard
  const avgScore = completedResults.length > 0 
    ? Math.round(completedResults.reduce((acc, curr) => acc + (curr.score/curr.total)*100, 0) / completedResults.length) 
    : 0;

  // Render Login Views
  if (view === 'login') {
      return (
