        </aside>

        {/* Main Content */}
        <div className={`flex-1 flex flex-col transition-all duration-300 ${sidebarOpen ? 'lg:ml-64' : ''}`}>

            {/* Header */}
            <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 sticky top-0 z-40 shadow-sm">
                <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500"><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 ml-auto">
                    <div className="flex items-center gap-2 pl-4 border-l border-gray-200">
                        <div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center text-xs font-bold">{currentStudent?.name?.charAt(0)}</div>
                        <span className="text-sm font-medium text-gray-700 hidden md:block">{currentStudent?.name}</span>
                    </div>
                </div>
            </header>

            <main className="p-4 lg:p-8">
                {/* Yellow Alert */}
                <div className="bg-amber-100 border-l-4 border-amber-500 text-amber-800 p-4 mb-8 rounded-r shadow-sm flex items-start gap-3">
                    <span className="bg-amber-200 p-1 rounded text-amber-700 font-bold px-2">i</span>
                    <p className="text-sm">Welcome back! You have <strong>{upcomingAssignments.length} pending assignments</strong> to complete.</p>
                </div>

                {view === 'dashboard' && (
                    <div className="space-y-8 animate-fade-in">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Pending</h3><span className="text-4xl font-light text-orange-500">{upcomingAssignments.length}</span></div>
                                <div className="p-3 bg-orange-50 rounded-full"><Clock className="w-6 h-6 text-orange-500" /></div>
                            </div>
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Completed</h3><span className="text-4xl font-light text-teal-500">{completedResults.length}</span></div>
                                <div className="p-3 bg-teal-50 rounded-full"><CheckCircle2 className="w-6 h-6 text-teal-500" /></div>
                            </div>
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Avg Score</h3><span className="text-4xl font-light text-blue-500">{avgScore}%</span></div>
                                <div className="p-3 bg-blue-50 rounded-full"><RotateCcw className="w-6 h-6 text-blue-500" /></div>
                            </div>
                        </div>
                    </div>
                )}

                {(view === 'assignments' || view === 'dashboard') && upcomingAssignments.length > 0 && (
                    <div className="mt-8 animate-fade-in">
                        <h3 className="text-lg font-bold text-gray-700 mb-4">Pending Assignments</h3>
                        {loadingQuiz ? (
                            <div className="text-center py-8">
                                <Loader2 className="w-8 h-8 animate-spin text-teal-600 mx-auto" />
                                <p className="text-sm text-gray-500 mt-2">Preparing questions...</p>
                            </div>
                        ) : (
                            <div className="grid gap-4">
                                {upcomingAssignments.map(a => (
                                    <div key={a.id} className="bg-white p-5 rounded-xl border border-gray-200 hover:border-teal-500 shadow-sm flex justify-between items-center transition-all group">
                                        <div>
                                            <span className="text-xs font-bold text-teal-600 bg-teal-50 px-2 py-1 rounded uppercase">{a.subject}</span>
                                            <h4 className="font-bold text-gray-800 mt-2">{a.topic}</h4>
                                            <p className="text-xs text-gray-500 mt-1">{a.questions.length} Questions</p>
                                        </div>
                                        <button onClick={() => startAssignment(a)} className="bg-slate-900 text-white px-4 py-2 rounded text-sm font-bold hover:bg-slate-800 transition-colors">Start</button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {view === 'results' && (
                    <div className="animate-fade-in">
                        <h3 className="text-lg font-bold text-gray-700 mb-4">Revision History</h3>
                        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs">
                                    <tr>
                                        <th className="px-6 py-3">Topic</th>
                                        <th className="px-6 py-3">Date</th>
                                        <th className="px-6 py-3">Score</th>
                                        <th className="px-6 py-3">Attempts</th>
                                        <th className="px-6 py-3 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {completedResults.map(r => {
                                        const assign = getAssignmentById(r.assignmentId);
                                        return (
                                            <tr key={r.id} className="hover:bg-gray-50">
                                                <td className="px-6 py-4 font-medium">{assign?.topic || 'Unknown'}</td>
                                                <td className="px-6 py-4 text-gray-500">{new Date(r.dateTaken).toLocaleDateString()}</td>
                                                <td className="px-6 py-4 font-bold text-slate-800">{r.score}/{r.total}</td>
                                                <td className="px-6 py-4 text-gray-500">{r.attempts || 1}/3</td>
                                                <td className="px-6 py-4 text-right">
                                                    {(r.attempts || 1) < 3 ? (
                                                        <button 
                                                            onClick={() => assign && startAssignment(assign, true)} 
                                                            className="text-orange-600 hover:underline font-bold text-xs bg-orange-50 px-2 py-1 rounded"
                                                        >
                                                            Try Again
                                                        </button>
                                                    ) : (
                                                        <button onClick={() => viewRevision(r)} className="text-teal-600 hover:underline font-medium">Review Answers</button>
                                                    )}
                                                </td>
                                            </tr>
                                        );
                                    })}
                                    {completedResults.length === 0 && <tr><td colSpan={5} className="px-6 py-8 text-center text-gray-400">No history available.</td></tr>}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* QUIZ UI */}
                {view === 'quiz' && activeAssignment && quizQuestions.length > 0 && (
                    <div className="max-w-2xl mx-auto bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden animate-fade-in-up">
                        <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                            <h3 className="font-bold">{activeAssignment.subject} Quiz</h3>
                            <span className="text-xs bg-slate-800 px-2 py-1 rounded">Q {currentQuestionIndex + 1} of {quizQuestions.length}</span>
                        </div>
                        <div className="p-8">
                            <p className="text-lg font-medium text-gray-800 mb-6">{quizQuestions[currentQuestionIndex].question}</p>

                            {quizQuestions[currentQuestionIndex].type === 'mcq' && quizQuestions[currentQuestionIndex].options ? (
                                <div className="space-y-3">
                                    {quizQuestions[currentQuestionIndex].options?.map((opt, idx) => (
                                        <button key={idx} onClick={() => handleAnswerSelect(opt)} className={`w-full text-left p-4 rounded border transition-all ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                                            {opt}
                                        </button>
                                    ))}
                                </div>
                            ) : (
                                <div>
                                    <input 
                                        type="text" 
                                        className="w-full p-4 rounded border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-teal-500" 
                                        placeholder="Type your answer here..."
                                        value={selectedAnswers[currentQuestionIndex] || ''}
                                        onChange={(e) => handleAnswerSelect(e.target.value)}
                                    />
                                    <p className="text-xs text-gray-500 mt-2">Answer specifically and concisely.</p>
                                </div>
                            )}
                        </div>
                        <div className="p-6 bg-gray-50 border-t border-gray-200 flex justify-between">
                            <button onClick={() => setView('dashboard')} className="text-gray-500 hover:text-gray-700 font-medium">Exit</button>
                            {currentQuestionIndex < quizQuestions.length - 1 ? (
                                <button onClick={nextQuestion} disabled={!selectedAnswers[currentQuestionIndex]} className="bg-slate-900 text-white px-6 py-2 rounded font-bold hover:bg-slate-800 disabled:opacity-50">Next</button>
                            ) : (
                                <button onClick={submitQuiz} disabled={!selectedAnswers[currentQuestionIndex]} className="bg-teal-600 text-white px-6 py-2 rounded font-bold hover:bg-teal-700 disabled:opacity-50">Submit</button>
                            )}
                        </div>
                    </div>
                )}

                {/* REVISION UI */}
                {view === 'revision' && activeAssignment && quizResult && (
                    <div className="max-w-3xl mx-auto animate-fade-in">
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-2xl font-bold text-gray-800">Results Review</h2>
                            <button onClick={() => setView('results')} className="text-slate-600 hover:text-slate-900 flex items-center gap-1"><ArrowLeft className="w-4 h-4" /> Back</button>
                        </div>

                        {quizResult.feedback && (
                            <div className="bg-blue-50 border-l-4 border-blue-500 p-4 mb-6 rounded-r shadow-sm">
                                <div className="flex items-center gap-2 mb-2">
                                    <MessageSquare className="w-5 h-5 text-blue-600" />
                                    <h4 className="font-bold text-blue-800">Teacher Feedback</h4>
                                </div>
                                <p className="text-blue-900 text-sm italic">"{quizResult.feedback}"</p>
                            </div>
                        )}

                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm mb-6 flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500 uppercase tracking-wider">Score</p>
                                <p className="text-3xl font-black text-slate-900">{quizResult.score} <span className="text-lg text-gray-400 font-normal">/ {quizResult.total}</span></p>
                            </div>
                            <div className={`px-4 py-2 rounded-full font-bold text-sm ${quizResult.score/quizResult.total >= 0.5 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                {quizResult.score/quizResult.total >= 0.5 ? 'Passed' : 'Needs Improvement'}
                            </div>
                        </div>
                        <div className="space-y-4">
                            {/* Note: Revision only fully accurate if questions haven't changed. Using assignment questions as base. */}
                            {activeAssignment.questions.map((q, idx) => {
                                const selected = quizResult.answers[idx];
                                const isCorrect = selected?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim();
                                return (
                                    <div key={idx} className={`bg-white p-6 rounded-xl border-l-4 ${isCorrect ? 'border-l-green-500' : 'border-l-red-500'} shadow-sm`}>
                                        <p className="font-bold text-gray-800 mb-3"><span className="text-gray-400 mr-2">{idx+1}.</span> {q.question}</p>
                                        <div className="space-y-2 text-sm">
                                            <div className={`p-2 rounded ${isCorrect ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>
                                                <span className="font-bold">Your Answer:</span> {selected}
                                            </div>
                                            {!isCorrect && (
                                                <div className="p-2 rounded bg-green-50 text-green-800">
                                                    <span className="font-bold">Correct Answer:</span> {q.correctAnswer}
                                                </div>
                                            )}
                                        </div>
                                        {q.explanation && <div className="mt-3 text-xs text-gray-500 bg-gray-50 p-2 rounded"><strong>Explanation:</strong> {q.explanation}</div>}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* RESULT SUMMARY UI */}
                {view === 'result' && quizResult && (
                    <div className="max-w-md mx-auto bg-white rounded-xl shadow-xl border border-gray-200 text-center p-10 animate-fade-in-up mt-10">
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <Check className="w-10 h-10 text-green-600" />
                        </div>
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">Quiz Completed!</h2>
                        <p className="text-gray-500 mb-8">Attempt {quizResult.attempts}/3 recorded.</p>
                        <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 mb-8">
                            <p className="text-sm text-gray-500 uppercase tracking-widest font-bold mb-1">Your Score</p>
                            <p className="text-4xl font-black text-slate-800">{quizResult.score} <span className="text-xl text-gray-400 font-normal">/ {quizResult.total}</span></p>
                        </div>
                        <div className="flex gap-3 flex-col">
                            {(quizResult.attempts || 1) < 3 && (
                                <button 
                                    onClick={() => activeAssignment && startAssignment(activeAssignment, true)} 
                                    className="w-full bg-teal-600 text-white py-3 rounded-lg font-bold hover:bg-teal-700 shadow-md flex items-center justify-center gap-2"
                                >
                                    <RotateCcw className="w-4 h-4" /> Try Again (Improve Score)
                                </button>
                            )}
                            <div className="flex gap-3">
                                <button onClick={() => setView('dashboard')} className="flex-1 bg-white border border-gray-300 text-gray-700 py-3 rounded-lg font-bold hover:bg-gray-50">Dashboard</button>
                                <button onClick={() => viewRevision(quizResult)} className="flex-1 bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800">Review Answers</button>
                            </div>
                        </div>
                    </div>
                )}

            </main>
        </div>
    </div>
  );
};

export default StudentPortal;

import React, { useRef, useState, useEffect } from 'react';
import { LessonPlanData, Classroom, Assignment } from '../types';
import { Printer, Download, ArrowLeft, FileText, HelpCircle, Loader2, Save, Layout, Lock, Link, X, Copy, Check, Send } from 'lucide-react';
import { generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan, getCurrentUser, getClassrooms, saveAssignment } from '../services/storageService';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  const [currentPlan, setCurrentPlan] = useState<LessonPlanData>(plan);
  const [activeTab, setActiveTab] = useState<'plan' | 'notes' | 'questions'>('plan');

  const [loadingNotes, setLoadingNotes] = useState(false);
  const [loadingQuestions, setLoadingQuestions] = useState(false);

  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [isGuest, setIsGuest] = useState(false);

  // Assign to Class State
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [userClassrooms, setUserClassrooms] = useState<Classroom[]>([]);
  const [selectedClassId, setSelectedClassId] = useState<string>('');
  const [assigningStatus, setAssigningStatus] = useState<'idle' | 'assigning' | 'assigned'>('idle');

  useEffect(() => {
    setCurrentPlan(plan);
    const user = getCurrentUser();
    setIsGuest(!user);
    if (user) {
        setUserClassrooms(getClassrooms());
    }
  }, [plan]);

  const handlePrint = () => {
    window.print();
  };

  const handleSave = () => {
    if (isGuest) {
        alert("Please sign in or create an account to save lesson plans.");
        return;
    }
    setSaveStatus('saving');
    savePlan(currentPlan);
    setTimeout(() => setSaveStatus('saved'), 800);
    setTimeout(() => setSaveStatus('idle'), 3000);
  };

  const handleDownload = (section: 'plan' | 'notes' | 'questions') => {
    if (isGuest) {
        alert("Please sign in or create an account to download content.");
        return;
    }

    const isKiswahili = currentPlan.subject === 'Kiswahili';

    let title = '';
    let bodyContent = '';
    let fileNameSuffix = '';

    // STRICT FORMATTING FOR WORD EXPORT
    const metadataTable = `
      <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px; font-size: 10pt; font-family: Arial, sans-serif; border: 1px solid #000;">
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Teacher</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.teacherName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">School</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.schoolName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Date</td>
          <td style="border: 1px solid #000; padding: 4px; width: 10%;">${currentPlan.date}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Subject</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.subject}</td>
        </tr>
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Grade</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.grade}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Term</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.term}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Roll</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.roll}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Time</td>
          <td style="border: 1px solid #000; padding: 4px;">40 min</td>
        </tr>
      </table>
    `;

    if (section === 'plan') {
        title = `Lesson Plan - ${currentPlan.date}`;
        fileNameSuffix = 'Plan';
        bodyContent = `
          ${metadataTable}

          <div style="font-family: Arial, sans-serif; font-size: 10pt;">
            <p style="margin: 3px 0;"><strong>Strand:</strong> ${currentPlan.strand}</p>
            <p style="margin: 3px 0;"><strong>Sub-strand:</strong> ${currentPlan.subStrand}</p>
            <p style="margin: 10px 0; font-weight: bold; text-transform: uppercase;">${currentPlan.topic.toUpperCase()}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">SPECIFIC LEARNING OUTCOMES</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.learningOutcomes.map(o => `<li>${o}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">KEY INQUIRY QUESTIONS</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.keyInquiryQuestions.map(q => `<li>${q}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LEARNING RESOURCES</p>
            <p style="margin-top: 0;">${currentPlan.learningResources.join(", ")}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">INTRODUCTION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.introduction}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LESSON DEVELOPMENT (25 MIN)</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 1:</strong> ${currentPlan.developmentSteps.step1}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 2:</strong> ${currentPlan.developmentSteps.step2}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 3:</strong> ${currentPlan.developmentSteps.step3}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">EXTENDED ACTIVITIES</p>
            <p style="margin-top: 0;">${currentPlan.extendedActivities}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">CONCLUSION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.conclusion}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">REFLECTION</p>
            <div style="height: 60px; border: 1px solid #000; width: 100%;"></div>
          </div>
        `;
    } else if (section === 'notes') {
        // Notes export keeps simple format
        title = 'Learner Notes';
        fileNameSuffix = 'Notes';
        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Simplified Learner Notes</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${currentPlan.learnerNotes?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    } else if (section === 'questions') {
        // Questions export keeps simple format
        title = 'Practice Questions';
        fileNameSuffix = 'Questions';
        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Practice Questions</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${currentPlan.practiceQuestions?.replace(/\n/g, '<br/>') || ''}
            </div>
        `;
    }

    const content = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
        <head>
          <meta charset="utf-8">
          <title>${title}</title>
          <style>
            body { font-family: 'Arial', sans-serif; font-size: 10pt; }
          </style>
        </head>
        <body>
          ${bodyContent}
        </body>
      </html>
    `;

    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileNameSuffix}-${currentPlan.date}-${currentPlan.subject}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleGenerateNotes = async () => {
    setLoadingNotes(true);
    try {
      const generatedNotes = await generateSimplifiedNotes(currentPlan);
      const updatedPlan = { ...currentPlan, learnerNotes: generatedNotes };
      setCurrentPlan(updatedPlan);
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(currentPlan);
      const textRepresentation = generatedQuestions.map((q, i) => {
        if(q.type === 'mcq') {
            return `${i+1}. ${q.question}\nA) ${q.options?.[0]}\nB) ${q.options?.[1]}\nC) ${q.options?.[2]}\nD) ${q.options?.[3]}\nAnswer: ${q.correctAnswer}`;
        } else {
            return `${i+1}. ${q.question}\nAnswer: ${q.correctAnswer}`;
        }
      }).join('\n\n');

      const updatedPlan = { 
          ...currentPlan, 
          practiceQuestions: textRepresentation, 
          structuredQuestions: generatedQuestions 
      };

      setCurrentPlan(updatedPlan);
      if (!isGuest && localStorage.getItem('mwalimu_saved_plans')?.includes(currentPlan.id || '')) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  const handleAssignToClass = () => {
    if (isGuest) {
      alert("Please sign in to assign work to classes.");
      return;
    }
    if (!currentPlan.structuredQuestions || currentPlan.structuredQuestions.length === 0) {
      alert("Please generate practice questions first.");
      return;
    }
    if (userClassrooms.length === 0) {
        alert("You have no active classrooms. Go to your Dashboard to create one.");
        return;
    }
    setShowAssignModal(true);
  };

  const confirmAssignment = () => {
      if (!selectedClassId) return;
      setAssigningStatus('assigning');

      const assignment: Assignment = {
