        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response");

    const cleanedText = cleanJson(text);
    return JSON.parse(cleanedText) as QuizQuestion[];
  } catch (error) {
    console.error("Gemini API Error (Regeneration):", error);
    throw new Error("Failed to regenerate questions.");
  }
};

export const generateGoogleFormScript = async (title: string, questions: string): Promise<string> => {
  const prompt = `
    You are a Google Apps Script developer.
    Convert the following list of practice questions into a Google Apps Script that creates a Google Form Quiz.

    Lesson Title: "${title}"

    Questions Content:
    ${questions}

    Requirements for the Script:
    1. Function name must be 'createQuiz'.
    2. Use 'FormApp.create' to create a new form with the title "${title} - Practice Quiz".
    3. Set the form to be a quiz using 'setIsQuiz(true)'.
    4. Parse the questions provided above and add them to the form.
       - If the question text implies multiple choice (e.g. has options A, B, C), use 'addMultipleChoiceItem'.
       - If it is a direct question, use 'addTextItem' (Short Answer) or 'addParagraphItem' (Long Answer).
       - Mark all questions as required.
    5. At the end of the script, log the 'Published URL' and 'Edit URL' using Logger.log().
    6. RETURN ONLY THE RAW JAVASCRIPT CODE. Do not use markdown blocks (\`\`\`). Do not include explanation text.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: prompt,
    });
    let text = response.text || "";
    // Clean up if markdown is present despite instructions
    text = text.replace(/```javascript/g, '').replace(/```/g, '');
    return text;
  } catch (error) {
    console.error("Gemini API Error (Form Script):", error);
    throw new Error("Failed to generate form script.");
  }
};

export const fetchEducationNews = async (): Promise<NewsItem[]> => {
  const prompt = `
    Find the top 5 latest and most relevant news headlines regarding Education in Kenya, the Teachers Service Commission (TSC), and the Competency Based Curriculum (CBC) from the last 7 days.

    Return a strictly valid JSON array of objects. Each object must have these exact keys and values must be strings:
    - "title": The headline of the news.
    - "summary": A very brief summary (1-2 sentences).
    - "source": The name of the publisher (e.g., Daily Nation, The Standard).
    - "date": The date of the article.
    - "url": A valid link to the source if available (or a placeholder if not found).

    Do NOT return markdown formatting. Just the JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    // Clean and parse
