export default LessonPlanDisplay;

import React, { useState, useEffect, useMemo } from 'react';
import { Grade, Term, LessonDefinition, LessonPlanData, Subject, UserProfile } from '../types';
import { SCHEMES_OF_WORK } from '../data/maths';
import { PRETECH_SCHEMES } from '../data/pretech';
import { CREATIVE_ARTS_SCHEMES } from '../data/creative_arts';
import { CRE_SCHEMES } from '../data/cre';
import { INTEGRATED_SCIENCE_SCHEMES } from '../data/integrated_science';
import { SCIENCE_TECHNOLOGY_SCHEMES } from '../data/science_technology';
import { SOCIAL_STUDIES_SCHEMES } from '../data/social_studies';
import { AGRICULTURE_NUTRITION_SCHEMES } from '../data/agriculture_nutrition';
import { ENGLISH_SCHEMES } from '../data/english';
import { KISWAHILI_SCHEMES } from '../data/kiswahili';
import { generateLessonPlan } from '../services/geminiService';
import { Loader2, BookOpen, AlertCircle, Upload, Paperclip, X } from 'lucide-react';

interface Props {
  userProfile?: UserProfile | null;
  onPlanGenerated: (data: LessonPlanData) => void;
}

const LessonGenerator: React.FC<Props> = ({ userProfile, onPlanGenerated }) => {
  const [formData, setFormData] = useState({
    teacherName: userProfile?.name || '',
    schoolName: userProfile?.school || '',
    date: new Date().toISOString().split('T')[0],
    grade: Grade.GRADE_7,
    term: Term.TERM_1,
    roll: 40,
    subject: Subject.MATHEMATICS,
    customContext: '',
    images: [] as string[] // Array of base64 strings
  });

  // Effect to update form if profile changes (e.g. from dashboard)
  useEffect(() => {
    if (userProfile) {
        setFormData(prev => ({
            ...prev,
            teacherName: userProfile.name,
            schoolName: userProfile.school
        }));
    }
  }, [userProfile]);

  const [selectedStrand, setSelectedStrand] = useState<string>('');
  const [selectedSubStrand, setSelectedSubStrand] = useState<string>('');
  const [selectedLesson, setSelectedLesson] = useState<LessonDefinition | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Derived data based on Grade and Subject selection
  const gradeData = useMemo(() => {
    if (formData.subject === Subject.MATHEMATICS) {
      return SCHEMES_OF_WORK[formData.grade] || [];
    } else if (formData.subject === Subject.PRETECHNICAL_STUDIES) {
      return PRETECH_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.CREATIVE_ARTS) {
      return CREATIVE_ARTS_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.CHRISTIAN_RELIGIOUS_EDUCATION) {
      return CRE_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.INTEGRATED_SCIENCE) {
      return INTEGRATED_SCIENCE_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.SCIENCE_AND_TECHNOLOGY) {
      return SCIENCE_TECHNOLOGY_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.SOCIAL_STUDIES) {
      return SOCIAL_STUDIES_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.AGRICULTURE_AND_NUTRITION) {
      return AGRICULTURE_NUTRITION_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.ENGLISH) {
      return ENGLISH_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.KISWAHILI) {
      return KISWAHILI_SCHEMES[formData.grade] || [];
    }
    return [];
  }, [formData.grade, formData.subject]);

  const strands = useMemo(() => {
    return Array.from(new Set(gradeData.map(l => l.strand)));
  }, [gradeData]);

  const subStrands = useMemo(() => {
    return Array.from(new Set(gradeData.filter(l => l.strand === selectedStrand).map(l => l.subStrand)));
  }, [gradeData, selectedStrand]);

  const lessons = useMemo(() => {
    return gradeData.filter(l => l.strand === selectedStrand && l.subStrand === selectedSubStrand);
  }, [gradeData, selectedStrand, selectedSubStrand]);

  // Reset downstream selections when upstream changes
  useEffect(() => { setSelectedStrand(''); setSelectedSubStrand(''); setSelectedLesson(null); }, [formData.grade, formData.subject]);
  useEffect(() => { setSelectedSubStrand(''); setSelectedLesson(null); }, [selectedStrand]);
  useEffect(() => { setSelectedLesson(null); }, [selectedSubStrand]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files) {
          if (formData.images.length + files.length > 5) {
              alert("You can upload a maximum of 5 images.");
              return;
          }

          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  if (typeof reader.result === 'string') {
                      setFormData(prev => ({ ...prev, images: [...prev.images, reader.result as string] }));
                  }
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removeImage = (index: number) => {
      setFormData(prev => ({
          ...prev,
          images: prev.images.filter((_, i) => i !== index)
      }));
  };

  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedLesson) {
        setError("Please select a specific lesson.");
        return;
    }
    setError(null);
    setLoading(true);

    try {
      const cleanLessonDef = { ...selectedLesson, topic: cleanTopic(selectedLesson.topic) };
      const plan = await generateLessonPlan(formData, cleanLessonDef);
      // Add ID and timestamp here
      const completePlan = {
        ...plan,
        topic: cleanTopic(plan.topic), // Ensure topic is clean in final plan too
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString()
      };
      onPlanGenerated(completePlan);
    } catch (err: any) {
      setError(err.message || "An error occurred generating the plan.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden no-print">
      <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex items-center gap-2">
        <BookOpen className="text-teal-600 w-5 h-5" />
        <h2 className="text-lg font-semibold text-gray-800">Lesson Plan Generator</h2>
      </div>

      <form onSubmit={handleSubmit} className="p-6 md:p-8 space-y-8">

        {/* Top Table-like Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">

            {/* Teacher & School */}
            <div className="space-y-4">
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Teacher</label>
                    <input 
                        required
                        type="text" 
                        value={formData.teacherName}
                        onChange={e => setFormData({...formData, teacherName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border bg-gray-50"
                        placeholder="Enter Name"
                    />
                </div>
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">School</label>
                    <input 
                        required
                        type="text" 
                        value={formData.schoolName}
                        onChange={e => setFormData({...formData, schoolName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border bg-gray-50"
                        placeholder="Enter School"
                    />
                </div>
            </div>

            {/* Date, Subject, Time */}
            <div className="space-y-4">
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Date</label>
                    <input 
                        type="date" 
                        value={formData.date}
                        onChange={e => setFormData({...formData, date: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                    />
                </div>
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Subject</label>
                    <select 
                        value={formData.subject}
                        onChange={e => setFormData({...formData, subject: e.target.value as Subject})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                    >
                        {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </div>
        </div>

        {/* Separator */}
        <div className="h-px bg-gray-200 w-full"></div>

        {/* Class Details Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Grade</label>
                <select 
                    value={formData.grade}
                    onChange={e => setFormData({...formData, grade: e.target.value as Grade})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Term</label>
                <select 
                    value={formData.term}
                    onChange={e => setFormData({...formData, term: e.target.value as Term})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Term).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
            </div>
             <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Roll (Class Size)</label>
                <input 
                    type="number"
                    value={formData.roll}
                    onChange={e => setFormData({...formData, roll: parseInt(e.target.value)})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                />
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Time</label>
                <div className="w-full py-2 px-3 bg-gray-100 rounded-md text-gray-700 border border-gray-200">
                    40 Minutes
                </div>
            </div>
        </div>

        {/* Cascading Content Selection */}
        <div className="bg-teal-50 p-6 rounded-lg border border-teal-100 space-y-6">
            <h3 className="text-teal-800 font-medium border-b border-teal-200 pb-2">Curriculum Content Selector</h3>

            {gradeData.length === 0 ? (
                <div className="text-center text-gray-500 py-4">No lesson data available for {formData.subject} - {formData.grade}</div>
            ) : (
                <>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-teal-800 mb-2">Select Strand</label>
                            <select 
                                value={selectedStrand}
                                onChange={e => setSelectedStrand(e.target.value)}
                                className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                                disabled={strands.length === 0}
                            >
                                <option value="">-- Choose Strand --</option>
                                {strands.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-teal-800 mb-2">Select Sub-strand</label>
                            <select 
                                value={selectedSubStrand}
                                onChange={e => setSelectedSubStrand(e.target.value)}
                                className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                                disabled={!selectedStrand}
                            >
                                <option value="">-- Choose Sub-strand --</option>
                                {subStrands.map(ss => <option key={ss} value={ss}>{ss}</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-teal-800 mb-2">Select Lesson</label>
                        <select 
                            value={selectedLesson ? JSON.stringify(selectedLesson) : ""}
                            onChange={e => {
                                if(e.target.value) setSelectedLesson(JSON.parse(e.target.value));
                            }}
                            className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                            disabled={!selectedSubStrand}
                        >
                            <option value="">-- Choose Lesson --</option>
                            {lessons.map((l, idx) => (
                                <option key={idx} value={JSON.stringify(l)}>{cleanTopic(l.topic)}</option>
                            ))}
                        </select>
                    </div>

                    {selectedLesson && (
                        <div className="mt-4 p-4 bg-white/60 rounded border border-teal-200 text-sm text-teal-900">
                            <p><strong>Preview Learning Outcome:</strong> {selectedLesson.learningOutcomes[0]}</p>
                        </div>
                    )}
                </>
            )}
        </div>

        {/* Custom Context & Resources */}
        <div className="border border-gray-200 rounded-lg p-6 bg-gray-50">
            <h3 className="text-gray-800 font-medium mb-4 flex items-center gap-2">
                <Paperclip className="w-4 h-4 text-gray-500" />
                Additional Context & Resources (Optional)
            </h3>

            <div className="space-y-4">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Teacher Notes / Custom Context</label>
                    <textarea 
                        className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-3 text-sm"
                        rows={3}
                        placeholder="Paste any specific notes, classroom context, or additional requirements here..."
                        value={formData.customContext}
                        onChange={(e) => setFormData({...formData, customContext: e.target.value})}
                    ></textarea>
                </div>

                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Upload Photos (Max 5)</label>
                    <div className="flex items-center gap-4">
                        <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 px-4 py-2 rounded-md shadow-sm text-sm font-medium text-gray-700 flex items-center gap-2 transition-colors">
                            <Upload className="w-4 h-4" />
                            Select Images
                            <input 
                                type="file" 
                                accept="image/*" 
                                multiple 
                                className="hidden" 
                                onChange={handleImageUpload}
                                disabled={formData.images.length >= 5}
                            />
                        </label>
                        <span className="text-xs text-gray-500">{formData.images.length} / 5 uploaded</span>
                    </div>

                    {formData.images.length > 0 && (
                        <div className="flex gap-2 mt-3 overflow-x-auto pb-2">
                            {formData.images.map((img, idx) => (
                                <div key={idx} className="relative w-16 h-16 shrink-0 border border-gray-200 rounded-md overflow-hidden group">
                                    <img src={img} alt={`Upload ${idx+1}`} className="w-full h-full object-cover" />
                                    <button 
                                        type="button"
                                        onClick={() => removeImage(idx)}
                                        className="absolute top-0 right-0 bg-red-500 text-white p-0.5 rounded-bl opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                        <X className="w-3 h-3" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>

        {error && (
            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded flex items-center gap-3">
                <AlertCircle className="text-red-500" />
                <p className="text-red-700">{error}</p>
            </div>
        )}

        {/* Actions */}
        <div className="flex gap-4 pt-2">
            <button 
                type="button" 
                className="px-6 py-3 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500"
                onClick={() => {
                   setFormData({...formData, teacherName: '', schoolName: '', customContext: '', images: []});
                   setSelectedStrand('');
                }}
            >
                Reset Form
            </button>
            <button 
                type="submit" 
                disabled={loading || !selectedLesson}
                className="flex-1 flex justify-center items-center gap-2 px-6 py-3 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-teal-600 hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin h-5 w-5" />
                        Generating Plan with AI...
                    </>
                ) : (
                    "Generate Lesson Plan"
                )}
            </button>
        </div>

      </form>
    </div>
  );
};

export default LessonGenerator;

import React, { useState } from 'react';
import { Classroom, Assignment, StudentResult, Student, QuizQuestion, SharedNote } from '../types';
import { authenticateStudent, getAssignmentsByClassId, saveStudentResult, updateStudentName, getStudentResults, getStudentNotes } from '../services/storageService';
import { generateSimilarQuestions } from '../services/geminiService';
import { BookOpen, Check, ChevronRight, GraduationCap, LogIn, AlertCircle, Key, ArrowLeft, LayoutDashboard, Clock, CheckCircle2, XCircle, RotateCcw, Menu, Bell, ChevronDown, FileText, List, User, LogOut, MessageSquare, Loader2, StickyNote } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'enterName' | 'dashboard' | 'assignments' | 'results' | 'quiz' | 'revision' | 'notes'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [studentNameInput, setStudentNameInput] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Session State
  const [currentStudent, setCurrentStudent] = useState<Student | null>(null);
  const [currentClassroom, setCurrentClassroom] = useState<Classroom | null>(null);
  const [classAssignments, setClassAssignments] = useState<Assignment[]>([]);
  const [completedResults, setCompletedResults] = useState<StudentResult[]>([]);
  const [classNotes, setClassNotes] = useState<SharedNote[]>([]);
  const [selectedNote, setSelectedNote] = useState<SharedNote | null>(null);

  // Active Quiz/Revision State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]); // To hold current set (original or regenerated)
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizResult, setQuizResult] = useState<StudentResult | null>(null);

  const [loadingQuiz, setLoadingQuiz] = useState(false);
  const [error, setError] = useState('');

  // Helper
  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');
  const cleanText = (text: string) => text.replace(/[*#]/g, '');

  // --- Auth Flow ---

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!accessCode) {
        setError("Please enter your Access Code.");
        return;
    }

    const authResult = authenticateStudent(accessCode.toUpperCase());
    if (authResult) {
        setCurrentStudent(authResult.student);
        setCurrentClassroom(authResult.classroom);

        if (!authResult.student.name) {
            setView('enterName');
        } else {
            loadStudentData(authResult.student, authResult.classroom);
            setView('dashboard');
        }
        setAccessCode('');
    } else {
        setError("Invalid Access Code. Please check and try again.");
    }
  };

  const handleNameSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!studentNameInput.trim() || !currentClassroom || !currentStudent) return;

      const updatedStudent = updateStudentName(currentClassroom.id, currentStudent.code, studentNameInput.trim());
      if (updatedStudent) {
          setCurrentStudent(updatedStudent);
          loadStudentData(updatedStudent, currentClassroom);
          setView('dashboard');
      }
  };

  const loadStudentData = (student: Student, classroom: Classroom) => {
      const allTasks = getAssignmentsByClassId(classroom.id);
      const results = getStudentResults(student.code);
      const notes = getStudentNotes(classroom.id);
      setClassAssignments(allTasks);
      setCompletedResults(results);
      setClassNotes(notes);
  };

  const handleLogout = () => {
      setCurrentStudent(null);
      setCurrentClassroom(null);
      setView('login');
      setStudentNameInput('');
      setSelectedAnswers({});
  };

  const upcomingAssignments = classAssignments.filter(a => 
      !completedResults.some(r => r.assignmentId === a.id)
  );

  const getAssignmentById = (id: string) => classAssignments.find(a => a.id === id);

  const startAssignment = async (assignment: Assignment, isReattempt = false) => {
      setLoadingQuiz(true);
      setActiveAssignment(assignment);

      try {
          if (isReattempt && assignment.grade) {
              // Generate new similar questions
              const newQuestions = await generateSimilarQuestions(assignment.topic, assignment.subject, assignment.grade);
              setQuizQuestions(newQuestions);
          } else {
              // Use original questions
              setQuizQuestions(assignment.questions);
          }

          setCurrentQuestionIndex(0);
          setSelectedAnswers({});
          setQuizResult(null);
          setView('quiz');
      } catch (err) {
          alert("Could not load questions. Please try again.");
      } finally {
          setLoadingQuiz(false);
      }
  };

  const handleAnswerSelect = (option: string) => {
      setSelectedAnswers(prev => ({ ...prev, [currentQuestionIndex]: option }));
  };

  const nextQuestion = () => {
      if (activeAssignment && currentQuestionIndex < quizQuestions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const submitQuiz = () => {
      if (!activeAssignment || !currentStudent) return;

      let score = 0;
      quizQuestions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx]?.toLowerCase().trim() || "";
          const correct = q.correctAnswer.toLowerCase().trim();

          // Basic exact match check (improve with fuzzy logic if needed later)
          if (userAnswer === correct || (q.type === 'mcq' && userAnswer === correct)) {
              score++;
          }
      });

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: currentStudent.code,
          studentName: currentStudent.name || `Index ${currentStudent.index}`,
          score: score,
          total: quizQuestions.length,
          attempts: 1, // Will be incremented in storage if exists
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);

      // Update local state to reflect new attempt count/score
      setCompletedResults(getStudentResults(currentStudent.code));

      // Get the latest result object (with updated attempt count)
      const updatedResults = getStudentResults(currentStudent.code);
      const latestResult = updatedResults.find(r => r.assignmentId === activeAssignment.id) || result;

      setQuizResult(latestResult);
      setView('result'); // Shows summary
  };

  const viewRevision = (result: StudentResult) => {
      const assignment = getAssignmentById(result.assignmentId);
      if (assignment) {
          setActiveAssignment(assignment);
          // For revision, we can only reliably show original questions if we didn't store re-generated ones.
          // Assumption: result.answers keys align with assignment.questions indices.
          // NOTE: If questions were regenerated, we can't show exact revision unless we store questions in result.
          // For MVP, falling back to original questions or hiding detail if mismatch.
          setQuizQuestions(assignment.questions); 
          setQuizResult(result);
          setView('revision');
      }
  };

  // Stats for Dashboard
  const avgScore = completedResults.length > 0 
    ? Math.round(completedResults.reduce((acc, curr) => acc + (curr.score/curr.total)*100, 0) / completedResults.length) 
    : 0;

  // Render Login Views
  if (view === 'login') {
      return (
        <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
            <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
                <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-slate-900 text-teal-400 rounded-full flex items-center justify-center mx-auto mb-4">
                        <GraduationCap className="w-8 h-8" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                    <p className="text-gray-500">Enter your access code</p>
                </div>
                {error && <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}
                <form onSubmit={handleLogin} className="space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none"><Key className="h-5 w-5 text-gray-400" /></div>
                            <input type="text" value={accessCode} onChange={(e) => setAccessCode(e.target.value.toUpperCase())} className="w-full pl-10 px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 text-center text-lg uppercase tracking-widest font-mono" placeholder="XXXXXX" maxLength={6} />
                        </div>
                    </div>
                    <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800 transition-colors shadow-md">Enter Dashboard</button>
                </form>
            </div>
        </div>
      );
  }

  if (view === 'enterName') {
      return (
          <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
              <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
                  <div className="text-center mb-6">
                      <h2 className="text-2xl font-bold text-gray-800">Welcome!</h2>
                      <p className="text-gray-500">Please enter your full name.</p>
                  </div>
                  <form onSubmit={handleNameSubmit} className="space-y-6">
                      <input type="text" required value={studentNameInput} onChange={(e) => setStudentNameInput(e.target.value)} className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500" placeholder="e.g. John Kamau" />
                      <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800">Continue</button>
                  </form>
              </div>
          </div>
      );
  }

  // LOGGED IN DASHBOARD LAYOUT
  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">

        {/* Sidebar */}
        <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-slate-300 transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 shadow-xl`}>
            <div className="flex items-center h-16 px-6 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800">
                <GraduationCap className="w-6 h-6 mr-2 text-teal-500" />
                Student<span className="text-teal-500">Portal</span>
            </div>
            <div className="p-4">
                <div className="bg-slate-800 rounded p-3 mb-6">
                    <p className="text-xs text-slate-400 uppercase tracking-wider">Class</p>
                    <p className="font-bold text-white">{currentClassroom?.grade} - {currentClassroom?.stream}</p>
                </div>
                <nav className="space-y-2">
                    <button onClick={() => setView('dashboard')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'dashboard' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <LayoutDashboard className="w-5 h-5 mr-3" /> Overview
                    </button>
                    <button onClick={() => setView('assignments')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'assignments' || view === 'quiz' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <FileText className="w-5 h-5 mr-3" /> Assignments
                        {upcomingAssignments.length > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{upcomingAssignments.length}</span>}
                    </button>
                    <button onClick={() => setView('results')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'results' || view === 'revision' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <List className="w-5 h-5 mr-3" /> Results
                    </button>
                    <button onClick={() => setView('notes')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'notes' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <StickyNote className="w-5 h-5 mr-3" /> Class Notes
                    </button>
                </nav>
            </div>
            <div className="absolute bottom-0 w-full p-4 border-t border-slate-800">
                <button onClick={handleLogout} className="flex items-center w-full px-4 py-2 text-sm text-slate-400 hover:text-red-400 transition-colors">
                    <LogOut className="w-4 h-4 mr-3" /> Sign Out
                </button>
            </div>
        </aside>

        {/* Main Content */}
        <div className={`flex-1 flex flex-col transition-all duration-300 ${sidebarOpen ? 'lg:ml-64' : ''}`}>

            {/* Header */}
            <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 sticky top-0 z-40 shadow-sm">
                <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500"><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 ml-auto">
                    <div className="flex items-center gap-2 pl-4 border-l border-gray-200">
                        <div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center text-xs font-bold">{currentStudent?.name?.charAt(0)}</div>
                        <span className="text-sm font-medium text-gray-700 hidden md:block">{currentStudent?.name}</span>
                    </div>
                </div>
            </header>

            <main className="p-4 lg:p-8">
                {/* Yellow Alert */}
                <div className="bg-amber-100 border-l-4 border-amber-500 text-amber-800 p-4 mb-8 rounded-r shadow-sm flex items-start gap-3">
                    <span className="bg-amber-200 p-1 rounded text-amber-700 font-bold px-2">i</span>
                    <p className="text-sm">Welcome back! You have <strong>{upcomingAssignments.length} pending assignments</strong> to complete.</p>
                </div>

                {view === 'dashboard' && (
                    <div className="space-y-8 animate-fade-in">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Pending</h3><span className="text-4xl font-light text-orange-500">{upcomingAssignments.length}</span></div>
                                <div className="p-3 bg-orange-50 rounded-full"><Clock className="w-6 h-6 text-orange-500" /></div>
                            </div>
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Completed</h3><span className="text-4xl font-light text-teal-500">{completedResults.length}</span></div>
                                <div className="p-3 bg-teal-50 rounded-full"><CheckCircle2 className="w-6 h-6 text-teal-500" /></div>
                            </div>
                            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex justify-between items-center hover:-translate-y-1 transition-transform">
                                <div><h3 className="text-gray-500 text-xs font-bold uppercase">Avg Score</h3><span className="text-4xl font-light text-blue-500">{avgScore}%</span></div>
                                <div className="p-3 bg-blue-50 rounded-full"><RotateCcw className="w-6 h-6 text-blue-500" /></div>
                            </div>
                        </div>
                    </div>
                )}

                {(view === 'assignments' || view === 'dashboard') && upcomingAssignments.length > 0 && (
                    <div className="mt-8 animate-fade-in">
                        <h3 className="text-lg font-bold text-gray-700 mb-4">Pending Assignments</h3>
                        {loadingQuiz ? (
                            <div className="text-center py-8">
                                <Loader2 className="w-8 h-8 animate-spin text-teal-600 mx-auto" />
                                <p className="text-sm text-gray-500 mt-2">Preparing questions...</p>
                            </div>
                        ) : (
                            <div className="grid gap-4">
                                {upcomingAssignments.map(a => (
                                    <div key={a.id} className="bg-white p-5 rounded-xl border border-gray-200 hover:border-teal-500 shadow-sm flex justify-between items-center transition-all group">
                                        <div>
                                            <span className="text-xs font-bold text-teal-600 bg-teal-50 px-2 py-1 rounded uppercase">{a.subject}</span>
                                            <h4 className="font-bold text-gray-800 mt-2">{cleanTopic(a.topic)}</h4>
                                            <p className="text-xs text-gray-500 mt-1">{a.questions.length} Questions</p>
                                        </div>
                                        <button onClick={() => startAssignment(a)} className="bg-slate-900 text-white px-4 py-2 rounded text-sm font-bold hover:bg-slate-800 transition-colors">Start</button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {view === 'results' && (
                    <div className="animate-fade-in">
                        <h3 className="text-lg font-bold text-gray-700 mb-4">Revision History</h3>
                        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs">
                                    <tr>
                                        <th className="px-6 py-3">Topic</th>
                                        <th className="px-6 py-3">Date</th>
                                        <th className="px-6 py-3">Score</th>
                                        <th className="px-6 py-3">Attempts</th>
                                        <th className="px-6 py-3 text-right">Action</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-100">
                                    {completedResults.map(r => {
                                        const assign = getAssignmentById(r.assignmentId);
                                        return (
                                            <tr key={r.id} className="hover:bg-gray-50">
                                                <td className="px-6 py-4 font-medium">{assign ? cleanTopic(assign.topic) : 'Unknown'}</td>
                                                <td className="px-6 py-4 text-gray-500">{new Date(r.dateTaken).toLocaleDateString()}</td>
                                                <td className="px-6 py-4 font-bold text-slate-800">{r.score}/{r.total}</td>
                                                <td className="px-6 py-4 text-gray-500">{r.attempts || 1}/3</td>
                                                <td className="px-6 py-4 text-right">
                                                    {(r.attempts || 1) < 3 ? (
                                                        <button 
                                                            onClick={() => assign && startAssignment(assign, true)} 
                                                            className="text-orange-600 hover:underline font-bold text-xs bg-orange-50 px-2 py-1 rounded"
                                                        >
                                                            Try Again
                                                        </button>
                                                    ) : (
                                                        <button onClick={() => viewRevision(r)} className="text-teal-600 hover:underline font-medium">Review Answers</button>
                                                    )}
                                                </td>
                                            </tr>
                                        );
                                    })}
                                    {completedResults.length === 0 && <tr><td colSpan={5} className="px-6 py-8 text-center text-gray-400">No history available.</td></tr>}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* NOTES VIEW */}
                {view === 'notes' && (
                    <div className="animate-fade-in">
                        {selectedNote ? (
                            <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                                <div className="bg-slate-50 p-6 border-b border-gray-200 flex justify-between items-start">
                                    <div>
                                        <button onClick={() => setSelectedNote(null)} className="text-sm text-gray-500 hover:text-gray-800 mb-2 flex items-center gap-1">
                                            <ArrowLeft className="w-4 h-4" /> Back to Notes
                                        </button>
                                        <h2 className="text-2xl font-bold text-slate-800">{cleanTopic(selectedNote.title)}</h2>
                                        <p className="text-sm text-gray-500 mt-1">{selectedNote.subject} • {new Date(selectedNote.dateShared).toLocaleDateString()}</p>
                                    </div>
                                </div>
                                <div className="p-8 prose max-w-none whitespace-pre-wrap text-slate-700">
                                    {cleanText(selectedNote.content)}
                                </div>
                            </div>
                        ) : (
                            <>
                                <h3 className="text-lg font-bold text-gray-700 mb-4">Classroom Notes</h3>
                                {classNotes.length === 0 ? (
                                    <div className="text-center py-16 bg-white rounded-xl shadow-sm border border-gray-200">
                                        <div className="bg-gray-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                                            <StickyNote className="w-8 h-8 text-gray-400" />
                                        </div>
                                        <h3 className="text-lg font-medium text-gray-900">No notes shared yet</h3>
                                        <p className="text-gray-500 mt-1">Your teacher hasn't shared any notes for this class yet.</p>
                                    </div>
                                ) : (
                                    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                                        {classNotes.map(note => (
                                            <div 
                                                key={note.id} 
                                                onClick={() => setSelectedNote(note)}
                                                className="bg-white p-5 rounded-xl border border-gray-200 hover:border-teal-500 shadow-sm cursor-pointer transition-all group"
                                            >
                                                <div className="flex justify-between items-start mb-2">
                                                    <span className="text-xs font-bold text-teal-600 bg-teal-50 px-2 py-1 rounded uppercase">{note.subject}</span>
                                                    <span className="text-xs text-gray-400">{new Date(note.dateShared).toLocaleDateString()}</span>
                                                </div>
                                                <h4 className="font-bold text-gray-800 mb-2 line-clamp-2">{cleanTopic(note.title)}</h4>
                                                <p className="text-sm text-gray-500 line-clamp-3">{cleanText(note.content)}</p>
                                                <div className="mt-3 flex items-center text-teal-600 text-xs font-bold">
                                                    Read Note <ChevronRight className="w-3 h-3 ml-1 group-hover:translate-x-1 transition-transform" />
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                )}

                {/* QUIZ UI */}
                {view === 'quiz' && activeAssignment && quizQuestions.length > 0 && (
                    <div className="max-w-2xl mx-auto bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden animate-fade-in-up">
                        <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                            <h3 className="font-bold">{activeAssignment.subject} Quiz</h3>
                            <span className="text-xs bg-slate-800 px-2 py-1 rounded">Q {currentQuestionIndex + 1} of {quizQuestions.length}</span>
                        </div>
                        <div className="p-8">
                            <p className="text-lg font-medium text-gray-800 mb-6">{quizQuestions[currentQuestionIndex].question}</p>

                            {/* Always render as MCQ per user request */}
                            {quizQuestions[currentQuestionIndex].options ? (
                                <div className="space-y-3">
                                    {quizQuestions[currentQuestionIndex].options?.map((opt, idx) => (
                                        <button key={idx} onClick={() => handleAnswerSelect(opt)} className={`w-full text-left p-4 rounded border transition-all ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                                            {opt}
                                        </button>
                                    ))}
                                </div>
                            ) : (
                                // Fallback just in case, though prompt forces MCQ
                                <div>
                                    <input 
                                        type="text" 
                                        className="w-full p-4 rounded border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-teal-500" 
                                        placeholder="Type your answer here..."
                                        value={selectedAnswers[currentQuestionIndex] || ''}
                                        onChange={(e) => handleAnswerSelect(e.target.value)}
                                    />
                                </div>
                            )}
                        </div>
                        <div className="p-6 bg-gray-50 border-t border-gray-200 flex justify-between">
                            <button onClick={() => setView('dashboard')} className="text-gray-500 hover:text-gray-700 font-medium">Exit</button>
                            {currentQuestionIndex < quizQuestions.length - 1 ? (
                                <button onClick={nextQuestion} disabled={!selectedAnswers[currentQuestionIndex]} className="bg-slate-900 text-white px-6 py-2 rounded font-bold hover:bg-slate-800 disabled:opacity-50">Next</button>
                            ) : (
                                <button onClick={submitQuiz} disabled={!selectedAnswers[currentQuestionIndex]} className="bg-teal-600 text-white px-6 py-2 rounded font-bold hover:bg-teal-700 disabled:opacity-50">Submit</button>
                            )}
                        </div>
                    </div>
                )}

                {/* REVISION UI */}
                {view === 'revision' && activeAssignment && quizResult && (
                    <div className="max-w-3xl mx-auto animate-fade-in">
                        <div className="flex justify-between items-center mb-6">
                            <h2 className="text-2xl font-bold text-gray-800">Results Review</h2>
                            <button onClick={() => setView('results')} className="text-slate-600 hover:text-slate-900 flex items-center gap-1"><ArrowLeft className="w-4 h-4" /> Back</button>
                        </div>

                        {quizResult.feedback && (
                            <div className="bg-blue-50 border-l-4 border-blue-500 p-4 mb-6 rounded-r shadow-sm">
                                <div className="flex items-center gap-2 mb-2">
                                    <MessageSquare className="w-5 h-5 text-blue-600" />
                                    <h4 className="font-bold text-blue-800">Teacher Feedback</h4>
                                </div>
                                <p className="text-blue-900 text-sm italic">"{quizResult.feedback}"</p>
                            </div>
                        )}

                        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm mb-6 flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500 uppercase tracking-wider">Score</p>
                                <p className="text-3xl font-black text-slate-900">{quizResult.score} <span className="text-lg text-gray-400 font-normal">/ {quizResult.total}</span></p>
                            </div>
                            <div className={`px-4 py-2 rounded-full font-bold text-sm ${quizResult.score/quizResult.total >= 0.5 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                {quizResult.score/quizResult.total >= 0.5 ? 'Passed' : 'Needs Improvement'}
                            </div>
                        </div>
                        <div className="space-y-4">
                            {/* Note: Revision only fully accurate if questions haven't changed. Using assignment questions as base. */}
                            {activeAssignment.questions.map((q, idx) => {
                                const selected = quizResult.answers[idx];
                                const isCorrect = selected?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim();
                                return (
                                    <div key={idx} className={`bg-white p-6 rounded-xl border-l-4 ${isCorrect ? 'border-l-green-500' : 'border-l-red-500'} shadow-sm`}>
                                        <p className="font-bold text-gray-800 mb-3"><span className="text-gray-400 mr-2">{idx+1}.</span> {q.question}</p>
                                        <div className="space-y-2 text-sm">
                                            <div className={`p-2 rounded ${isCorrect ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>
                                                <span className="font-bold">Your Answer:</span> {selected}
                                            </div>
                                            {!isCorrect && (
                                                <div className="p-2 rounded bg-green-50 text-green-800">
                                                    <span className="font-bold">Correct Answer:</span> {q.correctAnswer}
                                                </div>
                                            )}
                                        </div>
                                        {q.explanation && <div className="mt-3 text-xs text-gray-500 bg-gray-50 p-2 rounded"><strong>Explanation:</strong> {q.explanation}</div>}
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* RESULT SUMMARY UI */}
                {view === 'result' && quizResult && (
                    <div className="max-w-md mx-auto bg-white rounded-xl shadow-xl border border-gray-200 text-center p-10 animate-fade-in-up mt-10">
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                            <Check className="w-10 h-10 text-green-600" />
                        </div>
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">Quiz Completed!</h2>
                        <p className="text-gray-500 mb-8">Attempt {quizResult.attempts}/3 recorded.</p>
                        <div className="bg-slate-50 p-6 rounded-xl border border-slate-100 mb-8">
                            <p className="text-sm text-gray-500 uppercase tracking-widest font-bold mb-1">Your Score</p>
                            <p className="text-4xl font-black text-slate-800">{quizResult.score} <span className="text-xl text-gray-400 font-normal">/ {quizResult.total}</span></p>
                        </div>
                        <div className="flex gap-3 flex-col">
                            {(quizResult.attempts || 1) < 3 && (
                                <button 
                                    onClick={() => activeAssignment && startAssignment(activeAssignment, true)} 
                                    className="w-full bg-teal-600 text-white py-3 rounded-lg font-bold hover:bg-teal-700 shadow-md flex items-center justify-center gap-2"
                                >
                                    <RotateCcw className="w-4 h-4" /> Try Again (Improve Score)
                                </button>
                            )}
                            <div className="flex gap-3">
                                <button onClick={() => setView('dashboard')} className="flex-1 bg-white border border-gray-300 text-gray-700 py-3 rounded-lg font-bold hover:bg-gray-50">Dashboard</button>
                                <button onClick={() => viewRevision(quizResult)} className="flex-1 bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800">Review Answers</button>
                            </div>
                        </div>
                    </div>
                )}

            </main>
        </div>
    </div>
  );
};

export default StudentPortal;

import React, { useState, useEffect } from 'react';
import { LessonPlanData } from '../types';
import { getSavedPlans, deletePlan } from '../services/storageService';
import { FileText, Calendar, Trash2, ChevronRight, Search } from 'lucide-react';

interface Props {
  onSelectPlan: (plan: LessonPlanData) => void;
}

const SavedPlans: React.FC<Props> = ({ onSelectPlan }) => {
  const [plans, setPlans] = useState<LessonPlanData[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    setPlans(getSavedPlans());
  }, []);

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('Are you sure you want to delete this lesson plan?')) {
      deletePlan(id);
      setPlans(getSavedPlans());
    }
  };

  const filteredPlans = plans.filter(p => 
    p.topic.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.subject.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.grade.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');

  return (
    <div className="max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Saved Lesson Plans</h2>
        <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
            <input 
                type="text" 
                placeholder="Search plans..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
            />
        </div>
      </div>

      {filteredPlans.length === 0 ? (
        <div className="text-center py-16 bg-white rounded-xl shadow-sm border border-gray-200">
          <div className="bg-gray-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
            <FileText className="w-8 h-8 text-gray-400" />
          </div>
          <h3 className="text-lg font-medium text-gray-900">No saved plans found</h3>
          <p className="text-gray-500 mt-1">Generate a lesson plan and click "Save" to see it here.</p>
        </div>
      ) : (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
          <ul className="divide-y divide-gray-200">
            {filteredPlans.map((plan) => (
              <li 
                key={plan.id} 
                onClick={() => onSelectPlan(plan)}
                className="group hover:bg-gray-50 transition-colors cursor-pointer"
              >
                <div className="p-5 flex items-center justify-between">
                  <div className="flex-1 min-w-0">
                    <h3 className="text-base font-semibold text-teal-800 truncate mb-1 group-hover:text-teal-600">
                      {cleanTopic(plan.lessonNumber || plan.topic)}
                    </h3>
                    <div className="flex flex-wrap gap-x-4 gap-y-1 text-sm text-gray-500">
                      <span className="flex items-center gap-1">
                        <span className="font-medium text-gray-700">{plan.subject}</span>
                      </span>
                      <span className="flex items-center gap-1">
                        <span className="bg-gray-200 text-xs px-2 py-0.5 rounded-full">{plan.grade}</span>
                      </span>
                      <span className="flex items-center gap-1">
                        <Calendar className="w-3 h-3" />
                        {new Date(plan.date).toLocaleDateString()}
                      </span>
                    </div>
                  </div>

                  <div className="flex items-center gap-4 ml-4">
                    <button
                        onClick={(e) => handleDelete(e, plan.id || '')}
                        className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                        title="Delete Plan"
                    >
                        <Trash2 className="w-4 h-4" />
                    </button>
                    <ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" />
                  </div>
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

export default SavedPlans;

import React, { useState, useEffect } from 'react';
