import SavedPlans from './components/SavedPlans';
import NewsSection from './components/NewsSection';
import AdminDashboard from './components/AdminDashboard';
import StudentPortal from './components/StudentPortal';
import MwalimuBot from './components/MwalimuBot';
import { LessonPlanData, UserProfile } from './types';
import { LayoutDashboard, FileText, LogOut, Save, Newspaper, Shield } from 'lucide-react';
import { getCurrentUser, logoutUser, updateUserProfile } from './services/storageService';

function App() {
  // Initialize user state directly from storage to persist login across reloads/updates
  const [user, setUser] = useState<UserProfile | null>(() => getCurrentUser());

  const [generatedPlan, setGeneratedPlan] = useState<LessonPlanData | null>(null);

  // Initialize view based on auth state
  const [currentView, setCurrentView] = useState<'landing' | 'auth' | 'generator' | 'dashboard' | 'saved' | 'news' | 'admin' | 'student'>(() => {
    const savedUser = getCurrentUser();
    if (savedUser) {
        return savedUser.isAdmin ? 'admin' : 'generator';
    }
    return 'landing';
  });

  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');

  const handleLogin = (profile: UserProfile) => {
    setUser(profile);
    if (profile.isAdmin) {
        setCurrentView('admin');
    } else {
        setCurrentView('generator');
    }
  };

  const handleUpdateProfile = (profile: UserProfile) => {
    updateUserProfile(profile);
    setUser(profile); // Update local state
  };

  const handleLogout = () => {
    logoutUser();
    setUser(null);
    setGeneratedPlan(null);
    setCurrentView('landing');
  };

  const navigateToAuth = (mode: 'signin' | 'signup') => {
      setAuthMode(mode);
      setCurrentView('auth');
  };

  // Handler for clicking the logo/header title
  const handleHomeClick = () => {
    if (currentView === 'student') {
        // Do nothing or maybe warn if in student mode
        return;
    }

    if (user) {
        if (user.isAdmin) {
            setCurrentView('admin');
        } else {
            setCurrentView('generator');
            setGeneratedPlan(null); // Reset generated plan view
        }
    } else {
        setCurrentView('landing');
        setGeneratedPlan(null); // Reset guest generated plan view
    }
  };

  // Special rendering for Student Portal (no header/footer usually desired, but keeping header for consistency)
  if (currentView === 'student') {
      return (
          <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
              <Header onHomeClick={() => setCurrentView('landing')} />
              <StudentPortal />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <Header onHomeClick={handleHomeClick} />

      <main className="flex-1 relative">
        {/* Navigation State Logic */}

        {/* LANDING PAGE (Unauthenticated) */}
        {currentView === 'landing' && !user && (
            <LandingPage 
                onStart={() => navigateToAuth('signup')} 
                user={user}
                onLogout={handleLogout}
                onPlanGenerated={(plan) => {
                    setGeneratedPlan(plan);
                    // Stay in a state where we show the plan, but user is null
                }} 
            />
        )}

        {/* AUTH PAGE */}
        {currentView === 'auth' && !user && (
            <Login 
                onLogin={handleLogin} 
                initialMode={authMode} 
                onStudentLoginClick={() => setCurrentView('student')}
            />
        )}

        {/* LOGGED IN NAVIGATION */}
        {user && (
            <div className={`container mx-auto px-4 py-8 md:py-12 ${currentView === 'admin' ? 'max-w-full px-0 py-0' : 'max-w-5xl'}`}>
                {/* Navigation Bar for Authenticated Users */}
                <div className={`flex flex-wrap gap-4 justify-between items-center mb-8 border-b border-gray-200 pb-4 no-print ${currentView === 'admin' ? 'px-4 pt-4' : ''}`}>
                    <div className="flex gap-2 md:gap-4 overflow-x-auto pb-2 md:pb-0">
                        {user.isAdmin ? (
                            <button
                                onClick={() => setCurrentView('admin')}
                                className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'admin' ? 'bg-slate-800 text-white' : 'text-gray-600 hover:bg-gray-100'}`}
                            >
                                <Shield className="w-4 h-4" />
                                Admin Panel
                            </button>
                        ) : (
                            <>
                                <button
                                    onClick={() => {
                                        setCurrentView('generator');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'generator' && !generatedPlan ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <FileText className="w-4 h-4" />
                                    Planner
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('saved');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'saved' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <Save className="w-4 h-4" />
                                    Saved Plans
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('news');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'news' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <Newspaper className="w-4 h-4" />
                                    News
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('dashboard');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'dashboard' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <LayoutDashboard className="w-4 h-4" />
                                    Dashboard
                                </button>
                            </>
                        )}
                    </div>

                    <div className="flex items-center gap-4">
                        <span className="text-sm text-gray-500 hidden md:inline">
                            {user.isAdmin ? 'Administrator' : `Welcome, ${user.name}`}
                        </span>
                        <button
                            onClick={handleLogout}
                            className="flex items-center gap-2 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50 rounded-md transition-colors"
                        >
                            <LogOut className="w-4 h-4" />
                            Logout
                        </button>
                    </div>
                </div>

                {/* Authenticated Views */}
                {currentView === 'admin' ? (
                    <div className="animate-fade-in">
                        <AdminDashboard />
                    </div>
                ) : currentView === 'dashboard' ? (
                    <div className="animate-fade-in">
                        <Dashboard profile={user} onUpdate={handleUpdateProfile} />
                    </div>
                ) : currentView === 'saved' ? (
                    <div className="animate-fade-in">
                        <SavedPlans onSelectPlan={(plan) => {
                            setGeneratedPlan(plan);
                            setCurrentView('generator');
                        }} />
                    </div>
                ) : currentView === 'news' ? (
                    <div className="animate-fade-in">
                        <NewsSection />
                    </div>
                ) : generatedPlan ? (
                    <div className="animate-fade-in">
                        <LessonPlanDisplay 
                            plan={generatedPlan} 
                            onBack={() => setGeneratedPlan(null)} 
                        />
                    </div>
                ) : (
                    <div className="animate-fade-in-up">
                        <div className="text-center mb-8 no-print">
                            <h2 className="text-2xl font-semibold text-gray-800">Create Your Lesson Plan</h2>
                            <p className="text-gray-600 mt-2">Fill in the details below to generate a comprehensive, curriculum-aligned lesson plan in seconds.</p>
                        </div>
                        <LessonGenerator userProfile={user} onPlanGenerated={setGeneratedPlan} />
                    </div>
                )}
            </div>
        )}

        {/* GUEST GENERATED PLAN DISPLAY (Special Case) */}
        {!user && generatedPlan && (
             <div className="container mx-auto px-4 py-8 md:py-12 max-w-5xl animate-fade-in">
                <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-6 flex justify-between items-center">
                    <p className="text-sm text-yellow-700">
                        You are viewing this plan as a guest. <strong>Sign in</strong> to save it to your account.
                    </p>
                    <button 
                        onClick={() => navigateToAuth('signin')}
                        className="text-sm font-medium text-yellow-800 underline hover:text-yellow-900"
                    >
                        Sign In Now
                    </button>
                </div>
                <LessonPlanDisplay 
                    plan={generatedPlan} 
                    onBack={() => {
                        setGeneratedPlan(null);
                        setCurrentView('landing');
                    }} 
                />
            </div>
        )}

        {/* Mwalimu Bot - Only show when logged in and not in admin view */}
        {user && !user.isAdmin && <MwalimuBot />}

      </main>

      {/* Footer only if not in landing page (Landing has its own flow or style usually, but here we can keep it consistent or simple) */}
      <footer className="bg-slate-900 text-slate-400 py-8 text-center text-sm no-print mt-auto">
        <p>© {new Date().getFullYear()} MwalimuPlanner. All Rights Reserved.</p>
        <p className="mt-1">Empowering Kenyan Educators.</p>
      </footer>
    </div>
  );
}

export default App;

import { LessonPlanData, UserProfile, Classroom, Assignment, StudentResult, Student, SharedNote } from '../types';

const PLANS_STORAGE_KEY = 'mwalimu_saved_plans';
const USERS_DB_KEY = 'mwalimu_users_db';
const SESSION_KEY = 'mwalimu_current_session';
const CLASSROOMS_STORAGE_KEY = 'mwalimu_classrooms';
const ASSIGNMENTS_STORAGE_KEY = 'mwalimu_assignments';
const RESULTS_STORAGE_KEY = 'mwalimu_results';

// --- Plan Management ---

export const savePlan = (plan: LessonPlanData): void => {
  const currentUser = getCurrentUser();
  if (!currentUser) {
    throw new Error("You must be logged in to save a plan.");
  }

  // Fetch ALL plans first (to append to the global storage)
  const allPlans = getAllGlobalPlans();

  // Ensure ID and timestamp exist
  if (!plan.id) plan.id = crypto.randomUUID();
  if (!plan.createdAt) plan.createdAt = new Date().toISOString();
  // Assign ownership
  plan.userId = currentUser.email;

  const existingIndex = allPlans.findIndex(p => p.id === plan.id);

  if (existingIndex >= 0) {
    allPlans[existingIndex] = plan;
  } else {
    allPlans.unshift(plan);
  }

  localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(allPlans));
};

// Returns plans ONLY for the current user
export const getSavedPlans = (): LessonPlanData[] => {
  const currentUser = getCurrentUser();
  if (!currentUser) return [];

  const data = localStorage.getItem(PLANS_STORAGE_KEY);
  const allPlans: LessonPlanData[] = data ? JSON.parse(data) : [];

  // Filter plans where plan.userId matches current user's email
  return allPlans.filter(plan => plan.userId === currentUser.email);
};

// Returns ALL plans (For Admin Dashboard use only)
export const getAllGlobalPlans = (): LessonPlanData[] => {
  const data = localStorage.getItem(PLANS_STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

export const deletePlan = (id: string): void => {
  const allPlans = getAllGlobalPlans();
  const updatedPlans = allPlans.filter(p => p.id !== id);
  localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(updatedPlans));
};

// --- Classroom Management ---

const generateStudentCode = (): string => {
  // Generate a 6-character alphanumeric code (e.g., A7X92P)
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Helper to check if a code is globally unique across all classrooms
const isCodeUnique = (code: string, allClassrooms: Classroom[]): boolean => {
  for (const cls of allClassrooms) {
    if (cls.students.some(s => s.code === code)) return false;
  }
  return true;
};

export const createClassroom = (grade: string, stream: string, roll: number): Classroom => {
  const currentUser = getCurrentUser();
  if (!currentUser) throw new Error("Must be logged in.");

  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  const students: Student[] = [];
  for (let i = 1; i <= roll; i++) {
    let code = generateStudentCode();
    // Ensure uniqueness
    while (!isCodeUnique(code, allClassrooms)) {
      code = generateStudentCode();
    }
    students.push({
      index: i,
      code: code
    });
  }

  const newClassroom: Classroom = {
    id: crypto.randomUUID(),
    userId: currentUser.email,
    grade,
    stream,
    subjects: [], // Starts with no subjects
    students: students,
    sharedNotes: []
  };

  allClassrooms.push(newClassroom);
  localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
  return newClassroom;
};

export const addSubjectToClassroom = (classId: string, subject: string): void => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  const clsIndex = allClassrooms.findIndex(c => c.id === classId);
  if (clsIndex !== -1) {
    if (!allClassrooms[clsIndex].subjects.includes(subject)) {
        allClassrooms[clsIndex].subjects.push(subject);
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
  }
};

export const removeSubjectFromClassroom = (classId: string, subject: string): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
      allClassrooms[clsIndex].subjects = allClassrooms[clsIndex].subjects.filter(s => s !== subject);
      localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
};

export const shareNoteToClassroom = (classId: string, note: SharedNote): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
        if (!allClassrooms[clsIndex].sharedNotes) {
            allClassrooms[clsIndex].sharedNotes = [];
        }
        allClassrooms[clsIndex].sharedNotes.push(note);
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
};

export const getStudentNotes = (classId: string): SharedNote[] => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const cls = allClassrooms.find(c => c.id === classId);
    return cls && cls.sharedNotes ? cls.sharedNotes.sort((a,b) => new Date(b.dateShared).getTime() - new Date(a.dateShared).getTime()) : [];
};

export const getClassrooms = (): Classroom[] => {
  const currentUser = getCurrentUser();
  if (!currentUser) return [];

  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  return allClassrooms.filter(c => c.userId === currentUser.email);
};

// Admin helper to get ALL classrooms
export const getAllClassroomsGlobal = (): Classroom[] => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
};

export const deleteClassroom = (id: string): void => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  const updatedClassrooms = allClassrooms.filter(c => c.id !== id);
  localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(updatedClassrooms));

  // Also delete assignments associated with this classroom
  const assignData = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  if (assignData) {
      const assignments: Assignment[] = JSON.parse(assignData);
      const updatedAssignments = assignments.filter(a => a.classroomId !== id);
      localStorage.setItem(ASSIGNMENTS_STORAGE_KEY, JSON.stringify(updatedAssignments));
  }
};

// --- Assignment Management ---

export const saveAssignment = (assignment: Assignment): void => {
  const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  const assignments: Assignment[] = data ? JSON.parse(data) : [];
  assignments.push(assignment);
  localStorage.setItem(ASSIGNMENTS_STORAGE_KEY, JSON.stringify(assignments));
};

export const getAssignmentsByClassId = (classId: string): Assignment[] => {
  const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  const assignments: Assignment[] = data ? JSON.parse(data) : [];
  return assignments.filter(a => a.classroomId === classId);
};

// Admin helper for all assignments
export const getAllAssignmentsGlobal = (): Assignment[] => {
    const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
};

// --- Student Login & Results ---

export const authenticateStudent = (code: string): { student: Student, classroom: Classroom } | null => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  // Find the classroom that contains a student with this code
  for (const cls of allClassrooms) {
    const student = cls.students.find(s => s.code === code);
    if (student) {
      return { student, classroom: cls };
    }
  }
  return null;
};

export const updateStudentName = (classId: string, studentCode: string, name: string): Student | null => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex === -1) return null;

    const studentIndex = allClassrooms[clsIndex].students.findIndex(s => s.code === studentCode);
    if (studentIndex === -1) return null;

    // Update name
    allClassrooms[clsIndex].students[studentIndex].name = name;
    localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));

    return allClassrooms[clsIndex].students[studentIndex];
};

export const saveStudentResult = (result: StudentResult): void => {
  const data = localStorage.getItem(RESULTS_STORAGE_KEY);
  const results: StudentResult[] = data ? JSON.parse(data) : [];

  // Find existing results for this assignment and student to determine attempt number
  const priorAttempts = results.filter(r => r.assignmentId === result.assignmentId && r.studentCode === result.studentCode);

  // Set attempt number
  result.attempts = priorAttempts.length + 1;

  // Always push a NEW result for history
  results.push(result);

  localStorage.setItem(RESULTS_STORAGE_KEY, JSON.stringify(results));
};

export const getStudentResults = (studentCode: string): StudentResult[] => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    // Return all attempts, sorted by date (newest first)
    return results.filter(r => r.studentCode === studentCode).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
};

export const getAssignmentResults = (assignmentId: string): StudentResult[] => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    // Returns all attempts for an assignment
    return results.filter(r => r.assignmentId === assignmentId).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
};

export const updateStudentResultFeedback = (resultId: string, feedback: string): void => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    const index = results.findIndex(r => r.id === resultId);

    if (index !== -1) {
        results[index].feedback = feedback;
        localStorage.setItem(RESULTS_STORAGE_KEY, JSON.stringify(results));
    }
};

// --- User Authentication & Management ---

const getUsers = (): UserProfile[] => {
  const data = localStorage.getItem(USERS_DB_KEY);
  return data ? JSON.parse(data) : [];
};

export const getAllUsers = (): UserProfile[] => {
  return getUsers();
};

export const registerUser = (user: UserProfile): UserProfile => {
  const users = getUsers();

  // Check if email already exists
  if (users.some(u => u.email.toLowerCase() === user.email.toLowerCase())) {
    throw new Error('An account with this email already exists.');
  }

  // Regular users are not admins
  user.isAdmin = false;

  users.push(user);
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

  // Auto login after registration
  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const loginUser = (email: string, password: string): UserProfile => {
  // Hardcoded Admin Check
  if (email === 'admin@mwalimuplanner.com' && password === 'admin123') {
    const adminUser: UserProfile = {
      name: 'System Administrator',
      email: 'admin@mwalimuplanner.com',
      school: 'HQ',
      phone: '0000000000',
      isAdmin: true
    };
    localStorage.setItem(SESSION_KEY, JSON.stringify(adminUser));
    return adminUser;
  }

  const users = getUsers();
  const user = users.find(u => 
    u.email.toLowerCase() === email.toLowerCase() && 
    u.password === password
  );

  if (!user) {
    throw new Error('Invalid email or password.');
  }

  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const logoutUser = (): void => {
  localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = (): UserProfile | null => {
  const data = localStorage.getItem(SESSION_KEY);
  return data ? JSON.parse(data) : null;
};

export const updateUserProfile = (updatedProfile: UserProfile): void => {
  const users = getUsers();
  const index = users.findIndex(u => u.email === updatedProfile.email);

  if (index !== -1) {
    // Preserve password if not provided in update
    const existingUser = users[index];
    users[index] = { ...existingUser, ...updatedProfile };

    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
    localStorage.setItem(SESSION_KEY, JSON.stringify(users[index]));
  }
};

export const resetUserPassword = (email: string, newPass: string): boolean => {
    const users = getUsers();
    const index = users.findIndex(u => u.email.toLowerCase() === email.toLowerCase());

    if (index !== -1) {
        users[index].password = newPass;
        localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
        return true;
    }
    return false;
};

