import React, { useState } from 'react';
import { Classroom, Assignment, StudentResult, Student, QuizQuestion, SharedNote } from '../types';
import { authenticateStudent, getAssignmentsByClassId, saveStudentResult, updateStudentName, getStudentResults, getStudentNotes } from '../services/storageService';
import { generateSimilarQuestions } from '../services/geminiService';
import { BookOpen, Check, ChevronRight, GraduationCap, LogIn, AlertCircle, Key, ArrowLeft, LayoutDashboard, Clock, CheckCircle2, XCircle, RotateCcw, Menu, Bell, ChevronDown, FileText, List, User, LogOut, MessageSquare, Loader2, StickyNote } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'enterName' | 'dashboard' | 'assignments' | 'results' | 'quiz' | 'revision' | 'notes'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [studentNameInput, setStudentNameInput] = useState('');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Session State
  const [currentStudent, setCurrentStudent] = useState<Student | null>(null);
  const [currentClassroom, setCurrentClassroom] = useState<Classroom | null>(null);
  const [classAssignments, setClassAssignments] = useState<Assignment[]>([]);
  const [completedResults, setCompletedResults] = useState<StudentResult[]>([]);
  const [classNotes, setClassNotes] = useState<SharedNote[]>([]);
  const [selectedNote, setSelectedNote] = useState<SharedNote | null>(null);

  // Active Quiz/Revision State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]); // To hold current set (original or regenerated)
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizResult, setQuizResult] = useState<StudentResult | null>(null);

  const [loadingQuiz, setLoadingQuiz] = useState(false);
  const [error, setError] = useState('');

  // Helper
  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');
  const cleanText = (text: string) => text.replace(/[*#]/g, '');

  // --- Auth Flow ---

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!accessCode) {
        setError("Please enter your Access Code.");
        return;
    }

    const authResult = authenticateStudent(accessCode.toUpperCase());
    if (authResult) {
        setCurrentStudent(authResult.student);
        setCurrentClassroom(authResult.classroom);

        if (!authResult.student.name) {
            setView('enterName');
        } else {
            loadStudentData(authResult.student, authResult.classroom);
            setView('dashboard');
        }
        setAccessCode('');
    } else {
        setError("Invalid Access Code. Please check and try again.");
    }
  };

  const handleNameSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (!studentNameInput.trim() || !currentClassroom || !currentStudent) return;

      const updatedStudent = updateStudentName(currentClassroom.id, currentStudent.code, studentNameInput.trim());
      if (updatedStudent) {
          setCurrentStudent(updatedStudent);
          loadStudentData(updatedStudent, currentClassroom);
          setView('dashboard');
      }
  };

  const loadStudentData = (student: Student, classroom: Classroom) => {
      const allTasks = getAssignmentsByClassId(classroom.id);
      const results = getStudentResults(student.code);
      const notes = getStudentNotes(classroom.id);
      setClassAssignments(allTasks);
      setCompletedResults(results);
      setClassNotes(notes);
  };

  const handleLogout = () => {
      setCurrentStudent(null);
      setCurrentClassroom(null);
      setView('login');
      setStudentNameInput('');
      setSelectedAnswers({});
  };

  const upcomingAssignments = classAssignments.filter(a => 
      !completedResults.some(r => r.assignmentId === a.id)
  );

  const getAssignmentById = (id: string) => classAssignments.find(a => a.id === id);

  const startAssignment = async (assignment: Assignment, isReattempt = false) => {
      setLoadingQuiz(true);
      setActiveAssignment(assignment);

      try {
          if (isReattempt && assignment.grade) {
              // Generate new similar questions
              const newQuestions = await generateSimilarQuestions(assignment.topic, assignment.subject, assignment.grade);
              setQuizQuestions(newQuestions);
          } else {
              // Use original questions
              setQuizQuestions(assignment.questions);
          }

          setCurrentQuestionIndex(0);
          setSelectedAnswers({});
          setQuizResult(null);
          setView('quiz');
      } catch (err) {
          alert("Could not load questions. Please try again.");
      } finally {
          setLoadingQuiz(false);
      }
  };

  const handleAnswerSelect = (option: string) => {
      setSelectedAnswers(prev => ({ ...prev, [currentQuestionIndex]: option }));
  };

  const nextQuestion = () => {
      if (activeAssignment && currentQuestionIndex < quizQuestions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const submitQuiz = () => {
      if (!activeAssignment || !currentStudent) return;

      let score = 0;
      quizQuestions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx]?.toLowerCase().trim() || "";
          const correct = q.correctAnswer.toLowerCase().trim();

          // Basic exact match check (improve with fuzzy logic if needed later)
          if (userAnswer === correct || (q.type === 'mcq' && userAnswer === correct)) {
              score++;
          }
      });

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: currentStudent.code,
          studentName: currentStudent.name || `Index ${currentStudent.index}`,
          score: score,
          total: quizQuestions.length,
          attempts: 1, // Logic handled in saveStudentResult
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);

      // Update local state to reflect new attempt count/score
      setCompletedResults(getStudentResults(currentStudent.code));

      // Get the latest result object (with updated attempt count)
      const updatedResults = getStudentResults(currentStudent.code);
      // We want the one we just saved, which is the newest one for this assignment
      const latestResult = updatedResults.find(r => r.id === result.id) || result;

      setQuizResult(latestResult);
      setView('result'); // Shows summary
  };

  const viewRevision = (result: StudentResult) => {
      const assignment = getAssignmentById(result.assignmentId);
      if (assignment) {
          setActiveAssignment(assignment);
          // For revision, we rely on assignment questions. 
          // Note: If questions were re-generated dynamically, perfect historical view is hard without storing Qs in result.
          setQuizQuestions(assignment.questions); 
          setQuizResult(result);
          setView('revision');
      }
  };

  // Stats for Dashboard
  const avgScore = completedResults.length > 0 
    ? Math.round(completedResults.reduce((acc, curr) => acc + (curr.score/curr.total)*100, 0) / completedResults.length) 
    : 0;

  // Render Login Views
  if (view === 'login') {
      return (
        <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
            <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
                <div className="text-center mb-8">
                    <div className="w-16 h-16 bg-slate-900 text-teal-400 rounded-full flex items-center justify-center mx-auto mb-4">
                        <GraduationCap className="w-8 h-8" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                    <p className="text-gray-500">Enter your access code</p>
                </div>
                {error && <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 flex items-center gap-2"><AlertCircle className="w-4 h-4" /> {error}</div>}
                <form onSubmit={handleLogin} className="space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                        <div className="relative">
                            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none"><Key className="h-5 w-5 text-gray-400" /></div>
                            <input type="text" value={accessCode} onChange={(e) => setAccessCode(e.target.value.toUpperCase())} className="w-full pl-10 px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 text-center text-lg uppercase tracking-widest font-mono" placeholder="XXXXXX" maxLength={6} />
                        </div>
                    </div>
                    <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800 transition-colors shadow-md">Enter Dashboard</button>
                </form>
            </div>
        </div>
      );
  }

  if (view === 'enterName') {
      return (
          <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
              <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full border border-slate-200">
                  <div className="text-center mb-6">
                      <h2 className="text-2xl font-bold text-gray-800">Welcome!</h2>
                      <p className="text-gray-500">Please enter your full name.</p>
                  </div>
                  <form onSubmit={handleNameSubmit} className="space-y-6">
                      <input type="text" required value={studentNameInput} onChange={(e) => setStudentNameInput(e.target.value)} className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500" placeholder="e.g. John Kamau" />
                      <button type="submit" className="w-full bg-slate-900 text-white py-3 rounded-lg font-bold hover:bg-slate-800">Continue</button>
                  </form>
              </div>
          </div>
      );
  }

  // LOGGED IN DASHBOARD LAYOUT
  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">

        {/* Sidebar */}
        <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-slate-300 transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 shadow-xl`}>
            <div className="flex items-center h-16 px-6 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800">
                <GraduationCap className="w-6 h-6 mr-2 text-teal-500" />
                Student<span className="text-teal-500">Portal</span>
            </div>
            <div className="p-4">
                <div className="bg-slate-800 rounded p-3 mb-6">
                    <p className="text-xs text-slate-400 uppercase tracking-wider">Class</p>
                    <p className="font-bold text-white">{currentClassroom?.grade} - {currentClassroom?.stream}</p>
                </div>
                <nav className="space-y-2">
                    <button onClick={() => setView('dashboard')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'dashboard' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <LayoutDashboard className="w-5 h-5 mr-3" /> Overview
                    </button>
                    <button onClick={() => setView('assignments')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'assignments' || view === 'quiz' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <FileText className="w-5 h-5 mr-3" /> Assignments
                        {upcomingAssignments.length > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] px-1.5 py-0.5 rounded-full">{upcomingAssignments.length}</span>}
                    </button>
                    <button onClick={() => setView('results')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'results' || view === 'revision' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <List className="w-5 h-5 mr-3" /> Results
                    </button>
                    <button onClick={() => setView('notes')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${view === 'notes' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}>
                        <StickyNote className="w-5 h-5 mr-3" /> Class Notes
                    </button>
                </nav>
            </div>
            <div className="absolute bottom-0 w-full p-4 border-t border-slate-800">
                <button onClick={handleLogout} className="flex items-center w-full px-4 py-2 text-sm text-slate-400 hover:text-red-400 transition-colors">
                    <LogOut className="w-4 h-4 mr-3" /> Sign Out
                </button>
            </div>
        </aside>

        {/* Main Content */}
        <div className={`flex-1 flex flex-col transition-all duration-300 ${sidebarOpen ? 'lg:ml-64' : ''}`}>

            {/* Header */}
            <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 sticky top-0 z-40 shadow-sm">
                <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500"><Menu className="w-6 h-6" /></button>
                <div className="flex items-center gap-4 ml-auto">
                    <div className="flex items-center gap-2 pl-4 border-l border-gray-200">
                        <div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center text-xs font-bold">{currentStudent?.name?.charAt(0)}</div>
                        <span className="text-sm font-medium text-gray-700 hidden md:block">{currentStudent?.name}</span>
                    </div>
                </div>
            </header>

            <main className="p-4 lg:p-8">
                {/* Yellow Alert */}
                <div className="bg-amber-100 border-l-4 border-amber-500 text-amber-800 p-4 mb-8 rounded-r shadow-sm flex items-start gap-3">
                    <span className="bg-amber-200 p-1 rounded text-amber-700 font-bold px-2">i</span>
