import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import LessonGenerator from './components/LessonGenerator';
import LessonPlanDisplay from './components/LessonPlanDisplay';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import LandingPage from './components/LandingPage';
import SavedPlans from './components/SavedPlans';
import NewsSection from './components/NewsSection';
import AdminDashboard from './components/AdminDashboard';
import StudentPortal from './components/StudentPortal';
import MwalimuBot from './components/MwalimuBot';
import { LessonPlanData, UserProfile } from './types';
import { LayoutDashboard, FileText, LogOut, Save, Newspaper, Shield } from 'lucide-react';
import { getCurrentUser, logoutUser, updateUserProfile } from './services/storageService';

function App() {
  // Initialize user state directly from storage to persist login across reloads/updates
  const [user, setUser] = useState<UserProfile | null>(() => getCurrentUser());

  const [generatedPlan, setGeneratedPlan] = useState<LessonPlanData | null>(null);

  // Initialize view based on auth state
  const [currentView, setCurrentView] = useState<'landing' | 'auth' | 'generator' | 'dashboard' | 'saved' | 'news' | 'admin' | 'student'>(() => {
    const savedUser = getCurrentUser();
    if (savedUser) {
        return savedUser.isAdmin ? 'admin' : 'generator';
    }
    return 'landing';
  });

  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');

  const handleLogin = (profile: UserProfile) => {
    setUser(profile);
    if (profile.isAdmin) {
        setCurrentView('admin');
    } else {
        setCurrentView('generator');
    }
  };

  const handleUpdateProfile = (profile: UserProfile) => {
    updateUserProfile(profile);
    setUser(profile); // Update local state
  };

  const handleLogout = () => {
    logoutUser();
    setUser(null);
    setGeneratedPlan(null);
    setCurrentView('landing');
  };

  const navigateToAuth = (mode: 'signin' | 'signup') => {
      setAuthMode(mode);
      setCurrentView('auth');
  };

  // Handler for clicking the logo/header title
  const handleHomeClick = () => {
    if (currentView === 'student') {
        // Do nothing or maybe warn if in student mode
        return;
    }

    if (user) {
        if (user.isAdmin) {
            setCurrentView('admin');
        } else {
            setCurrentView('generator');
            setGeneratedPlan(null); // Reset generated plan view
        }
    } else {
        setCurrentView('landing');
        setGeneratedPlan(null); // Reset guest generated plan view
    }
  };

  // Special rendering for Student Portal (no header/footer usually desired, but keeping header for consistency)
  if (currentView === 'student') {
      return (
          <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
              <Header onHomeClick={() => setCurrentView('landing')} />
              <StudentPortal />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <Header onHomeClick={handleHomeClick} />

      <main className="flex-1 relative">
        {/* Navigation State Logic */}

        {/* LANDING PAGE (Unauthenticated) */}
        {currentView === 'landing' && !user && (
            <LandingPage 
                onStart={() => navigateToAuth('signup')} 
                user={user}
                onLogout={handleLogout}
                onPlanGenerated={(plan) => {
                    setGeneratedPlan(plan);
                    // Stay in a state where we show the plan, but user is null
                }} 
            />
        )}

        {/* AUTH PAGE */}
        {currentView === 'auth' && !user && (
            <Login 
                onLogin={handleLogin} 
                initialMode={authMode} 
                onStudentLoginClick={() => setCurrentView('student')}
            />
        )}

        {/* LOGGED IN NAVIGATION */}
        {user && (
            <div className={`container mx-auto px-4 py-8 md:py-12 ${currentView === 'admin' ? 'max-w-full px-0 py-0' : 'max-w-5xl'}`}>
                {/* Navigation Bar for Authenticated Users */}
                <div className={`flex flex-wrap gap-4 justify-between items-center mb-8 border-b border-gray-200 pb-4 no-print ${currentView === 'admin' ? 'px-4 pt-4' : ''}`}>
                    <div className="flex gap-2 md:gap-4 overflow-x-auto pb-2 md:pb-0">
                        {user.isAdmin ? (
                            <button
                                onClick={() => setCurrentView('admin')}
                                className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'admin' ? 'bg-slate-800 text-white' : 'text-gray-600 hover:bg-gray-100'}`}
                            >
                                <Shield className="w-4 h-4" />
                                Admin Panel
                            </button>
                        ) : (
                            <>
                                <button
                                    onClick={() => {
                                        setCurrentView('generator');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'generator' && !generatedPlan ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <FileText className="w-4 h-4" />
                                    Planner
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('saved');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'saved' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <Save className="w-4 h-4" />
                                    Generated Plans
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('news');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'news' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <Newspaper className="w-4 h-4" />
                                    News
                                </button>
                                <button
                                    onClick={() => {
                                        setCurrentView('dashboard');
                                        setGeneratedPlan(null);
                                    }}
                                    className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'dashboard' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}
                                >
                                    <LayoutDashboard className="w-4 h-4" />
                                    Dashboard
                                </button>
                            </>
                        )}
                    </div>

                    <div className="flex items-center gap-4">
                        <span className="text-sm text-gray-500 hidden md:inline">
                            {user.isAdmin ? 'Administrator' : `Welcome, ${user.name}`}
                        </span>
                        <button
                            onClick={handleLogout}
                            className="flex items-center gap-2 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50 rounded-md transition-colors"
                        >
                            <LogOut className="w-4 h-4" />
                            Logout
                        </button>
                    </div>
                </div>

                {/* Authenticated Views */}
                {currentView === 'admin' ? (
                    <div className="animate-fade-in">
                        <AdminDashboard />
                    </div>
                ) : currentView === 'dashboard' ? (
                    <div className="animate-fade-in">
                        <Dashboard profile={user} onUpdate={handleUpdateProfile} />
                    </div>
                ) : currentView === 'saved' ? (
                    <div className="animate-fade-in">
                        <SavedPlans onSelectPlan={(plan) => {
                            setGeneratedPlan(plan);
                            setCurrentView('generator');
                        }} />
                    </div>
                ) : currentView === 'news' ? (
                    <div className="animate-fade-in">
                        <NewsSection />
                    </div>
                ) : generatedPlan ? (
                    <div className="animate-fade-in">
                        <LessonPlanDisplay 
                            plan={generatedPlan} 
                            onBack={() => setGeneratedPlan(null)} 
                        />
                    </div>
                ) : (
                    <div className="animate-fade-in-up">
                        <div className="text-center mb-8 no-print">
                            <h2 className="text-2xl font-semibold text-gray-800">Create Your Lesson Plan</h2>
                            <p className="text-gray-600 mt-2">Fill in the details below to generate a comprehensive, curriculum-aligned lesson plan in seconds.</p>
                        </div>
                        <LessonGenerator userProfile={user} onPlanGenerated={setGeneratedPlan} />
                    </div>
                )}
            </div>
        )}

        {/* GUEST GENERATED PLAN DISPLAY (Special Case) */}
        {!user && generatedPlan && (
             <div className="container mx-auto px-4 py-8 md:py-12 max-w-5xl animate-fade-in">
                <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-6 flex justify-between items-center">
                    <p className="text-sm text-yellow-700">
                        You are viewing this plan as a guest. <strong>Sign in</strong> to save it to your account.
                    </p>
                    <button 
                        onClick={() => navigateToAuth('signin')}
                        className="text-sm font-medium text-yellow-800 underline hover:text-yellow-900"
                    >
                        Sign In Now
                    </button>
                </div>
                <LessonPlanDisplay 
                    plan={generatedPlan} 
                    onBack={() => {
                        setGeneratedPlan(null);
                        setCurrentView('landing');
                    }} 
                />
            </div>
        )}

        {/* Mwalimu Bot - Only show when logged in and not in admin view */}
        {user && !user.isAdmin && <MwalimuBot />}

      </main>

      {/* Footer only if not in landing page (Landing has its own flow or style usually, but here we can keep it consistent or simple) */}
      <footer className="bg-slate-900 text-slate-400 py-8 text-center text-sm no-print mt-auto">
        <p>© {new Date().getFullYear()} MwalimuPlanner. All Rights Reserved.</p>
        <p className="mt-1">Empowering Kenyan Educators.</p>
      </footer>
    </div>
  );
}

